import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock database functions - in a real app these would connect to a database
const customers = [
  { id: "1", name: "John Doe", email: "john@example.com", phone: "123-456-7890", points: 150 },
  { id: "2", name: "Jane Smith", email: "jane@example.com", phone: "098-765-4321", points: 200 }
];

const findCustomerIndex = (id: string) => customers.findIndex(customer => customer.id === id);

// Get all customers
router.get("/customers", (req: Request, res: Response) => {
  res.json(customers);
});

// Get a customer by ID
router.get("/customers/:id", (req: Request, res: Response) => {
  const customer = customers.find(c => c.id === req.params.id);
  if (!customer) {
    return res.status(404).json({ error: "Customer not found" });
  }
  res.json(customer);
});

// Create a new customer
router.post("/customers", (req: Request, res: Response) => {
  const { name, email, phone, points } = req.body;

  if (!name || !email || !phone) {
    return res.status(400).json({ error: "Name, email, and phone are required" });
  }

  const newCustomer = {
    id: String(customers.length + 1),
    name,
    email,
    phone,
    points: points || 0
  };

  customers.push(newCustomer);
  res.status(201).json(newCustomer);
});

// Update a customer
router.put("/customers/:id", (req: Request, res: Response) => {
  const index = findCustomerIndex(req.params.id);

  if (index === -1) {
    return res.status(404).json({ error: "Customer not found" });
  }

  const { name, email, phone, points } = req.body;

  if (!name || !email || !phone) {
    return res.status(400).json({ error: "Name, email, and phone are required" });
  }

  customers[index] = {
    ...customers[index],
    name,
    email,
    phone,
    points: points !== undefined ? points : customers[index].points
  };

  res.json(customers[index]);
});

// Delete a customer
router.delete("/customers/:id", (req: Request, res: Response) => {
  const index = findCustomerIndex(req.params.id);

  if (index === -1) {
    return res.status(404).json({ error: "Customer not found" });
  }

  customers.splice(index, 1);
  res.json({ message: "Customer deleted successfully" });
});

