import { useEffect, useState } from "react";

interface Customer {
  id: number;
  name: string;
  email: string;
  loyaltyPoints: number;
}

export function CustomerListPage() {
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchCustomers();
  }, []);

  const fetchCustomers = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/customers');
      if (!response.ok) {
        throw new Error('Failed to fetch customers');
      }
      const data = await response.json();
      setCustomers(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  if (customers.length === 0) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>No customers found.</div>;
  }

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Customer List</h1>
      <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
        {customers.map(customer => (
          <div 
            key={customer.id} 
            style={{ 
              border: '1px solid #ccc', 
              borderRadius: '8px', 
              padding: '15px', 
              display: 'flex', 
              justifyContent: 'space-between', 
              alignItems: 'center'
            }}
          >
            <div>
              <h3>{customer.name}</h3>
              <p>Email: {customer.email}</p>
              <p>Loyalty Points: {customer.loyaltyPoints}</p>
            </div>
            <div>
              <button 
                style={{ 
                  backgroundColor: '#007bff', 
                  color: 'white', 
                  border: 'none', 
                  borderRadius: '4px', 
                  padding: '8px 12px', 
                  cursor: 'pointer'
                }}
                onClick={() => {
                  // In a real app, this would navigate to a customer detail/edit page
                  alert(`Viewing details for ${customer.name}`);
                }}
              >
                View Details
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

