export function StaffParcelManagement() {
  const [parcels, setParcels] = useState<Parcel[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [newEvent, setNewEvent] = useState({
    parcelId: '',
    event: '',
  });
  const [statusUpdate, setStatusUpdate] = useState({
    parcelId: '',
    status: '',
  });

  useEffect(() => {
    fetchParcels();
  }, []);

  const fetchParcels = async () => {
    try {
      const response = await fetch('/api/parcels');
      if (!response.ok) throw new Error('Failed to fetch parcels');
      const data = await response.json();
      setParcels(data);
      setLoading(false);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
      setLoading(false);
    }
  };

  const handleAddTrackingEvent = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch('/api/tracking-events', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(newEvent),
      });
      if (!response.ok) throw new Error('Failed to add tracking event');
      setNewEvent({ parcelId: '', event: '' });
      fetchParcels();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleUpdateStatus = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch(`/api/parcels/${statusUpdate.parcelId}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ status: statusUpdate.status }),
      });
      if (!response.ok) throw new Error('Failed to update status');
      setStatusUpdate({ parcelId: '', status: '' });
      fetchParcels();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;

  if (error) return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Staff Parcel Management</h1>

      <div style={{ marginBottom: '30px' }}>
        <h2>Add Tracking Event</h2>
        <form onSubmit={handleAddTrackingEvent} style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
          <input
            type="text"
            placeholder="Parcel ID"
            value={newEvent.parcelId}
            onChange={(e) => setNewEvent({...newEvent, parcelId: e.target.value})}
            style={{ width: '100%', padding: '8px' }}
          />
          <input
            type="text"
            placeholder="Event Description"
            value={newEvent.event}
            onChange={(e) => setNewEvent({...newEvent, event: e.target.value})}
            style={{ width: '100%', padding: '8px' }}
          />
          <button type="submit" style={{ padding: '10px', backgroundColor: '#007bff', color: 'white', border: 'none', borderRadius: '4px' }}>
            Add Event
          </button>
        </form>
      </div>

      <div style={{ marginBottom: '30px' }}>
        <h2>Update Parcel Status</h2>
        <form onSubmit={handleUpdateStatus} style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
          <input
            type="text"
            placeholder="Parcel ID"
            value={statusUpdate.parcelId}
            onChange={(e) => setStatusUpdate({...statusUpdate, parcelId: e.target.value})}
            style={{ width: '100%', padding: '8px' }}
          />
          <select
            value={statusUpdate.status}
            onChange={(e) => setStatusUpdate({...statusUpdate, status: e.target.value})}
            style={{ width: '100%', padding: '8px' }}
          >
            <option value="">Select Status</option>
            <option value="pending">Pending</option>
            <option value="in-transit">In Transit</option>
            <option value="delivered">Delivered</option>
            <option value="returned">Returned</option>
          </select>
          <button type="submit" style={{ padding: '10px', backgroundColor: '#28a745', color: 'white', border: 'none', borderRadius: '4px' }}>
            Update Status
          </button>
        </form>
      </div>

      <h2>Parcel List</h2>
      {parcels.length === 0 ? (
        <p style={{ textAlign: 'center', padding: '20px' }}>No parcels found.</p>
      ) : (
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: '20px' }}>
          {parcels.map(parcel => (
            <div key={parcel.id} style={{
              border: '1px solid #ccc',
              borderRadius: '8px',
              padding: '15px',
              width: '100%',
              maxWidth: '300px'
            }}>
              <h3>{parcel.trackingNumber}</h3>
              <p><strong>Status:</strong> {parcel.status}</p>
              <p><strong>Recipient:</strong> {parcel.recipientName}</p>
              <p><strong>Address:</strong> {parcel.recipientAddress}</p>
              <p><strong>Weight:</strong> {parcel.weight}kg</p>
