  { id: 2, name: "Dance Competition", description: "Group dance performance", date: "2023-12-02", location: "Auditorium" }
];

let nextId = 3;

// Get all events
router.get("/events", (req: Request, res: Response) => {
  res.json(events);
});

// Get event by ID
router.get("/events/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const event = events.find(e => e.id === id);

  if (!event) {
