import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to /login endpoint
  if (!(req.method === "POST" && req.path === "/login")) {
    next();
    return;
  }

  const jwtSecret = process.env.JWT_SECRET;

  if (!jwtSecret) {
    res.status(500).json({ error: "JWT secret not configured" });
    return;
  }

  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Missing or invalid authorization header" });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '

  try {
    // Simple verification of token format (base64url encoded)
    const [header, payload, signature] = token.split(".");

    if (!header || !payload || !signature) {
      res.status(401).json({ error: "Invalid token format" });
      return;
    }

    // Verify signature using HMAC-SHA256
    const expectedSignature = createHmac("sha256", jwtSecret)
      .update(`${header}.${payload}`)
      .digest("base64url");

    // Use timingSafeEqual to prevent timing attacks
    const isValid = timingSafeEqual(
      Buffer.from(signature, "base64url"),
      Buffer.from(expectedSignature, "base64url")
    );

    if (!isValid) {
      res.status(401).json({ error: "Invalid token signature" });
      return;
    }

    // If we get here, token is valid
    next();
  } catch (error) {
    res.status(401).json({ error: "Token verification failed" });
  }
}

import type { Request, Response, NextFunction } from "express";
import { createHash, scryptSync, randomBytes, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // This middleware is designed to handle password hashing for user registration
  // It should only process POST requests to the /register endpoint
  if (req.method !== "POST" || req.path !== "/register") {
    next();
    return;
  }

  // Check if password exists in request body
  if (!req.body || typeof req.body.password !== "string") {
    next();
    return;
  }

  // Hash the password using scrypt
  const salt = randomBytes(16).toString("hex");
  const key = scryptSync(req.body.password, salt, 32);
  const hashedPassword = key.toString("hex");

  // Replace the password with the hashed version
  req.body.password = hashedPassword;
  req.body.salt = salt;

  next();
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to POST requests to /register
  if (req.method !== "POST" || req.path !== "/register") {
    next();
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error: JWT_SECRET not set" });
    return;
  }

  // Simple token validation (in a real app, you'd decode and verify properly)
  const [payload, signature] = token.split(".");
  if (!payload || !signature) {
    res.status(401).json({ error: "Unauthorized: Invalid token format" });
    return;
  }

  // Create expected signature
  const expectedSignature = createHmac("sha256", secret)
    .update(payload)
    .digest("base64url");

  // Use timingSafeEqual to prevent timing attacks
  const expectedBuffer = Buffer.from(expectedSignature);
  const actualBuffer = Buffer.from(signature);

  if (expectedBuffer.length !== actualBuffer.length || 
      !timingSafeEqual(expectedBuffer, actualBuffer)) {
    res.status(401).json({ error: "Unauthorized: Invalid token signature" });
    return;
  }

  // In a real implementation, we would decode the payload here
  // For now, we'll just check if the role is present in the payload
  // This is a simplified version - in practice, you'd parse the JWT properly
  try {
    const decodedPayload = JSON.parse(Buffer.from(payload, "base64url").toString());
    const userRole = decodedPayload.role;

    if (!userRole) {
      res.status(403).json({ error: "Forbidden: Role not specified in token" });
      return;
    }

    // Allow only staff to register students
    if (userRole === "staff") {
      next();
    } else if (userRole === "student") {
      res.status(403).json({ error: "Forbidden: Students cannot register other students" });
    } else {
      res.status(403).json({ error: "Forbidden: Unknown role" });
    }
  } catch (err) {
    res.status(401).json({ error: "Unauthorized: Invalid token payload" });
  }
}

