import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

// Define the role requirements for different HTTP methods
const roleRequirements: Record<string, string[]> = {
  POST: ["admin"],
  PUT: ["admin"],
  DELETE: ["admin"],
  PATCH: ["admin"],
};

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to specific routes and methods
  const allowedPaths = ["/leave-applications"];
  const isProtectedPath = allowedPaths.some(path =>
    req.path.startsWith(path)
  );

  if (!isProtectedPath || !roleRequirements.hasOwnProperty(req.method)) {
    next();
    return;
  }

  // Get the authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res
      .status(500)
      .json({ error: "Internal Server Error: JWT_SECRET not configured" });
    return;
  }

  // Simple token validation (in a real app, you'd decode and verify properly)
  try {
    const [payload, signature] = token.split(".");
    if (!payload || !signature) {
      res.status(401).json({ error: "Unauthorized: Invalid token format" });
      return;
    }

    // Create expected signature
    const expectedSignature = createHmac("sha256", secret)
      .update(payload)
      .digest("hex");

    // Use timingSafeEqual to prevent timing attacks
    const signatureBuffer = Buffer.from(signature, "hex");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "hex");

    if (
      signatureBuffer.length !== expectedSignatureBuffer.length ||
      !timingSafeEqual(signatureBuffer, expectedSignatureBuffer)
    ) {
      res.status(401).json({ error: "Unauthorized: Invalid token" });
      return;
    }

    // In a real implementation, decode the payload to get user role
    // For now, we'll simulate role extraction
    const decodedPayload = JSON.parse(
      Buffer.from(payload, "base64").toString()
    );

    const userRole = decodedPayload.role;
    const requiredRoles = roleRequirements[req.method] || [];

    if (!requiredRoles.includes(userRole)) {
      res
        .status(403)
        .json({ error: "Forbidden: Insufficient permissions" });
      return;
    }

    next();
  } catch (error) {
    res.status(401).json({ error: "Unauthorized: Invalid token" });
  }
}

import type { Request, Response, NextFunction } from "express";
import { createHash, scrypt, randomBytes, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // This middleware is designed to handle password hashing for user registration
  // It should only process POST requests to the /register endpoint
  if (req.method !== "POST" || req.path !== "/register") {
    next();
    return;
  }

  // Check if password exists in request body
  if (!req.body || typeof req.body.password !== "string") {
    next();
    return;
  }

  const password = req.body.password;

  // Generate salt
  const salt = randomBytes(16).toString("hex");

  // Hash password with scrypt
  scrypt(password, salt, 64, (err, derivedKey) => {
    if (err) {
      next(err);
      return;
    }

    // Store hashed password and salt
    req.body.hashedPassword = derivedKey.toString("hex");
    req.body.salt = salt;

    next();
  });
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const SESSION_TIMEOUT = 30 * 60 * 1000; // 30 minutes
const ACTIVE_SESSIONS = new Map<string, { expires: number }>();

function getSessionIdFromRequest(req: Request): string | null {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return null;
  }

  const token = authHeader.substring(7);
  return token;
}

function verifyTokenSignature(token: string): boolean {
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    return false;
  }

  try {
    const [header, payload, signature] = token.split(".");
    if (!header || !payload || !signature) {
      return false;
    }

    const expectedSignature = createHmac("sha256", secret)
      .update(`${header}.${payload}`)
      .digest("base64url");

    const actualSignature = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    return timingSafeEqual(actualSignature, expectedSignatureBuffer);
  } catch {
    return false;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only handle POST requests to /leave-applications endpoint
  if (req.method !== "POST" || !req.path.startsWith("/leave-applications")) {
    next();
    return;
  }

  const sessionId = getSessionIdFromRequest(req);
  if (!sessionId) {
    res.status(401).json({ error: "Unauthorized: Missing session token" });
    return;
  }

  const session = ACTIVE_SESSIONS.get(sessionId);
  if (!session) {
    res.status(401).json({ error: "Unauthorized: Invalid session" });
    return;
  }

  if (Date.now() > session.expires) {
    ACTIVE_SESSIONS.delete(sessionId);
    res.status(401).json({ error: "Unauthorized: Session expired" });
    return;
  }

  // Verify token signature
  if (!verifyTokenSignature(sessionId)) {
    ACTIVE_SESSIONS.delete(sessionId);
    res.status(401).json({ error: "Unauthorized: Invalid token signature" });
    return;
  }

  // Refresh session timeout
  session.expires = Date.now() + SESSION_TIMEOUT;

  next();
}

