import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock database functions - in a real app these would be actual database calls
const mockLeaveRequests = [
  { id: "1", employeeId: "emp1", startDate: "2023-05-01", endDate: "2023-05-05", status: "approved" },
  { id: "2", employeeId: "emp2", startDate: "2023-06-01", endDate: "2023-06-03", status: "pending" }
];

const findLeaveRequestById = (id: string) => {
  return mockLeaveRequests.find(request => request.id === id);
};

const createLeaveRequest = (request: any) => {
  const newRequest = {
    id: String(mockLeaveRequests.length + 1),
    ...request,
    status: request.status || "pending"
  };
  mockLeaveRequests.push(newRequest);
  return newRequest;
};

const updateLeaveRequest = (id: string, updates: any) => {
  const index = mockLeaveRequests.findIndex(request => request.id === id);
  if (index === -1) return null;

  mockLeaveRequests[index] = { ...mockLeaveRequests[index], ...updates };
  return mockLeaveRequests[index];
};

const deleteLeaveRequest = (id: string) => {
  const index = mockLeaveRequests.findIndex(request => request.id === id);
  if (index === -1) return false;

  mockLeaveRequests.splice(index, 1);
  return true;
};

// GET /leave-requests - List all leave requests
router.get("/leave-requests", (req: Request, res: Response) => {
  res.json(mockLeaveRequests);
});

// GET /leave-requests/:id - Get a specific leave request by ID
router.get("/leave-requests/:id", (req: Request, res: Response) => {
  const leaveRequest = findLeaveRequestById(req.params.id);

  if (!leaveRequest) {
    return res.status(404).json({ error: "Leave request not found" });
  }

  res.json(leaveRequest);
});

// POST /leave-requests - Create a new leave request
router.post("/leave-requests", (req: Request, res: Response) => {
  const { employeeId, startDate, endDate, status } = req.body;

  // Basic validation
  if (!employeeId || !startDate || !endDate) {
    return res.status(400).json({ error: "employeeId, startDate, and endDate are required" });
  }

  const newLeaveRequest = createLeaveRequest({ employeeId, startDate, endDate, status });

  res.status(201).json(newLeaveRequest);
});

// PUT /leave-requests/:id - Update a leave request
router.put("/leave-requests/:id", (req: Request, res: Response) => {
  const { employeeId, startDate, endDate, status } = req.body;

  const updatedLeaveRequest = updateLeaveRequest(req.params.id, { employeeId, startDate, endDate, status });

  if (!updatedLeaveRequest) {
    return res.status(404).json({ error: "Leave request not found" });
