import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to specific routes
  const isLeaveRoute = req.path.startsWith('/leave') && (req.method === 'GET' || req.method === 'POST' || req.method === 'PUT' || req.method === 'DELETE');

  if (!isLeaveRoute) {
    next();
    return;
  }

  // Check for authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    res.status(401).json({ error: 'Unauthorized: Missing or invalid token' });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '

  try {
    // Decode token (simple base64 decode for demo purposes)
    const payload = Buffer.from(token.split('.')[1], 'base64').toString('utf8');
    const decoded = JSON.parse(payload);

    // Get user role from token
    const userRole = decoded.role;

    // Define role permissions
    const allowedRoles = {
      'employee': ['GET', 'POST'],
      'manager': ['GET', 'POST', 'PUT', 'DELETE']
    };

    // Check if user has sufficient permissions
    const allowedMethods = allowedRoles[userRole as keyof typeof allowedRoles] || [];

    if (!allowedMethods.includes(req.method)) {
      res.status(403).json({ error: 'Forbidden: Insufficient permissions' });
      return;
    }

    // If we get here, user has proper permissions
    next();
  } catch (error) {
    res.status(401).json({ error: 'Unauthorized: Invalid token' });
  }
}

