import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to protected routes
  if (!req.path.startsWith('/api/')) {
    next();
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    res.status(401).json({ error: 'Missing or invalid authorization header' });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: 'Server configuration error' });
    return;
  }

  // Simple token validation - in a real app, you'd decode and verify the JWT properly
  // For this implementation, we'll just check if it has the right format
  const parts = token.split('.');
  if (parts.length !== 3) {
    res.status(401).json({ error: 'Invalid token format' });
    return;
  }

  // In a real implementation, we would verify the signature here
  // This is a simplified version that just checks if the token exists
  // and has proper structure
  try {
    // Decode the payload (simplified)
    const payload = JSON.parse(Buffer.from(parts[1], 'base64').toString());

    // Check if user has appropriate role based on path
    const userRole = payload.role || 'client';
    const userId = payload.userId;

    // Allow access to client projects and communications
    if (req.path.includes('/projects/') || req.path.includes('/communications/')) {
      // For staff, allow access to all resources
      if (userRole === 'staff') {
        next();
        return;
      }

      // For clients, ensure they can only access their own resources
      const pathUserId = req.params.userId || req.params.id;
      if (userId && pathUserId && userId === pathUserId) {
        next();
        return;
      }

      // If user doesn't match resource owner, deny access
      res.status(403).json({ error: 'Access denied' });
      return;
    }

    // For other routes, allow staff access
    if (userRole === 'staff') {
      next();
      return;
    }

    // Deny access for unauthorized users
    res.status(403).json({ error: 'Access denied' });
  } catch (error) {
    res.status(401).json({ error: 'Invalid token' });
  }
}

