import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const SESSION_TIMEOUT = 30 * 60 * 1000; // 30 minutes
const JWT_SECRET = process.env.JWT_SECRET;

// Helper to decode JWT without verification (for header/payload extraction)
function base64UrlDecode(str: string): string {
  str = str.replace(/-/g, "+").replace(/_/g, "/");
  const pad = str.length % 4;
  if (pad) {
    str += "=".repeat(4 - pad);
  }
  return Buffer.from(str, "base64").toString();
}

// Helper to verify JWT signature
function verifyTokenSignature(token: string): boolean {
  if (!JWT_SECRET) return false;

  const parts = token.split(".");
  if (parts.length !== 3) return false;

  const [header, payload, signature] = parts;
  const expectedSignature = createHmac("sha256", JWT_SECRET)
    .update(`${header}.${payload}`)
    .digest("base64url");

  try {
    const expectedBuffer = Buffer.from(expectedSignature, "base64url");
    const actualBuffer = Buffer.from(signature, "base64url");
    return timingSafeEqual(expectedBuffer, actualBuffer);
  } catch {
    return false;
  }
}

// Helper to parse JWT payload
function parsePayload(payload: string): any {
  try {
    return JSON.parse(base64UrlDecode(payload));
  } catch {
    return null;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only handle POST requests with a token in the Authorization header
  if (req.method !== "POST" || !req.headers.authorization) {
    return next();
  }

  const authHeader = req.headers.authorization;
  const token = authHeader.startsWith("Bearer ") ? authHeader.substring(7) : null;

  if (!token) {
    return res.status(401).json({ error: "Invalid token" });
  }

  // Verify token signature
  if (!verifyTokenSignature(token)) {
    return res.status(401).json({ error: "Invalid token" });
  }

  // Parse payload
  const parts = token.split(".");
  const payload = parsePayload(parts[1]);

  if (!payload || !payload.exp || !payload.sessionId) {
    return res.status(401).json({ error: "Invalid token payload" });
  }

  // Check expiration
  const now = Date.now();
  const expTime = payload.exp * 1000; // Convert seconds to milliseconds
  if (now > expTime) {
    return res.status(401).json({ error: "Session expired" });
  }

  // Check session timeout
  const sessionStart = payload.iat * 1000; // Convert seconds to milliseconds
  if (now - sessionStart > SESSION_TIMEOUT) {
    return res.status(401).json({ error: "Session expired" });
  }

  // If we get here, the session is valid
  next();
}

