import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const SECRET = process.env.JWT_SECRET;

function getBearerToken(req: Request): string | null {
  const authHeader = req.header("Authorization");
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return null;
  }
  return authHeader.substring(7);
}

function verifyToken(token: string): { role: string; id: string } | null {
  if (!SECRET) return null;

  const parts = token.split(".");
  if (parts.length !== 3) return null;

  const [header, payload, signature] = parts;

  const expectedSignature = createHmac("sha256", SECRET)
    .update(`${header}.${payload}`)
    .digest();

  const actualSignature = Buffer.from(signature, "base64");

  try {
    if (timingSafeEqual(expectedSignature, actualSignature)) {
      const decodedPayload = JSON.parse(Buffer.from(payload, "base64").toString());
      return {
        role: decodedPayload.role,
        id: decodedPayload.id
      };
    }
  } catch {
    return null;
  }

  return null;
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply RBAC to specific routes that require authorization
  const protectedPaths = [
    /^\/api\/items\/[^\/]+\/status$/,
    /^\/api\/items\/[^\/]+\/contact$/,
    /^\/api\/reports\/[^\/]+\/contact$/
  ];

  const isProtectedPath = protectedPaths.some(path => path.test(req.path));

  if (!isProtectedPath) {
    next();
    return;
  }

  const token = getBearerToken(req);

  if (!token) {
    res.status(401).json({ error: "Unauthorized: Missing token" });
    return;
  }

  const decoded = verifyToken(token);

  if (!decoded) {
    res.status(401).json({ error: "Unauthorized: Invalid token" });
    return;
  }

  // Allow access based on role and path
  const { role, id } = decoded;

  // Staff can modify status and contact info
  if (role === "staff") {
    next();
    return;
  }

  // Students can only view their own reports
  if (role === "student") {
    // Check if the request is for a report owned by this student
    if (req.path.includes("/reports/")) {
      const pathParts = req.path.split("/");
      const reportId = pathParts[4]; // Assuming path format: /api/reports/:id/contact

      // For demonstration purposes, we'll assume the student ID is in the token
      // In a real implementation, you'd want to verify ownership in DB
      if (reportId && reportId === id) {
        next();
        return;
      }
    }

    // If it's not a report-related path or doesn't match student ID
    res.status(403).json({ error: "Forbidden: Insufficient permissions" });
    return;
  }

  // If role is neither staff nor student
  res.status(403).json({ error: "Forbidden: Insufficient permissions" });
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // This middleware is meant for data encryption, but since we're dealing with
  // sensitive user data and photos, we should ensure that we don't process
  // any request that doesn't involve data that needs encryption.

  // For now, let's assume that all POST/PUT requests to specific routes
  // involving user data or photos need encryption. We'll check the path
  // and method to determine if encryption is needed.

  const isDataRoute = req.path.startsWith('/api/users/') || 
                      req.path.startsWith('/api/items/') ||
                      req.path.startsWith('/api/photos/');

  if ((req.method === 'POST' || req.method === 'PUT') && isDataRoute) {
    // In a real implementation, we would encrypt the data here
    // For now, we just pass through to the next middleware
    next();
  } else {
    // For all other requests, we continue normally
    next();
  }
}

