import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only enforce role-based access control on POST, PUT, DELETE requests
  if (!['POST', 'PUT', 'DELETE'].includes(req.method)) {
    next();
    return;
  }

  // For demonstration purposes, we'll check a mock header
  // In a real implementation, this would be part of a JWT or similar token
  const userRole = req.header('X-User-Role') || 'worker';

  // Define role permissions
  const rolePermissions: Record<string, string[]> = {
    admin: ['POST', 'PUT', 'DELETE'],
    manager: ['PUT', 'DELETE'],
    worker: []
  };

  // Check if the user's role has permission for this request
  const allowedMethods = rolePermissions[userRole] || [];

  if (allowedMethods.includes(req.method)) {
    next();
  } else {
    res.status(403).json({ error: 'Insufficient permissions' });
  }
}

