  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchInventoryData = async () => {
      try {
        // Simulate API call
        await new Promise(resolve => setTimeout(resolve, 500));

        // Mock data
        const mockMaterials: Material[] = [
          { id: 1, name: "Steel Beams", category: "Structural", quantity: 25, threshold: 30 },
          { id: 2, name: "Concrete Blocks", category: "Masonry", quantity: 15, threshold: 20 },
          { id: 3, name: "Bricks", category: "Masonry", quantity: 40, threshold: 35 },
          { id: 4, name: "Insulation", category: "Electrical", quantity: 8, threshold: 10 },
          { id: 5, name: "Copper Wiring", category: "Electrical", quantity: 12, threshold: 15 },
          { id: 6, name: "Wood Planks", category: "Framing", quantity: 30, threshold: 25 },
        ];

        setMaterials(mockMaterials);

        // Calculate category summaries
        const categories = [...new Set(mockMaterials.map(m => m.category))];
        const summaries = categories.map(category => {
          const categoryMaterials = mockMaterials.filter(m => m.category === category);
          const totalQuantity = categoryMaterials.reduce((sum, m) => sum + m.quantity, 0);
          const lowStockCount = categoryMaterials.filter(m => m.quantity <= m.threshold).length;

          return {
            category,
            totalQuantity,
            lowStockCount
          };
        });

        setCategorySummaries(summaries);
      } catch (err) {
        setError("Failed to load inventory data");
      } finally {
        setLoading(false);
      }
    };

    fetchInventoryData();
  }, []);

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  const lowStockItems = materials.filter(item => item.quantity <= item.threshold);
  const totalMaterials = materials.length;
  const totalQuantity = materials.reduce((sum, item) => sum + item.quantity, 0);

  return (
    <div style={{ maxWidth: "1200px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
