          <h2 style={{ margin: "0 0 10px 0", fontSize: "18px" }}>Total Quantity</h2>
          <p style={{ fontSize: "24px", fontWeight: "bold" }}>{totalQuantity}</p>
        </div>

        <div style={{ flex: "1 1 200px", padding: "20px", border: "1px solid #ddd", borderRadius: "8px", backgroundColor: "#f9f9f9" }}>
          <h2 style={{ margin: "0 0 10px 0", fontSize: "18px" }}>Low Stock Items</h2>
