import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check authorization for POST, PUT, DELETE requests to birthday routes
  const isBirthdayRoute = req.path.startsWith('/api/birthdays');
  const isProtectedMethod = ['POST', 'PUT', 'DELETE'].includes(req.method);

  if (!isBirthdayRoute || !isProtectedMethod) {
    next();
    return;
  }

  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    res.status(401).json({ error: 'Missing or invalid authorization header' });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '

  // Check if JWT_SECRET is set
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: 'Server configuration error: JWT_SECRET not set' });
    return;
  }

  // Simple token verification (in a real app, you'd want proper JWT validation)
  // For this example, we'll assume the token is a base64 encoded user ID
  try {
    const [userId, signature] = token.split('.');

    if (!userId || !signature) {
      res.status(401).json({ error: 'Invalid token format' });
      return;
    }

    // Recreate the expected signature
    const expectedSignature = createHmac('sha256', secret)
      .update(userId)
      .digest('hex');

    // Use timingSafeEqual to prevent timing attacks
    const expectedBuffer = Buffer.from(expectedSignature);
    const actualBuffer = Buffer.from(signature);

    if (actualBuffer.length !== expectedBuffer.length || 
        !timingSafeEqual(expectedBuffer, actualBuffer)) {
      res.status(401).json({ error: 'Invalid token signature' });
      return;
    }

    // If we get here, the token is valid
    // In a real implementation, you would decode the token to get the user ID
    // and then check if the user has permission to access the resource

    // For now, we'll just pass the token through
    // In a real app, you'd store the user ID in the request object
    // req.userId = userId;

    next();
  } catch (error) {
    res.status(401).json({ error: 'Token verification failed' });
  }
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  // Check if JWT_SECRET is set
  const jwtSecret = process.env.JWT_SECRET;
  if (!jwtSecret) {
    res.status(500).json({ error: "Internal server error" });
    return;
  }

  // Simulate password verification
  const token = req.headers.authorization?.split(" ")[1];
  if (!token) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  // Verify token signature
  const secretBuffer = Buffer.from(jwtSecret);
  const tokenParts = token.split(".");
  if (tokenParts.length !== 3) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const [header, payload, signature] = tokenParts;
  const expectedSignature = createHmac("sha256", secretBuffer)
    .update(`${header}.${payload}`)
    .digest("base64url");

  const signatureBuffer = Buffer.from(signature, "base64url");
  const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

  try {
    const isValid = timingSafeEqual(signatureBuffer, expectedSignatureBuffer);
    if (!isValid) {
      res.status(401).json({ error: "Unauthorized" });
      return;
    }
  } catch (err) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  next();
}

