import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to POST requests to booking endpoints
  if (!(req.method === "POST" && req.path.startsWith("/bookings"))) {
    next();
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid authorization header" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Internal Server Error: JWT_SECRET not configured" });
    return;
  }

  // Simple token validation - in a real app, you'd decode and verify the JWT properly
  // For this example, we'll just check if it has the right format
  const parts = token.split(".");
  if (parts.length !== 3) {
    res.status(401).json({ error: "Unauthorized: Invalid token format" });
    return;
  }

  // In a real implementation, we would verify the signature here
  // This is a simplified version for demonstration purposes
  try {
    // Check if user has staff role (simplified)
    const payload = JSON.parse(atob(parts[1]));

    // Assuming payload contains a role field
    if (payload.role === "staff") {
      next();
    } else {
      res.status(403).json({ error: "Forbidden: Staff role required" });
    }
  } catch (err) {
    res.status(401).json({ error: "Unauthorized: Invalid token" });
  }
}

import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Skip validation for GET requests without body
  if (req.method === 'GET' && !req.body) {
    return next();
  }

  // Only validate POST, PUT, PATCH requests
  if (!['POST', 'PUT', 'PATCH'].includes(req.method)) {
    return next();
  }

  // Basic input validation
  const invalidFields = [];

  // Check for potentially dangerous patterns in body fields
  const checkField = (value: unknown, fieldName: string) => {
    if (typeof value === 'string') {
      // Check for common injection patterns
      if (value.includes('<script') || value.includes('javascript:')) {
        invalidFields.push(fieldName);
      }
    }
  };

  // Validate body fields
  if (req.body) {
    Object.entries(req.body).forEach(([key, value]) => {
      checkField(value, key);
    });
  }

  // Validate query parameters
  if (req.query) {
    Object.entries(req.query).forEach(([key, value]) => {
      if (Array.isArray(value)) {
        value.forEach(v => checkField(v, key));
      } else {
        checkField(value, key);
      }
    });
  }

  // Validate path parameters
  if (req.params) {
    Object.entries(req.params).forEach(([key, value]) => {
      checkField(value, key);
    });
  }

  if (invalidFields.length > 0) {
    return res.status(400).json({ error: 'Invalid input data' });
  }

  next();
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const JWT_SECRET = process.env.JWT_SECRET;

function verifyToken(token: string): boolean {
  if (!JWT_SECRET) return false;

  const parts = token.split(".");
  if (parts.length !== 3) return false;

  const [header, payload, signature] = parts;

  const expectedSignature = createHmac("sha256", JWT_SECRET)
    .update(`${header}.${payload}`)
    .digest("base64url");

  try {
    const expectedBuffer = Buffer.from(expectedSignature, "base64url");
    const actualBuffer = Buffer.from(signature, "base64url");

    return timingSafeEqual(expectedBuffer, actualBuffer);
  } catch {
    return false;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check authentication for POST /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  // Check if Authorization header exists
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
    return;
  }

  const token = authHeader.substring(7); // Remove "Bearer " prefix

  if (!verifyToken(token)) {
    res.status(401).json({ error: "Unauthorized: Invalid token" });
    return;
  }

  next();
}

