import { useEffect, useState } from "react";

interface Class {
  id: number;
  name: string;
  instrument: string;
  level: string;
  schedule: string;
  capacity: number;
}

export function ClassManagement() {
  const [classes, setClasses] = useState<Class[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Form state
  const [formData, setFormData] = useState<Omit<Class, 'id'>>({ 
    name: '',
    instrument: '',
    level: '',
    schedule: '',
    capacity: 0
  });

  const [editingId, setEditingId] = useState<number | null>(null);

  // Fetch classes
  useEffect(() => {
    fetchClasses();
  }, []);

  const fetchClasses = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/classes');
      if (!response.ok) throw new Error('Failed to fetch classes');
      const data = await response.json();
      setClasses(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  // Handle form input changes
  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: name === 'capacity' ? Number(value) : value
    }));
  };

  // Submit form
  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
      const url = editingId 
        ? `/api/classes/${editingId}`
        : '/api/classes';

      const method = editingId ? 'PUT' : 'POST';

      const response = await fetch(url, {
        method,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(formData)
      });

      if (!response.ok) throw new Error('Failed to save class');

      // Reset form and refetch data
      setFormData({ name: '', instrument: '', level: '', schedule: '', capacity: 0 });
      setEditingId(null);
      fetchClasses();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  // Edit class
  const handleEdit = (cls: Class) => {
    setFormData({
      name: cls.name,
      instrument: cls.instrument,
      level: cls.level,
      schedule: cls.schedule,
      capacity: cls.capacity
    });
    setEditingId(cls.id);
  };

  // Delete class
  const handleDelete = async (id: number) => {
    try {
      const response = await fetch(`/api/classes/${id}`, { method: 'DELETE' });
      if (!response.ok) throw new Error('Failed to delete class');
      fetchClasses();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;

  if (error) return <div style={{ color: 'red', textAlign: 'center', padding: '20px' }}>{error}</div>;

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Manage Music Classes</h1>

      {/* Form */}
      <form onSubmit={handleSubmit} style={{ marginBottom: '30px', padding: '20px', border: '1px solid #ccc', borderRadius: '8px' }}>
        <h2>{editingId ? 'Edit Class' : 'Add New Class'}</h2>

        <div style={{ marginBottom: '10px' }}>
          <label>Name: </label>
          <input
            type="text"
            name="name"
            value={formData.name}
            onChange={handleInputChange}
            style={{ width: '100%', padding: '8px', marginTop: '5px' }}
