      <div style={{ marginBottom: "20px" }}>
        <input
          type="text"
          placeholder="Search by student or class..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          style={{ width: "100%", padding: "10px", borderRadius: "4px", border: "1px solid #ccc" }}
        />
      </div>

      <div style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
        {filteredBookings.length === 0 ? (
          <p style={{ textAlign: "center", padding: "20px" }}>No bookings found.</p>
        ) : (
          filteredBookings.map(booking => {
            const student = students.find(s => s.id === booking.studentId);
            const className = classes.find(c => c.id === booking.classId)?.title || "Unknown Class";

            return (
              <div key={booking.id} style={{ border: "1px solid #ddd", borderRadius: "8px", padding: "15px", backgroundColor: "#f9f9f9" }}>
