                  <div>
                    <h3>{student?.name}</h3>
                    <p><strong>Class:</strong> {className}</p>
                    <p><strong>Date:</strong> {booking.bookingDate}</p>
                  </div>
                  <div style={{ display: "flex", flexDirection: "column", alignItems: "flex-end" }}>
                    <span style={{ backgroundColor: getStatusColor(booking.status), color: "white", padding: "4px 8px", borderRadius: "4px", fontSize: "14px" }}>
                      {booking.status.charAt(0).toUpperCase() + booking.status.slice(1)}
                    </span>
                    <div style={{ marginTop: "10px", display: "flex", gap: "5px" }}>
                      <button 
                        onClick={() => handleStatusChange(booking.id, "confirmed")}
                        style={{ padding: "4px 8px", backgroundColor: "#4caf50", color: "white", border: "none", borderRadius: "4px", cursor: "pointer" }}
                      >
                        Confirm
