import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock article data structure
interface Article {
  id: number;
  title: string;
  authors: string[];
  abstract: string;
  publicationDate: string;
  journal: string;
  fileUrl?: string;
}

// Mock in-memory storage
let articles: Article[] = [];
let nextId = 1;

// Validation helper
const validateArticle = (article: Partial<Article>): string | null => {
  if (!article.title || article.title.trim() === '') {
    return 'Title is required';
  }

  if (!article.authors || !Array.isArray(article.authors) || article.authors.length === 0) {
    return 'Authors are required';
  }

  if (!article.abstract || article.abstract.trim() === '') {
    return 'Abstract is required';
  }

  if (!article.publicationDate) {
    return 'Publication date is required';
  }

  if (!article.journal || article.journal.trim() === '') {
    return 'Journal is required';
  }

  return null;
};

// GET /articles - List all articles
router.get('/', (req: Request, res: Response) => {
  res.json(articles);
});

// GET /articles/:id - Get one article by ID
router.get('/:id', (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: 'Invalid article ID' });
  }

  const article = articles.find(a => a.id === id);

  if (!article) {
    return res.status(404).json({ error: 'Article not found' });
  }

  res.json(article);
});

// POST /articles - Create a new article
router.post('/', (req: Request, res: Response) => {
  const { title, authors, abstract, publicationDate, journal, fileUrl } = req.body;

  const validationError = validateArticle({ title, authors, abstract, publicationDate, journal });

  if (validationError) {
    return res.status(400).json({ error: validationError });
  }

  const newArticle: Article = {
    id: nextId++,
    title,
    authors,
    abstract,
    publicationDate,
    journal,
    fileUrl
  };

  articles.push(newArticle);

  res.status(201).json(newArticle);
});

// PUT /articles/:id - Update an existing article
router.put('/:id', (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: 'Invalid article ID' });
  }

  const articleIndex = articles.findIndex(a => a.id === id);

  if (articleIndex === -1) {
    return res.status(404).json({ error: 'Article not found' });
  }

  const { title, authors, abstract, publicationDate, journal, fileUrl } = req.body;

  const validationError = validateArticle({ title, authors, abstract, publicationDate, journal });

  if (validationError) {
    return res.status(400).json({ error: validationError });
  }

  const updatedArticle: Article = {
    ...articles[articleIndex],
    title,
    authors,
    abstract,
    publicationDate,
    journal,
    fileUrl
  };

  articles[articleIndex] = updatedArticle;

  res.json(updatedArticle);
});

// DELETE /articles/:id - Delete an article
router.delete('/:id', (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: 'Invalid article ID' });
  }

  const articleIndex = articles.findIndex(a => a.id === id);

  if (articleIndex === -1) {
    return res.status(404).json({ error: 'Article not found' });
  }

  articles.splice(articleIndex, 1);

  res.json({ message: 'Article deleted successfully' });
});

import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock data structures to simulate database operations
const reviews = new Map<string, any>();
const articles = new Map<string, any>();

// Helper function to calculate average rating
const calculateAverageRating = (ratings: number[]): number => {
  if (ratings.length === 0) return 0;
  const sum = ratings.reduce((acc, rating) => acc + rating, 0);
  return Math.round((sum / ratings.length) * 10) / 10; // Round to 1 decimal place
};

// POST /reviews - Create a new review
router.post("/reviews", (req: Request, res: Response) => {
  const { articleId, rating, comment } = req.body;

  if (!articleId || !rating || !comment) {
    return res.status(400).json({ error: "Missing required fields: articleId, rating, comment" });
  }

  if (typeof rating !== "number" || rating < 1 || rating > 5) {
    return res.status(400).json({ error: "Rating must be a number between 1 and 5" });
  }

  const reviewId = Date.now().toString();
  const newReview = {
    id: reviewId,
    articleId,
    rating,
    comment,
    createdAt: new Date().toISOString()
  };

  reviews.set(reviewId, newReview);

  // Update article's average rating
  const existingArticle = articles.get(articleId);
  if (existingArticle) {
    existingArticle.ratings.push(rating);
    existingArticle.averageRating = calculateAverageRating(existingArticle.ratings);
  } else {
    articles.set(articleId, {
      id: articleId,
      ratings: [rating],
      averageRating: rating
    });
  }

  return res.status(201).json(newReview);
});

// GET /reviews/:id - Get a specific review by ID
router.get("/reviews/:id", (req: Request, res: Response) => {
  const { id } = req.params;
  const review = reviews.get(id);

  if (!review) {
    return res.status(404).json({ error: "Review not found" });
  }

  return res.json(review);
});

// PUT /reviews/:id - Update a review
router.put("/reviews/:id", (req: Request, res: Response) => {
  const { id } = req.params;
  const { rating, comment } = req.body;

  const review = reviews.get(id);
  if (!review) {
    return res.status(404).json({ error: "Review not found" });
  }

  if (typeof rating !== "number" || rating < 1 || rating > 5) {
    return res.status(400).json({ error: "Rating must be a number between 1 and 5" });
  }

  if (!comment) {
    return res.status(400).json({ error: "Comment is required" });
  }

  review.rating = rating;
  review.comment = comment;
  review.updatedAt = new Date().toISOString();

  // Recalculate average rating for the article
  const article = articles.get(review.articleId);
  if (article) {
    const index = article.ratings.indexOf(review.rating);
    if (index !== -1) {
      article.ratings[index] = rating;
      article.averageRating = calculateAverageRating(article.ratings);
    }
  }

  return res.json(review);
});

// DELETE /reviews/:id - Delete a review
router.delete("/reviews/:id", (req: Request, res: Response) => {
  const { id } = req.params;
  const review = reviews.get(id);

  if (!review) {
    return res.status(404).json({ error: "Review not found" });
  }

  reviews.delete(id);

  // Recalculate average rating for the article
  const article = articles.get(review.articleId);
  if (article) {
    const index = article.ratings.indexOf(review.rating);
    if (index !== -1) {
      article.ratings.splice(index, 1);
      article.averageRating = calculateAverageRating(article.ratings);
    }
  }

  return res.json({ message: "Review deleted successfully" });
});

