import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const JWT_SECRET = process.env.JWT_SECRET;

function verifyToken(token: string): boolean {
  if (!JWT_SECRET) return false;

  const parts = token.split(".");
  if (parts.length !== 3) return false;

  const [header, payload, signature] = parts;

  const expectedSignature = createHmac("sha256", JWT_SECRET)
    .update(`${header}.${payload}`)
    .digest("base64url");

  try {
    const expectedBuffer = Buffer.from(expectedSignature, "base64url");
    const actualBuffer = Buffer.from(signature, "base64url");

    return timingSafeEqual(expectedBuffer, actualBuffer);
  } catch {
    return false;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST, PUT, DELETE, PATCH requests
  if (!['POST', 'PUT', 'DELETE', 'PATCH'].includes(req.method)) {
    next();
    return;
  }

  // Check if the request path requires authentication
  if (!req.path.startsWith('/api/')) {
    next();
    return;
  }

  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7); // Remove "Bearer " prefix

  if (!verifyToken(token)) {
    res.status(401).json({ error: "Invalid token" });
    return;
  }

  next();
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Skip validation for non-protected routes
  const protectedPaths = ["/articles", "/reviews", "/admin"];
  const isProtectedPath = protectedPaths.some(path =>
    req.path.startsWith(path)
  );

  if (!isProtectedPath) {
    next();
    return;
  }

  // Check if user has required role
  const userRole = req.headers["x-user-role"] as string | undefined;
  const requiredRoles = getRequiredRoles(req.method, req.path);

  if (!userRole || !requiredRoles.includes(userRole)) {
    res.status(403).json({ error: "Forbidden: Insufficient permissions" });
    return;
  }

  // Validate JWT if present
  const authHeader = req.headers["authorization"];
  if (authHeader && authHeader.startsWith("Bearer ")) {
    const token = authHeader.substring(7);
    if (!process.env.JWT_SECRET) {
      res.status(500).json({ error: "Server configuration error" });
      return;
    }

    try {
      const [payload, signature] = token.split(".");
      const expectedSignature = createHmac("sha256", process.env.JWT_SECRET)
        .update(payload)
        .digest("base64url");

      const expectedBuffer = Buffer.from(expectedSignature);
      const actualBuffer = Buffer.from(signature);

      if (timingSafeEqual(expectedBuffer, actualBuffer)) {
        next();
        return;
      } else {
        res.status(401).json({ error: "Unauthorized: Invalid token" });
        return;
      }
    } catch (err) {
      res.status(401).json({ error: "Unauthorized: Invalid token" });
      return;
    }
  }

  next();
}

function getRequiredRoles(method: string, path: string): string[] {
  if (path.startsWith("/articles")) {
    if (method === "POST") return ["author", "editor"];
    if (method === "PUT" || method === "DELETE") return ["author", "editor"];
  }

  if (path.startsWith("/reviews")) {
    if (method === "POST") return ["reviewer", "editor"];
    if (method === "PUT" || method === "DELETE") return ["reviewer", "editor"];
  }

  if (path.startsWith("/admin")) {
    return ["editor"];
  }

  return [];
}

