import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to specific admin routes
  const isAdminRoute = req.path.startsWith('/admin') && (req.method === 'GET' || req.method === 'POST' || req.method === 'PUT' || req.method === 'DELETE');

  if (!isAdminRoute) {
    next();
    return;
  }

  // Check for authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    res.status(401).json({ error: 'Unauthorized: Missing or invalid token' });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '

  // Verify JWT signature
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    res.status(500).json({ error: 'Server configuration error: JWT_SECRET not set' });
    return;
  }

  try {
    // Simple verification of token structure (in a real app, use a proper JWT library)
    const [header, payload, signature] = token.split('.');
    if (!header || !payload || !signature) {
      res.status(401).json({ error: 'Unauthorized: Invalid token format' });
      return;
    }

    // Recreate the signature to verify
    const expectedSignature = createHmac('sha256', secret)
      .update(`${header}.${payload}`)
      .digest('base64url');

    // Use timingSafeEqual to prevent timing attacks
    const expectedBuffer = Buffer.from(expectedSignature);
    const actualBuffer = Buffer.from(signature);

    if (!timingSafeEqual(expectedBuffer, actualBuffer)) {
      res.status(401).json({ error: 'Unauthorized: Invalid token signature' });
      return;
    }

    // Decode payload to check role (simplified for this example)
    const decodedPayload = JSON.parse(Buffer.from(payload, 'base64').toString());

    if (decodedPayload.role !== 'admin') {
      res.status(403).json({ error: 'Forbidden: Admin access required' });
      return;
    }

    // If we get here, user has admin role
    next();
  } catch (error) {
    res.status(401).json({ error: 'Unauthorized: Invalid token' });
  }
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only validate POST requests to the registration endpoint
  if (req.method !== "POST" || req.path !== "/register") {
    next();
    return;
  }

  const { email, password, name } = req.body;

  // Validate email format
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!email || !emailRegex.test(email)) {
    return res.status(400).json({ error: 'Invalid email format' });
  }

  // Validate password requirements
  const passwordRegex = /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]{8,}$/;
  if (!password || !passwordRegex.test(password)) {
    return res.status(400).json({ error: 'Password does not meet requirements' });
  }

  // Validate name contains only letters, spaces, hyphens, and apostrophes
  const nameRegex = /^[A-Za-z\s\-'']+$/;
  if (!name || !nameRegex.test(name)) {
    return res.status(400).json({ error: 'Name contains invalid characters' });
  }

  next();
}

