}

export function BillsManagement() {
  const [bills, setBills] = useState<Bill[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState("");

  // Form state
  const [amount, setAmount] = useState("");
  const [dueDate, setDueDate] = useState("");
  const [status, setStatus] = useState<"paid" | "pending" | "overdue">("pending");
  const [editingId, setEditingId] = useState<number | null>(null);

  // Fetch bills
  useEffect(() => {
    const fetchBills = async () => {
      try {
        const response = await fetch('/api/bills');
        if (!response.ok) {
          throw new Error('Failed to fetch bills');
        }
        const data = await response.json();
        setBills(data);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'An unknown error occurred');
      } finally {
        setLoading(false);
      }
    };

    fetchBills();
  }, []);

  // Filter bills based on search term
  const filteredBills = bills.filter(bill => 
    bill.id.toString().includes(searchTerm) ||
    bill.amount.toString().includes(searchTerm) ||
    bill.dueDate.includes(searchTerm)
  );

  // Handle form submission
  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    const billData = {
      amount: parseFloat(amount),
      dueDate,
      status
    };

    try {
      const response = editingId 
        ? await fetch(`/api/bills/${editingId}`, {
            method: 'PUT',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(billData)
          })
        : await fetch('/api/bills', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(billData)
          });

      if (!response.ok) {
        throw new Error('Failed to save bill');
      }

      // Refresh bills
      const response2 = await fetch('/api/bills');
      const data = await response2.json();
      setBills(data);

      // Reset form
      setAmount("");
      setDueDate("");
      setStatus("pending");
      setEditingId(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  // Edit a bill
  const handleEdit = (bill: Bill) => {
    setAmount(bill.amount.toString());
    setDueDate(bill.dueDate);
    setStatus(bill.status);
    setEditingId(bill.id);
  };

  // Delete a bill
  const handleDelete = async (id: number) => {
    try {
      const response = await fetch(`/api/bills/${id}`, { method: 'DELETE' });
      if (!response.ok) {
        throw new Error('Failed to delete bill');
      }

      // Refresh bills
      const response2 = await fetch('/api/bills');
      const data = await response2.json();
      setBills(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;

  if (error) return <div style={{ color: 'red', textAlign: 'center', padding: '20px' }}>{error}</div>;

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Electricity Bills Management</h1>

      {/* Search */}
      <div style={{ marginBottom: '20px' }}>
        <input
          type="text"
          placeholder="Search bills..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          style={{ width: '100%', padding: '10px', borderRadius: '4px', border: '1px solid #ccc' }}
        />
      </div>

      {/* Form */}
      <form onSubmit={handleSubmit} style={{ marginBottom: '30px', padding: '20px', border: '1px solid #ddd', borderRadius: '8px' }}>
        <h2 style={{ marginTop: '0' }}>{editingId ? 'Edit Bill' : 'Add New Bill'}</h2>

        <div style={{ marginBottom: '15px' }}>
          <label>Amount ($): </label>
          <input
            type="number"
            value={amount}
            onChange={(e) => setAmount(e.target.value)}
            required
            style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
          />
        </div>

        <div style={{ marginBottom: '15px' }}>
          <label>Due Date: </label>
          <input
            type="date"
            value={dueDate}
            onChange={(e) => setDueDate(e.target.value)}
            required
            style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
          />
        </div>

        <div style={{ marginBottom: '15px' }}>
          <label>Status: </label>
          <select
            value={status}
            onChange={(e) => setStatus(e.target.value as any)}
            style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
          >
            <option value="pending">Pending</option>
