        <p>Error: {error}</p>
      </div>
    );
  }

  return (
    <div style={containerStyle}>
      <h1>Usage Records</h1>

      <form onSubmit={handleSubmit} style={formStyle}>
        <input
          type="date"
          name="date"
          value={formData.date}
          onChange={handleInputChange}
          style={inputStyle}
          required
        />
        <input
          type="number"
          name="usageKwh"
          placeholder="Usage (kWh)"
          value={formData.usageKwh}
          onChange={handleInputChange}
          style={inputStyle}
          required
        />
        <input
          type="number"
          name="cost"
          placeholder="Cost ($)"
          value={formData.cost}
          onChange={handleInputChange}
          style={inputStyle}
          required
        />
        <button type="submit" style={buttonStyle}>
          {editingId ? "Update Record" : "Add Record"}
        </button>
        {editingId && (
          <button
            type="button"
            onClick={() => {
              setEditingId(null);
              setFormData({ date: "", usageKwh: "", cost: "" });
            }}
            style={{
              ...buttonStyle,
              backgroundColor: "#6c757d"
            }}
          >
            Cancel
          </button>
        )}
      </form>

      {records.length === 0 ? (
        <p>No usage records found.</p>
      ) : (
        <table style={tableStyle}>
          <thead>
            <tr>
              <th style={thTdStyle}>Date</th>
              <th style={thTdStyle}>Usage (kWh)</th>
              <th style={thTdStyle}>Cost ($)</th>
              <th style={thTdStyle}>Actions</th>
            </tr>
          </thead>
          <tbody>
            {records.map((record) => (
              <tr key={record.id}>
                <td style={thTdStyle}>{record.date}</td>
                <td style={thTdStyle}>{record.usageKwh}</td>
                <td style={thTdStyle}>{record.cost}</td>
                <td style={thTdStyle}>
                  <div style={actionsStyle}>
                    <button
                      onClick={() => handleEdit(record)}
                      style={{
                        ...buttonStyle,
                        backgroundColor: "#28a745"
                      }}
                    >
                      Edit
                    </button>
                    <button
                      onClick={() => handleDelete(record.id)}
                      style={{
                        ...buttonStyle,
                        backgroundColor: "#dc3545"
                      }}
                    >
                      Delete
                    </button>
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
}

