  insertInspection,
  updateInspection,
  deleteInspection
} from "../db/inspections-table";

export const router = Router();

// Get all inspections
router.get("/", (req: Request, res: Response) => {
  try {
    const inspections = getAllInspections();
    res.json(inspections);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch inspections" });
  }
});

// Get inspection by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid inspection ID" });
    }

    const inspection = getInspectionById(id);
    if (!inspection) {
      return res.status(404).json({ error: "Inspection not found" });
    }

    res.json(inspection);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch inspection" });
  }
});

// Create new inspection
router.post("/", (req: Request, res: Response) => {
  try {
    const { date, inspectorName, checklistItems, status, notes } = req.body;

    if (!date || !inspectorName || !checklistItems || !status) {
      return res.status(400).json({ error: "Missing required fields: date, inspectorName, checklistItems, status" });
    }

    const id = insertInspection(date, inspectorName, checklistItems, status, notes || "");

    // Fetch the created inspection to send back
    const inspection = getInspectionById(id);
    if (!inspection) {
      return res.status(500).json({ error: "Failed to retrieve created inspection" });
    }

    res.status(201).json(inspection);
  } catch (error) {
    res.status(500).json({ error: "Failed to create inspection" });
  }
});

// Update inspection
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid inspection ID" });
    }

    const { date, inspectorName, checklistItems, status, notes } = req.body;

    if (!date || !inspectorName || !checklistItems || !status) {
      return res.status(400).json({ error: "Missing required fields: date, inspectorName, checklistItems, status" });
    }

    const existing = getInspectionById(id);
    if (!existing) {
      return res.status(404).json({ error: "Inspection not found" });
    }

    updateInspection(id, date, inspectorName, checklistItems, status, notes || "");

    // Fetch updated inspection
    const updated = getInspectionById(id);
    if (!updated) {
      return res.status(500).json({ error: "Failed to retrieve updated inspection" });
    }

    res.json(updated);
  } catch (error) {
    res.status(500).json({ error: "Failed to update inspection" });
  }
});

