import type { Request, Response, NextFunction } from "express";
import { Router } from "express";
import { router as inspectionRouter } from "../routes/inspection-api";
import { router as templateRouter } from "../routes/template-api";
import { router as authRouter } from "../routes/authentication-api";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Skip validation for GET requests to authentication endpoints
  if (req.method === "GET" && req.path.startsWith("/auth")) {
    return next();
  }

  // Only enforce role-based access control on specific routes
  const isInspectionRoute = req.path.startsWith("/inspections") && 
    (req.method === "POST" || req.method === "PUT" || req.method === "DELETE");

  const isTemplateRoute = req.path.startsWith("/templates") && 
    (req.method === "POST" || req.method === "PUT" || req.method === "DELETE");

  // If not a protected route, continue
  if (!isInspectionRoute && !isTemplateRoute) {
    return next();
  }

  // Check for authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return res.status(401).json({ error: "Unauthorized" });
  }

  const token = authHeader.substring(7);

  // In a real implementation, we would decode and verify the JWT here
  // For now, we'll simulate a basic verification
  try {
    // This is a placeholder - in reality, you'd verify the JWT signature
    // using HMAC-SHA256 with process.env.JWT_SECRET
    const payload = JSON.parse(atob(token.split(".")[1]));

    // Simulate role checking
    const userRole = payload.role;

    if (!userRole) {
      return res.status(401).json({ error: "Invalid token" });
    }

    // Allow only admin users to modify inspections or templates
    if ((isInspectionRoute || isTemplateRoute) && userRole !== "admin") {
      return res.status(403).json({ error: "Forbidden" });
    }

    next();
  } catch (error) {
    return res.status(401).json({ error: "Invalid token" });
  }
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";
import { Router } from "express";

// Importing routers to check if we should skip auth for specific routes
import { router as inspectionApiRouter } from "../routes/inspection-api";
import { router as templateApiRouter } from "../routes/template-api";
import { router as authenticationApiRouter } from "../routes/authentication-api";

const JWT_SECRET = process.env.JWT_SECRET;

/**
 * Checks if a request path matches any protected route patterns
 */
function isProtectedRoute(req: Request): boolean {
  // Skip authentication for login and registration endpoints
  if (req.path.startsWith("/auth/login") || req.path.startsWith("/auth/register")) {
    return false;
  }

  // Skip authentication for static assets or public endpoints
  if (req.path.startsWith("/public/")) {
    return false;
  }

  // For all other routes, require authentication
  return true;
}

/**
 * Verifies a JWT token using HMAC-SHA256 with the secret from environment variables
 */
function verifyToken(token: string): boolean {
  if (!JWT_SECRET) {
    return false;
  }

  try {
    // Split token into parts (header.payload.signature)
    const [header, payload, signature] = token.split(".");

    if (!header || !payload || !signature) {
      return false;
    }

    // Recreate the signature
    const expectedSignature = createHmac("sha256", JWT_SECRET)
      .update(`${header}.${payload}`)
      .digest("base64url");

    // Use timingSafeEqual to prevent timing attacks
    const expectedBuffer = Buffer.from(expectedSignature);
    const actualBuffer = Buffer.from(signature);

    return timingSafeEqual(expectedBuffer, actualBuffer);
  } catch (err) {
    return false;
  }
}

/**
 * Express middleware for user authentication
 */
export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Skip authentication for non-protected routes
  if (!isProtectedRoute(req)) {
    next();
    return;
  }

  // Check for Authorization header
  const authHeader = req.headers["authorization"];

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '

  // Verify the token
  if (!verifyToken(token)) {
    res.status(401).json({ error: "Unauthorized: Invalid token" });
    return;
  }

  // If we get here, the token is valid
  next();
}

import { useState, useEffect } from "react";

interface ChecklistItem {
  id: string;
  description: string;
  status: 'pass' | 'fail' | 'na';
}

interface Inspection {
  id?: string;
  inspectionDate: string;
  inspectorName: string;
  checklistItems: ChecklistItem[];
  status: 'draft' | 'submitted' | 'approved' | 'rejected';
}

export function InspectionForm() {
  const [inspection, setInspection] = useState<Inspection>({
    inspectionDate: new Date().toISOString().split('T')[0],
    inspectorName: '',
    checklistItems: [],
    status: 'draft'
  });

  const [loading, setLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);

  // Initialize with sample checklist items
  useEffect(() => {
    fetchChecklistItems();
  }, []);

  const fetchChecklistItems = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/template-api/templates');
      if (!response.ok) throw new Error('Failed to fetch templates');

      const templates = await response.json();
      const items = templates.map((template: any) => ({
        id: template.id,
        description: template.description,
        status: 'na' as const
      }));

      setInspection(prev => ({
        ...prev,
        checklistItems: items
      }));
    } catch (err) {
      setError('Failed to load checklist items');
    } finally {
      setLoading(false);
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setInspection(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const handleItemStatusChange = (itemId: string, status: 'pass' | 'fail' | 'na') => {
    setInspection(prev => ({
      ...prev,
      checklistItems: prev.checklistItems.map(item => 
        item.id === itemId ? { ...item, status } : item
      )
    }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
      setLoading(true);
      const response = await fetch('/api/inspection-api/', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(inspection)
      });

      if (!response.ok) throw new Error('Failed to save inspection');

      // Reset form after successful submission
      setInspection({
        inspectionDate: new Date().toISOString().split('T')[0],
        inspectorName: '',
        checklistItems: inspection.checklistItems.map(item => ({
          ...item,
          status: 'na'
        })),
        status: 'draft'
      });

    } catch (err) {
      setError('Failed to save inspection');
    } finally {
      setLoading(false);
    }
  };

  if (loading && !inspection.checklistItems.length) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ color: 'red', textAlign: 'center', padding: '20px' }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Quality Inspection Form</h1>

      <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
        <div style={{ display: 'flex', flexDirection: 'column', gap: '5px' }}>
          <label htmlFor="inspectionDate">Inspection Date:</label>
          <input
            type="date"
            id="inspectionDate"
            name="inspectionDate"
            value={inspection.inspectionDate}
            onChange={handleInputChange}
            required
            style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
          />
        </div>

        <div style={{ display: 'flex', flexDirection: 'column', gap: '5px' }}>
          <label htmlFor="inspectorName">Inspector Name:</label>
          <input
            type="text"
            id="inspectorName"
            name="inspectorName"
            value={inspection.inspectorName}
            onChange={handleInputChange}
            required
            style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
          />
        </div>

        <div style={{ display: 'flex', flexDirection: 'column', gap: '5px' }}>
          <label>Status:</label>
          <select
            name="status"
            value={inspection.status}
            onChange={handleInputChange}
            style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
          >
            <option value="draft">Draft</option>
            <option value="submitted">Submitted</option>
            <option value="approved">Approved</option>
            <option value="rejected">Rejected</option>
          </select>
        </div>

        <h2 style={{ marginTop: '20px' }}>Checklist Items</h2>

        {inspection.checklistItems.length === 0 ? (
          <p>No checklist items found.</p>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
            {inspection.checklistItems.map((item) => (
              <div key={item.id} style={{ 
                border: '1px solid #ddd', 
                borderRadius: '4px', 
                padding: '10px', 
                backgroundColor: '#f9f9f9' 
              }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                  <span style={{ fontWeight: 'bold' }}>{item.description}</span>
                  <div style={{ display: 'flex', gap: '5px' }}>
                    <button
                      type="button"
                      onClick={() => handleItemStatusChange(item.id, 'pass')}
                      style={{ 
                        backgroundColor: item.status === 'pass' ? '#4CAF50' : '#f1f1f1', 
                        color: item.status === 'pass' ? 'white' : 'black', 
                        border: 'none', 
                        padding: '4px 8px', 
                        borderRadius: '4px', 
                        cursor: 'pointer' 
                      }}
                    >
                      Pass
                    </button>
                    <button
                      type="button"
                      onClick={() => handleItemStatusChange(item.id, 'fail')}
                      style={{ 
                        backgroundColor: item.status === 'fail' ? '#f44336' : '#f1f1f1', 
                        color: item.status === 'fail' ? 'white' : 'black', 
                        border: 'none', 
                        padding: '4px 8px', 
                        borderRadius: '4px', 
                        cursor: 'pointer' 
                      }}
                    >
                      Fail
                    </button>
                    <button
                      type="button"
                      onClick={() => handleItemStatusChange(item.id, 'na')}
                      style={{ 
                        backgroundColor: item.status === 'na' ? '#ff9800' : '#f1f1f1', 
                        color: item.status === 'na' ? 'white' : 'black', 
                        border: 'none', 
                        padding: '4px 8px', 
                        borderRadius: '4px', 
                        cursor: 'pointer' 
                      }}
                    >
                      N/A
                    </button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}

        <button
          type="submit"
          disabled={loading}
          style={{ 
            backgroundColor: '#2196F3', 
            color: 'white', 
            border: 'none', 
            padding: '10px 15px', 
            borderRadius: '4px', 
            cursor: 'pointer', 
            fontSize: '16px', 
            marginTop: '20px' 
          }}
        >
          {loading ? 'Saving...' : 'Save Inspection'}
        </button>
      </form>
    </div>
  );
}

import { useEffect, useState } from "react";

interface Inspection {
  id: string;
  date: string;
  inspector: string;
  status: 'pending' | 'completed' | 'failed';
}

export function InspectionList() {
  const [inspections, setInspections] = useState<Inspection[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [inspector, setInspector] = useState('');
  const [status, setStatus] = useState('');

  useEffect(() => {
    fetchInspections();
  }, []);

  const fetchInspections = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/inspection-api/');
      if (!response.ok) {
        throw new Error(`HTTP error! Status: ${response.status}`);
      }
      const data = await response.json();
      setInspections(data);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const filteredInspections = inspections.filter(inspection => {
    const matchesDate = (!startDate || inspection.date >= startDate) &&
                        (!endDate || inspection.date <= endDate);
    const matchesInspector = !inspector || inspection.inspector.toLowerCase().includes(inspector.toLowerCase());
    const matchesStatus = !status || inspection.status === status;

    return matchesDate && matchesInspector && matchesStatus;
  });

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Quality Inspection Checklist</h1>

      <div style={{ marginBottom: '20px', display: 'flex', flexDirection: 'column', gap: '10px' }}>
        <input
          type="date"
          placeholder="Start Date"
          value={startDate}
          onChange={(e) => setStartDate(e.target.value)}
          style={{ width: '100%', padding: '8px' }}
        />
        <input
          type="date"
          placeholder="End Date"
          value={endDate}
          onChange={(e) => setEndDate(e.target.value)}
          style={{ width: '100%', padding: '8px' }}
        />
        <input
          type="text"
          placeholder="Inspector Name"
          value={inspector}
          onChange={(e) => setInspector(e.target.value)}
          style={{ width: '100%', padding: '8px' }}
        />
        <select
          value={status}
          onChange={(e) => setStatus(e.target.value)}
          style={{ width: '100%', padding: '8px' }}
        >
          <option value="">All Statuses</option>
          <option value="pending">Pending</option>
          <option value="completed">Completed</option>
          <option value="failed">Failed</option>
        </select>
        <button 
          onClick={fetchInspections}
          style={{ padding: '8px 16px', backgroundColor: '#007bff', color: 'white', border: 'none', borderRadius: '4px', cursor: 'pointer' }}
        >
          Apply Filters
        </button>
      </div>

      {filteredInspections.length === 0 ? (
        <div style={{ textAlign: 'center', padding: '20px' }}>No inspections found.</div>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
          {filteredInspections.map((inspection) => (
            <div 
              key={inspection.id} 
              style={{ 
                border: '1px solid #ccc', 
                borderRadius: '8px', 
                padding: '15px', 
                backgroundColor: '#f9f9f9'
              }}
            >
              <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '10px' }}>
                <span><strong>Date:</strong> {inspection.date}</span>
                <span><strong>Status:</strong> {inspection.status}</span>
              </div>
              <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                <span><strong>Inspector:</strong> {inspection.inspector}</span>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

import { useEffect, useState } from "react";

interface Template {
