        <form onSubmit={handleCreate}>
          <div style={{ marginBottom: "10px" }}>
            <label>Name:</label><br />
            <input
              type="text"
              value={newTemplate.name}
              onChange={(e) => setNewTemplate({...newTemplate, name: e.target.value})}
              style={{ width: "100%", padding: "8px", marginTop: "5px" }}
              required
            />
          </div>
          <div style={{ marginBottom: "10px" }}>
            <label>Description:</label><br />
            <textarea
              value={newTemplate.description}
              onChange={(e) => setNewTemplate({...newTemplate, description: e.target.value})}
              style={{ width: "100%", padding: "8px", marginTop: "5px" }}
              required
            />
          </div>
          <div style={{ marginBottom: "10px" }}>
            <label>Items (one per line):</label><br />
            <textarea
              value={newTemplate.items}
              onChange={(e) => setNewTemplate({...newTemplate, items: e.target.value})}
              style={{ width: "100%", padding: "8px", marginTop: "5px" }}
              required
            />
          </div>
          <button type="submit" style={{ backgroundColor: "#007bff", color: "white", border: "none", padding: "10px 20px", borderRadius: "4px", cursor: "pointer" }}>
            Create Template
          </button>
        </form>
      </div>

      <h2>Existing Templates</h2>
      {templates.length === 0 ? (
        <p style={{ textAlign: "center", padding: "20px" }}>No templates found.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
          {templates.map((template) => (
            <div key={template.id} style={{ border: "1px solid #ccc", borderRadius: "8px", padding: "15px" }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                <h3>{template.name}</h3>
