import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(":memory:");

interface TemplateRow {
  id: number;
  name: string;
  description: string;
  checklist_items: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS templates (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    description TEXT,
    checklist_items TEXT NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllTemplates(): TemplateRow[] {
  const stmt = db.prepare(`SELECT * FROM templates`);
  return stmt.all() as unknown as TemplateRow[];
}

export function getTemplateById(id: number): TemplateRow | undefined {
  const stmt = db.prepare(`SELECT * FROM templates WHERE id = ?`);
  return stmt.get(id) as unknown as TemplateRow | undefined;
}

export function insertTemplate(template: Omit<TemplateRow, "id">): number {
  const stmt = db.prepare(
    `INSERT INTO templates (name, description, checklist_items) VALUES (?, ?, ?)`
  );
  const result = stmt.run(template.name, template.description, template.checklist_items);
  return Number(result.lastInsertRowid);
}

export function updateTemplate(
  id: number,
  template: Partial<Omit<TemplateRow, "id">>
): boolean {
  const updates: string[] = [];
  const values: (string | number)[] = [id];

  if (template.name !== undefined) {
    updates.push("name = ?");
    values.push(template.name);
  }

  if (template.description !== undefined) {
    updates.push("description = ?");
    values.push(template.description);
  }

  if (template.checklist_items !== undefined) {
    updates.push("checklist_items = ?");
    values.push(template.checklist_items);
  }

  if (updates.length === 0) {
    return false;
  }

  const sql = `UPDATE templates SET ${updates.join(", ")} WHERE id = ?`;
  const stmt = db.prepare(sql);
  const result = stmt.run(...values);
  return result.changes > 0;
}

export function deleteTemplate(id: number): boolean {
  const stmt = db.prepare(`DELETE FROM templates WHERE id = ?`);
  const result = stmt.run(id);
  return result.changes > 0;
}

