import type { Request, Response, NextFunction } from "express";
import { Router } from "express";
import { router as inspectionRouter } from "../routes/inspection-api";
import { router as templateRouter } from "../routes/template-api";
import { router as authRouter } from "../routes/authentication-api";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Skip validation for GET requests to authentication endpoints
  if (req.method === "GET" && req.path.startsWith("/auth")) {
    return next();
  }

  // Only enforce role-based access control on specific routes
  const isInspectionRoute = req.path.startsWith("/inspections") && 
    (req.method === "POST" || req.method === "PUT" || req.method === "DELETE");

  const isTemplateRoute = req.path.startsWith("/templates") && 
    (req.method === "POST" || req.method === "PUT" || req.method === "DELETE");

  // If not a protected route, continue
  if (!isInspectionRoute && !isTemplateRoute) {
    return next();
  }

  // Check for authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return res.status(401).json({ error: "Unauthorized" });
  }

  const token = authHeader.substring(7);

  // In a real implementation, we would decode and verify the JWT here
  // For now, we'll simulate a basic verification
  try {
    // This is a placeholder - in reality, you'd verify the JWT signature
    // using HMAC-SHA256 with process.env.JWT_SECRET
    const payload = JSON.parse(atob(token.split(".")[1]));

    // Simulate role checking
    const userRole = payload.role;

    if (!userRole) {
      return res.status(401).json({ error: "Invalid token" });
    }

    // Allow only admin users to modify inspections or templates
    if ((isInspectionRoute || isTemplateRoute) && userRole !== "admin") {
      return res.status(403).json({ error: "Forbidden" });
    }

    next();
  } catch (error) {
    return res.status(401).json({ error: "Invalid token" });
  }
}

