import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock file storage service - in a real implementation, this would interact with a cloud storage service
const fileStorage = new Map<string, { fileName: string; fileData: Buffer; contentType: string }>();

// Upload a file
router.post("/upload", (req: Request, res: Response) => {
  // In a real implementation, we would handle multipart form data
  // For this mock, we'll assume file data is passed in the body

  if (!req.body.fileName || !req.body.fileData || !req.body.contentType) {
    return res.status(400).json({ error: "fileName, fileData, and contentType are required" });
  }

  const fileId = Date.now().toString();
  fileStorage.set(fileId, {
    fileName: req.body.fileName,
    fileData: Buffer.from(req.body.fileData, "base64"),
    contentType: req.body.contentType
  });

  return res.status(201).json({ fileId });
});

// Retrieve a file by ID
router.get("/:fileId", (req: Request, res: Response) => {
  const fileId = req.params.fileId;

  const file = fileStorage.get(fileId);

  if (!file) {
    return res.status(404).json({ error: "File not found" });
  }

  return res.json({
    fileName: file.fileName,
    fileData: file.fileData.toString("base64"),
    contentType: file.contentType
  });
});

// Delete a file by ID
router.delete("/:fileId", (req: Request, res: Response) => {
  const fileId = req.params.fileId;

  const deleted = fileStorage.delete(fileId);

  if (!deleted) {
    return res.status(404).json({ error: "File not found" });
  }

  return res.json({ message: "File deleted successfully" });
});

import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock data structures to simulate database operations
const evaluations = new Map<string, any>();
const scores = new Map<string, any>();
const finalResults = new Map<string, any>();

// Helper function to generate unique ID
const generateId = () => Math.random().toString(36).substr(2, 9);

// POST /judging/evaluate - Process team evaluation
router.post("/evaluate", (req: Request, res: Response) => {
  const { teamId, criteria, score, judgeId } = req.body;

  if (!teamId || !criteria || score === undefined || !judgeId) {
    return res.status(400).json({ error: "Missing required fields: teamId, criteria, score, judgeId" });
  }

  const evaluationId = generateId();
  const evaluation = {
    id: evaluationId,
    teamId,
    criteria,
    score,
    judgeId,
    timestamp: new Date(),
  };

  evaluations.set(evaluationId, evaluation);

  return res.status(201).json(evaluation);
});

// GET /judging/evaluate/:id - Get specific evaluation by ID
router.get("/evaluate/:id", (req: Request, res: Response) => {
  const { id } = req.params;
  const evaluation = evaluations.get(id);

  if (!evaluation) {
    return res.status(404).json({ error: "Evaluation not found" });
  }

  return res.json(evaluation);
});

// PUT /judging/evaluate/:id - Update an existing evaluation
router.put("/evaluate/:id", (req: Request, res: Response) => {
  const { id } = req.params;
  const { criteria, score } = req.body;

  const evaluation = evaluations.get(id);

  if (!evaluation) {
    return res.status(404).json({ error: "Evaluation not found" });
  }

  if (criteria !== undefined) evaluation.criteria = criteria;
  if (score !== undefined) evaluation.score = score;
  evaluation.timestamp = new Date();

  evaluations.set(id, evaluation);

  return res.json(evaluation);
});

// DELETE /judging/evaluate/:id - Delete an evaluation
router.delete("/evaluate/:id", (req: Request, res: Response) => {
  const { id } = req.params;

  const deleted = evaluations.delete(id);

  if (!deleted) {
    return res.status(404).json({ error: "Evaluation not found" });
  }

  return res.json({ message: "Evaluation deleted successfully" });
});

// POST /judging/score - Track team scores
router.post("/score", (req: Request, res: Response) => {
  const { teamId, totalScore } = req.body;

  if (!teamId || totalScore === undefined) {
    return res.status(400).json({ error: "Missing required fields: teamId, totalScore" });
  }

  const scoreId = generateId();
  const scoreEntry = {
    id: scoreId,
    teamId,
    totalScore,
    timestamp: new Date(),
  };

  scores.set(scoreId, scoreEntry);

  return res.status(201).json(scoreEntry);
});

// GET /judging/score/:teamId - Get scores for a specific team
router.get("/score/:teamId", (req: Request, res: Response) => {
  const { teamId } = req.params;

  const teamScores = [];
  for (const [_, score] of scores.entries()) {
    if (score.teamId === teamId) {
      teamScores.push(score);
    }
  }

  if (teamScores.length === 0) {
    return res.status(404).json({ error: "No scores found for this team" });
  }

  return res.json(teamScores);
});

// POST /judging/final-result - Record final judging result
router.post("/final-result", (req: Request, res: Response) => {
  const { teamId, finalScore, winner } = req.body;

  if (!teamId || finalScore === undefined) {
    return res.status(400).json({ error: "Missing required fields: teamId, finalScore" });
  }

  const resultId = generateId();
  const finalResult = {
    id: resultId,
    teamId,
    finalScore,
    winner: winner || false,
    timestamp: new Date(),
  };

  finalResults.set(resultId, finalResult);

  return res.status(201).json(finalResult);
});

// GET /judging/final-result/:teamId - Get final result for a specific team
router.get("/final-result/:teamId", (req: Request, res: Response) => {
  const { teamId } = req.params;

  let teamResult = null;
  for (const [_, result] of finalResults.entries()) {
    if (result.teamId === teamId) {
      teamResult = result;
      break;
    }
  }

  if (!teamResult) {
    return res.status(404).json({ error: "Final result not found for this team" });
  }

  return res.json(teamResult);
});

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to /login endpoint
  if (!(req.method === "POST" && req.path === "/login")) {
    next();
    return;
  }

  const secret = process.env.JWT_SECRET;
  if (!secret) {
    res.status(500).json({ error: "Internal server error" });
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7);
  const [payload, signature] = token.split(".");
  if (!payload || !signature) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const expectedSignature = createHmac("sha256", secret)
    .update(payload)
    .digest("base64url");

  const signatureBuffer = Buffer.from(signature, "base64url");
  const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

  try {
    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      res.status(401).json({ error: "Unauthorized" });
      return;
    }
  } catch {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  next();
}

import type { Request, Response, NextFunction } from "express";
