          />
        </div>

        <div>
          <label style={{ display: 'block', marginBottom: '5px' }}>
            Team Members
          </label>
          {members.map((member, index) => (
            <div key={index} style={{ display: 'flex', gap: '10px', marginBottom: '10px' }}>
