import { useEffect, useState } from "react";

interface Team {
  id: number;
  name: string;
  members: string[];
  projectDescription: string;
}

export function TeamListPage() {
  const [teams, setTeams] = useState<Team[]>([]);
  const [searchTerm, setSearchTerm] = useState("");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchTeams = async () => {
      try {
        const response = await fetch(`/api/teams`);
        if (!response.ok) {
          throw new Error(`Failed to fetch teams: ${response.status}`);
        }
        const data = await response.json();
        setTeams(data);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    };

    fetchTeams();
  }, []);

  const filteredTeams = teams.filter(team =>
    team.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    team.members.some(member => 
      member.toLowerCase().includes(searchTerm.toLowerCase())
    )
  );

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  return (
    <div style={{
      maxWidth: "800px",
      margin: "0 auto",
      padding: "20px",
      fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif"
    }}>
      <h1 style={{ textAlign: "center" }}>Hackathon Teams</h1>

      <div style={{ marginBottom: "20px" }}>
        <input
          type="text"
          placeholder="Search teams..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          style={{
            width: "100%",
            padding: "10px",
            borderRadius: "4px",
            border: "1px solid #ccc",
            fontSize: "16px"
          }}
        />
      </div>

      {filteredTeams.length === 0 ? (
        <p style={{ textAlign: "center", padding: "20px" }}>
          {searchTerm ? "No teams found matching your search." : "No teams registered yet."}
        </p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
          {filteredTeams.map(team => (
            <div 
              key={team.id} 
              style={{
                border: "1px solid #ddd",
                borderRadius: "8px",
                padding: "15px",
                backgroundColor: "#f9f9f9"
              }}
            >
              <h3 style={{ margin: "0 0 10px 0", color: "#333" }}>
                {team.name}
              </h3>
              <p style={{ margin: "5px 0", color: "#555" }}>
                <strong>Members:</strong> {team.members.join(", ")}
              </p>
              <p style={{ margin: "5px 0", color: "#555" }}>
                <strong>Description:</strong> {team.projectDescription}
              </p>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

