// Define the allowed file extensions
const ALLOWED_EXTENSIONS = ["pdf", "doc", "docx", "txt", "jpg", "jpeg", "png"];

// Define maximum file size in bytes (e.g., 5MB)
const MAX_FILE_SIZE = 5 * 1024 * 1024;

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST and PUT requests with file uploads
  if ((req.method !== "POST" && req.method !== "PUT") || !req.path.includes("upload")) {
    next();
    return;
  }

  // Check if there are files in the request
  if (!req.files || !Array.isArray(req.files)) {
    next();
    return;
  }

  // Validate file sizes
  for (const file of req.files) {
    if (file.size > MAX_FILE_SIZE) {
      return res.status(413).json({ error: "File too large" });
    }
  }

  // Validate file types
  for (const file of req.files) {
    const fileExtension = file.originalname.split(".").pop()?.toLowerCase();
    if (!fileExtension || !ALLOWED_EXTENSIONS.includes(fileExtension)) {
      return res.status(400).json({ error: "Invalid file type" });
    }
  }

  // Simulate malware scan (in a real implementation, integrate with antivirus)
  for (const file of req.files) {
    if (file.originalname.includes("malware")) {
      return res.status(400).json({ error: "Malware detected" });
    }
  }

  // If all validations pass, continue to the next middleware/route handler
  next();
}

