import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to specific routes
  const adminPaths = ["/admin", "/admin/"];
  const isProtectedPath = adminPaths.some(path => 
    req.path === path || req.path.startsWith(path + "/")
  );

  if (!isProtectedPath) {
    next();
    return;
  }

  // Check if user has required role
  const userRole = req.headers["x-user-role"] as string | undefined;

  if (!userRole) {
    res.status(401).json({ error: "Unauthorized: Missing role header" });
    return;
  }

  // For demonstration purposes, we'll assume admin role is required
  // In a real implementation, this would check against a database or config
  if (userRole !== "admin") {
    res.status(403).json({ error: "Forbidden: Insufficient permissions" });
    return;
  }

  // User has proper role, proceed
  next();
