  return mockRequests.find(request => request.id === id);
};

const createRequest = (request: any) => {
  const newId = Math.max(0, ...mockRequests.map(r => r.id)) + 1;
  const newRequest = { ...request, id: newId };
  mockRequests.push(newRequest);
  return newRequest;
};

const updateRequest = (id: number, updates: any) => {
  const index = mockRequests.findIndex(request => request.id === id);
  if (index === -1) return null;
  mockRequests[index] = { ...mockRequests[index], ...updates };
  return mockRequests[index];
};

const deleteRequest = (id: number) => {
  const index = mockRequests.findIndex(request => request.id === id);
  if (index === -1) return false;
  mockRequests.splice(index, 1);
  return true;
};

