  const { name } = req.body;

  if (!name || typeof name !== "string") {
    return res.status(400).json({ error: "Name is required and must be a string" });
  }

  const newItem = {
    id: nextId++,
    name,
    purchased: false
  };

  shoppingListItems.push(newItem);

  res.status(201).json(newItem);
});

