  const { purchased } = req.body;

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid item ID" });
  }

  if (typeof purchased !== "boolean") {
    return res.status(400).json({ error: "Purchased status is required and must be a boolean" });
  }

  const itemIndex = shoppingListItems.findIndex(item => item.id === id);

  if (itemIndex === -1) {
    return res.status(404).json({ error: "Shopping list item not found" });
  }

  shoppingListItems[itemIndex].purchased = purchased;

  res.json(shoppingListItems[itemIndex]);
});

// DELETE /shopping-list/:id - Remove a shopping list item
router.delete("/shopping-list/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid item ID" });
  }

  const itemIndex = shoppingListItems.findIndex(item => item.id === id);

  if (itemIndex === -1) {
    return res.status(404).json({ error: "Shopping list item not found" });
  }

  shoppingListItems.splice(itemIndex, 1);

  res.json({ message: "Item removed successfully" });
});

