            required
            style={{
              width: "100%",
              padding: "8px",
              borderRadius: "4px",
              border: "1px solid #ccc",
            }}
          />
        </div>

        <div>
          <label htmlFor="quantity" style={{ display: "block", marginBottom: "5px" }}>
            Quantity
          </label>
