import { useEffect, useState } from "react";

interface ShoppingListItem {
  id: string;
  name: string;
  category: string;
  purchased: boolean;
}

export function ShoppingListPage() {
  const [items, setItems] = useState<ShoppingListItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchShoppingList();
  }, []);

  const fetchShoppingList = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/shopping-list');
      if (!response.ok) {
        throw new Error('Failed to fetch shopping list');
      }
      const data = await response.json();
      setItems(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const togglePurchased = async (id: string) => {
    try {
      const response = await fetch(`/api/shopping-list/${id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ purchased: true }),
      });

      if (!response.ok) {
        throw new Error('Failed to update item');
      }

      setItems(items.map(item => 
        item.id === id ? { ...item, purchased: true } : item
      ));
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  if (items.length === 0) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>No items in shopping list</div>;
  }

  // Group items by category
  const groupedItems: Record<string, ShoppingListItem[]> = {};
  items.forEach(item => {
    if (!groupedItems[item.category]) {
      groupedItems[item.category] = [];
    }
    groupedItems[item.category].push(item);
  });

  const categories = Object.keys(groupedItems);

  return (
    <div style={{
      maxWidth: '600px',
      margin: '0 auto',
      padding: '20px',
      fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif'
    }}>
      <h1 style={{ textAlign: 'center' }}>Shopping List</h1>

      {categories.map(category => (
        <div key={category} style={{ marginBottom: '30px' }}>
          <h2 style={{
            borderBottom: '1px solid #ccc',
            paddingBottom: '5px',
            marginBottom: '10px'
          }}>
            {category}
          </h2>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
            {groupedItems[category].map(item => (
              <div 
                key={item.id} 
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  padding: '10px',
                  border: '1px solid #ddd',
                  borderRadius: '5px',
                  backgroundColor: item.purchased ? '#f0f8f0' : 'white'
                }}
              >
                <input
                  type="checkbox"
                  checked={item.purchased}
                  onChange={() => togglePurchased(item.id)}
                  style={{ marginRight: '10px' }}
                />
                <span style={{
                  textDecoration: item.purchased ? 'line-through' : 'none',
                  flexGrow: 1
                }}>
                  {item.name}
                </span>
              </div>
            ))}
          </div>
        </div>
      ))}
    </div>
  );
}

