import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("shop.db");

interface Product {
  id: number;
  name: string;
  price: number;
  sku: string;
  category: string;
  quantity: number;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS products (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    price REAL NOT NULL,
    sku TEXT UNIQUE NOT NULL,
    category TEXT NOT NULL,
    quantity INTEGER NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllProducts(): Product[] {
  const stmt = db.prepare("SELECT * FROM products");
  return stmt.all() as unknown as Product[];
}

export function getProductById(id: number): Product | undefined {
  const stmt = db.prepare("SELECT * FROM products WHERE id = ?");
  return stmt.get(id) as unknown as Product | undefined;
}

export function insertProduct(product: Omit<Product, "id">): number {
  const stmt = db.prepare(
    "INSERT INTO products (name, price, sku, category, quantity) VALUES (?, ?, ?, ?, ?)"
  );
  const result = stmt.run(product.name, product.price, product.sku, product.category, product.quantity);
  return Number(result.lastInsertRowid);
}

export function updateProduct(id: number, product: Partial<Omit<Product, "id">>): boolean {
  const fields = [];
  const values = [];

  if (product.name !== undefined) {
    fields.push("name = ?");
    values.push(product.name);
  }

  if (product.price !== undefined) {
    fields.push("price = ?");
    values.push(product.price);
  }

  if (product.sku !== undefined) {
    fields.push("sku = ?");
    values.push(product.sku);
  }

  if (product.category !== undefined) {
    fields.push("category = ?");
    values.push(product.category);
  }

  if (product.quantity !== undefined) {
    fields.push("quantity = ?");
    values.push(product.quantity);
  }

  if (fields.length === 0) return false;

  values.push(id);

  const sql = `UPDATE products SET ${fields.join(", ")} WHERE id = ?`;
  const stmt = db.prepare(sql);
  stmt.run(...values);

  return true;
}

export function deleteProduct(id: number): boolean {
  const stmt = db.prepare("DELETE FROM products WHERE id = ?");
  const result = stmt.run(id);
  return result.changes > 0;
}

