    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid sale ID" });
    }

    const deleted = deleteSale(id);
    if (!deleted) {
      return res.status(404).json({ error: "Sale not found" });
    }

    return res.json({ message: "Sale deleted successfully" });
  } catch (error) {
    return res.status(500).json({ error: "Failed to delete sale" });
  }
});

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const ROLES = {
  cashier: ["POST", "/sales"],
  manager: ["POST", "/sales", "PUT", "/products", "DELETE", "/products"],
};

function getRoleFromToken(token: string): string | null {
  const secret = process.env.JWT_SECRET;
  if (!secret) return null;

  try {
    const [header, payload, signature] = token.split(".");
    if (!header || !payload || !signature) return null;

    const expectedSignature = createHmac("sha256", secret)
      .update(`${header}.${payload}`)
      .digest();

    const actualSignature = Buffer.from(signature, "base64");

    if (actualSignature.length !== expectedSignature.length) return null;

    if (!timingSafeEqual(expectedSignature, actualSignature)) return null;

    const decodedPayload = JSON.parse(Buffer.from(payload, "base64").toString());
    return decodedPayload.role || null;
  } catch {
    return null;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check role-based access for specific methods and paths
  const isSalesRequest = req.method === "POST" && req.path === "/sales";
  const isProductRequest = (req.method === "PUT" || req.method === "DELETE") && req.path.startsWith("/products");

  if (!isSalesRequest && !isProductRequest) {
    next();
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7);
  const userRole = getRoleFromToken(token);

  if (!userRole) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const allowedMethodsAndPaths = ROLES[userRole as keyof typeof ROLES];
  if (!allowedMethodsAndPaths) {
    res.status(403).json({ error: "Forbidden" });
    return;
  }

  const isAllowed = allowedMethodsAndPaths.includes(req.method) &&
    (req.path === "/sales" || req.path.startsWith("/products"));

  if (!isAllowed) {
    res.status(403).json({ error: "Forbidden" });
    return;
  }

  next();
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only protect POST /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  // Check if JWT_SECRET is set
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // Check if request has authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Missing or invalid authorization header" });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '

  // Verify token signature
  const expectedSignature = createHmac("sha256", secret)
    .update(token.split(".")[0] + "." + token.split(".")[1])
    .digest();

  const actualSignature = Buffer.from(token.split(".")[2], "base64");

  try {
    const isValid = timingSafeEqual(expectedSignature, actualSignature);
    if (!isValid) {
      res.status(401).json({ error: "Invalid token" });
      return;
    }
  } catch {
    res.status(401).json({ error: "Invalid token" });
    return;
  }

  // If we get here, token is valid
  next();
}

import { useEffect, useState } from "react";

interface Product {
  id: number;
  name: string;
  price: number;
}

interface CartItem {
  product: Product;
  quantity: number;
}

export function PosPage() {
  const [products, setProducts] = useState<Product[]>([]);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [searchTerm, setSearchTerm] = useState("");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchProducts();
  }, []);

  const fetchProducts = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/product-management-api/");
      if (!response.ok) {
        throw new Error(`Failed to fetch products: ${response.status}`);
      }
      const data = await response.json();
      setProducts(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const addToCart = (product: Product) => {
    setCart(prevCart => {
      const existingItem = prevCart.find(item => item.product.id === product.id);
      if (existingItem) {
        return prevCart.map(item =>
          item.product.id === product.id
            ? { ...item, quantity: item.quantity + 1 }
            : item
        );
      } else {
        return [...prevCart, { product, quantity: 1 }];
      }
    });
  };

  const removeFromCart = (productId: number) => {
    setCart(prevCart => prevCart.filter(item => item.product.id !== productId));
  };

  const updateQuantity = (productId: number, quantity: number) => {
    if (quantity <= 0) {
      removeFromCart(productId);
      return;
    }
    setCart(prevCart =>
      prevCart.map(item =>
        item.product.id === productId ? { ...item, quantity } : item
      )
    );
  };

  const totalAmount = cart.reduce(
    (total, item) => total + item.product.price * item.quantity,
    0
  );

  const filteredProducts = products.filter(product =>
    product.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: "center", padding: "20px", color: "red" }}>
        Error: {error}
      </div>
    );
  }

  return (
    <div
      style={{
        maxWidth: "800px",
        margin: "0 auto",
        padding: "20px",
        fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
      }}
    >
      <h1 style={{ textAlign: "center" }}>Point of Sale</h1>

      <div style={{ marginBottom: "20px" }}>
        <input
          type="text"
          placeholder="Search products..."
          value={searchTerm}
          onChange={e => setSearchTerm(e.target.value)}
          style={{
            width: "100%",
            padding: "10px",
            borderRadius: "4px",
            border: "1px solid #ccc",
          }}
        />
      </div>

      <div
        style={{
          display: "flex",
          flexWrap: "wrap",
          gap: "15px",
          marginBottom: "30px",
        }}
      >
        {filteredProducts.length > 0 ? (
          filteredProducts.map(product => (
            <div
              key={product.id}
              style={{
                border: "1px solid #ddd",
                borderRadius: "8px",
                padding: "15px",
                width: "calc(33.333% - 15px)",
                boxSizing: "border-box",
                backgroundColor: "#f9f9f9",
              }}
            >
              <h3>{product.name}</h3>
              <p>${product.price.toFixed(2)}</p>
              <button
                onClick={() => addToCart(product)}
                style={{
                  backgroundColor: "#007bff",
                  color: "white",
                  border: "none",
                  padding: "8px 12px",
                  borderRadius: "4px",
                  cursor: "pointer",
                  width: "100%",
                }}
              >
                Add to Cart
              </button>
            </div>
          ))
        ) : (
          <p>No products found.</p>
        )}
      </div>

      <div
        style={{
          border: "1px solid #ddd",
          borderRadius: "8px",
          padding: "20px",
          backgroundColor: "#f9f9f9",
        }}
      >
        <h2>Shopping Cart</h2>
        {cart.length === 0 ? (
          <p>Your cart is empty.</p>
        ) : (
          <>
            {cart.map(item => (
              <div
                key={item.product.id}
                style={{
                  display: "flex",
                  justifyContent: "space-between",
                  alignItems: "center",
                  marginBottom: "10px",
                  padding: "10px",
                  borderBottom: "1px solid #eee",
                }}
              >
                <span>
                  {item.product.name} - ${item.product.price.toFixed(2)}
                </span>
                <div style={{ display: "flex", alignItems: "center", gap: "10px" }}>
                  <button
                    onClick={() => updateQuantity(item.product.id, item.quantity - 1)}
                    style={{
                      backgroundColor: "#6c757d",
                      color: "white",
                      border: "none",
                      padding: "4px 8px",
                      borderRadius: "4px",
                      cursor: "pointer",
                    }}
                  >
                    -
                  </button>
                  <span>{item.quantity}</span>
                  <button
                    onClick={() => updateQuantity(item.product.id, item.quantity + 1)}
                    style={{
                      backgroundColor: "#6c757d",
                      color: "white",
                      border: "none",
                      padding: "4px 8px",
                      borderRadius: "4px",
                      cursor: "pointer",
                    }}
                  >
                    +
                  </button>
                  <button
                    onClick={() => removeFromCart(item.product.id)}
                    style={{
                      backgroundColor: "#dc3545",
                      color: "white",
                      border: "none",
                      padding: "4px 8px",
                      borderRadius: "4px",
                      cursor: "pointer",
                    }}
                  >
                    Remove
                  </button>
                </div>
              </div>
            ))}
            <div
              style={{
                marginTop: "20px",
                paddingTop: "10px",
                borderTop: "1px solid #ddd",
                fontWeight: "bold",
              }}
            >
              Total: ${totalAmount.toFixed(2)}
            </div>
            <button
              onClick={async () => {
                try {
                  const response = await fetch("/api/sales-processing-api/", {
                    method: "POST",
                    headers: { "Content-Type": "application/json" },
                    body: JSON.stringify({ items: cart }),
                  });
                  if (!response.ok) {
                    throw new Error(`Failed to process sale: ${response.status}`);
                  }
                  alert("Sale processed successfully!");
                  setCart([]);
                } catch (err) {
                  setError(err instanceof Error ? err.message : "An unknown error occurred");
                }
              }}
              style={{
                backgroundColor: "#28a745",
                color: "white",
                border: "none",
                padding: "12px 20px",
                borderRadius: "4px",
                cursor: "pointer",
                width: "100%",
                marginTop: "20px",
                fontSize: "16px",
              }}
            >
              Process Payment
            </button>
          </>
        )}
      </div>
    </div>
  );
}

