import { useEffect, useState } from "react";

interface Sale {
  id: string;
  productId: string;
  productName: string;
  quantity: number;
  price: number;
  total: number;
  date: string;
}

export function SalesHistoryPage() {
  const [sales, setSales] = useState<Sale[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [filterDate, setFilterDate] = useState("");
  const [filterProduct, setFilterProduct] = useState("");

  useEffect(() => {
    fetchSales();
  }, []);

  const fetchSales = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/sales-processing-api/");
      if (!response.ok) {
        throw new Error(`Failed to fetch sales: ${response.status}`);
      }
      const data = await response.json();
      setSales(data);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const filteredSales = sales.filter(sale => {
    const matchesDate = filterDate ? sale.date.includes(filterDate) : true;
    const matchesProduct = filterProduct ? sale.productName.toLowerCase().includes(filterProduct.toLowerCase()) : true;
    return matchesDate && matchesProduct;
  });

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "system-ui, sans-serif" }}>
      <h1>Sales History</h1>

      <div style={{ marginBottom: "20px", display: "flex", flexDirection: "column", gap: "10px" }}>
        <input
          type="date"
          value={filterDate}
          onChange={(e) => setFilterDate(e.target.value)}
          placeholder="Filter by date"
          style={{ width: "100%", padding: "8px" }}
        />
        <input
          type="text"
          value={filterProduct}
          onChange={(e) => setFilterProduct(e.target.value)}
          placeholder="Filter by product name"
          style={{ width: "100%", padding: "8px" }}
        />
      </div>

      {filteredSales.length === 0 ? (
        <p style={{ textAlign: "center", padding: "20px" }}>No sales found.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          {filteredSales.map((sale) => (
            <div key={sale.id} style={{ border: "1px solid #ccc", borderRadius: "8px", padding: "15px" }}>
              <div style={{ display: "flex", justifyContent: "space-between", marginBottom: "5px" }}>
                <span><strong>{sale.productName}</strong></span>
                <span>${sale.total.toFixed(2)}</span>
              </div>
              <div style={{ display: "flex", justifyContent: "space-between", fontSize: "0.9em", color: "#666" }}>
                <span>{sale.quantity} x ${sale.price.toFixed(2)}</span>
                <span>{new Date(sale.date).toLocaleDateString()}</span>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

