  { id: 2, title: "Advanced React Patterns", speaker: "Jane Smith", startTime: "10:30", endTime: "11:30", roomId: "B202" }
];

const findTalkById = (id: number) => {
  return mockTalks.find(talk => talk.id === id);
};

const createTalk = (talk: Omit<Talk, 'id'>) => {
  const newId = Math.max(0, ...mockTalks.map(t => t.id)) + 1;
  const newTalk = { ...talk, id: newId };
  mockTalks.push(newTalk);
  return newTalk;
};

const updateTalk = (id: number, updatedTalk: Partial<Talk>) => {
  const index = mockTalks.findIndex(talk => talk.id === id);
  if (index === -1) return null;
  mockTalks[index] = { ...mockTalks[index], ...updatedTalk };
  return mockTalks[index];
};

const deleteTalk = (id: number) => {
  const index = mockTalks.findIndex(talk => talk.id === id);
  if (index === -1) return false;
  mockTalks.splice(index, 1);
  return true;
};

