import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const JWT_SECRET = process.env.JWT_SECRET;

function isValidToken(token: string): boolean {
  if (!JWT_SECRET) return false;

  const parts = token.split(".");
  if (parts.length !== 3) return false;

  const [header, payload, signature] = parts;

  const expectedSignature = createHmac("sha256", JWT_SECRET)
    .update(`${header}.${payload}`)
    .digest("base64url");

  try {
    const expectedBytes = Buffer.from(expectedSignature, "base64url");
    const actualBytes = Buffer.from(signature, "base64url");

    return timingSafeEqual(expectedBytes, actualBytes);
  } catch {
    return false;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check authentication for POST /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  const authHeader = req.headers["authorization"];

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7); // Remove "Bearer " prefix

  if (!isValidToken(token)) {
    res.status(401).json({ error: "Invalid token" });
    return;
  }

  next();
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to specific routes
  const protectedPaths = ["/admin", "/organizer", "/attendee"];
  const isProtectedPath = protectedPaths.some(path =>
    req.path.startsWith(path)
  );

  if (!isProtectedPath) {
    next();
    return;
  }

  // Check for authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
    return;
  }

  const token = authHeader.substring(7); // Remove "Bearer " prefix

  // Validate token signature
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    res.status(500).json({ error: "Server configuration error: JWT_SECRET not set" });
    return;
  }

  // Simple token validation (in a real app, you'd decode and verify properly)
  const [payload, signature] = token.split(".");
  if (!payload || !signature) {
    res.status(401).json({ error: "Unauthorized: Invalid token format" });
    return;
  }

  // Recreate the signature for comparison
  const expectedSignature = createHmac("sha256", secret)
    .update(payload)
    .digest("base64url");

  // Use timingSafeEqual to prevent timing attacks
  try {
    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedBuffer = Buffer.from(expectedSignature, "base64url");

    if (!timingSafeEqual(signatureBuffer, expectedBuffer)) {
      res.status(401).json({ error: "Unauthorized: Invalid token signature" });
      return;
    }
  } catch (err) {
    res.status(401).json({ error: "Unauthorized: Invalid token" });
    return;
  }

  // For demo purposes, we'll assume the payload contains role info
  // In a real implementation, you'd decode the JWT properly
  const decodedPayload = Buffer.from(payload, "base64url").toString("utf8");
  let payloadObj: { role?: string } = {};
  try {
    payloadObj = JSON.parse(decodedPayload);
  } catch {
    res.status(401).json({ error: "Unauthorized: Invalid token payload" });
    return;
  }

  const userRole = payloadObj.role || "attendee";

  // Define role hierarchy
  const roles = ["attendee", "organizer", "administrator"];

  // Check if user has sufficient permissions
  const requiredRole = getRequiredRole(req.path);
  const userRoleIndex = roles.indexOf(userRole);
  const requiredRoleIndex = roles.indexOf(requiredRole);

  if (userRoleIndex < requiredRoleIndex) {
    res.status(403).json({ error: "Forbidden: Insufficient permissions" });
    return;
  }

  // Attach user role to request for downstream use
  (req as any).userRole = userRole;
  next();
}

function getRequiredRole(path: string): string {
  if (path.startsWith("/admin")) return "administrator";
  if (path.startsWith("/organizer")) return "organizer";
  return "attendee";
}

