import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const ROLES = {
  ADMIN: "admin",
  DRIVER: "driver",
  DISPATCHER: "dispatcher",
} as const;

const ALLOWED_ROLES = Object.values(ROLES);

interface DecodedToken {
  userId: string;
  role: typeof ROLES[keyof typeof ROLES];
}

function verifyTokenSignature(token: string, secret: string): boolean {
  const [header, payload, signature] = token.split(".");

  if (!header || !payload || !signature) {
    return false;
  }

  const expectedSignature = createHmac("sha256", secret)
    .update(`${header}.${payload}`)
    .digest("base64url");

  try {
    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    return timingSafeEqual(signatureBuffer, expectedSignatureBuffer);
  } catch {
    return false;
  }
}

function decodeToken(token: string): DecodedToken | null {
  try {
    const payload = token.split(".")[1];
    const decodedPayload = Buffer.from(payload, "base64").toString();
    return JSON.parse(decodedPayload);
  } catch {
    return null;
  }
}

function getRoleFromToken(token: string): string | null {
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    return null;
  }

  if (!verifyTokenSignature(token, secret)) {
    return null;
  }

  const decoded = decodeToken(token);

  if (!decoded || !ALLOWED_ROLES.includes(decoded.role)) {
    return null;
  }

  return decoded.role;
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to specific routes
  const protectedPaths = [
    /^\/api\/students\/.*/,
    /^\/api\/routes\/.*/,
    /^\/api\/drivers\/.*/,
    /^\/api\/dispatchers\/.*/,
  ];

  const isProtectedPath = protectedPaths.some(path => path.test(req.path));

  if (!isProtectedPath) {
    next();
    return;
  }

  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '

  const role = getRoleFromToken(token);

  if (!role) {
    res.status(401).json({ error: "Unauthorized: Invalid token" });
    return;
  }

  // Check if user has required permissions
  const requiredRoles = getRequiredRoles(req.method, req.path);

  if (!requiredRoles.includes(role)) {
    res.status(403).json({ error: "Forbidden: Insufficient permissions" });
    return;
  }

  // Attach role to request for downstream middleware or route handlers
  (req as any).userRole = role;

  next();
}

function getRequiredRoles(method: string, path: string): string[] {
  // Define role requirements per endpoint
  const roleRequirements: Record<string, string[]> = {
    "GET /api/students": [ROLES.ADMIN, ROLES.DRIVER, ROLES.DISPATCHER],
    "POST /api/students": [ROLES.ADMIN],
    "PUT /api/students": [ROLES.ADMIN],
    "DELETE /api/students": [ROLES.ADMIN],
    "GET /api/routes": [ROLES.ADMIN, ROLES.DRIVER, ROLES.DISPATCHER],
    "POST /api/routes": [ROLES.ADMIN],
    "PUT /api/routes": [ROLES.ADMIN],
    "DELETE /api/routes": [ROLES.ADMIN],
    "GET /api/drivers": [ROLES.ADMIN, ROLES.DISPATCHER],
    "POST /api/drivers": [ROLES.ADMIN],
    "PUT /api/drivers": [ROLES.ADMIN],
    "DELETE /api/drivers": [ROLES.ADMIN],
    "GET /api/dispatchers": [ROLES.ADMIN],
    "POST /api/dispatchers": [ROLES.ADMIN],
    "PUT /api/dispatchers": [ROLES.ADMIN],
    "DELETE /api/dispatchers": [ROLES.ADMIN],
  };

  const key = `${method} ${path}`;

  return roleRequirements[key] || [];
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const JWT_SECRET = process.env.JWT_SECRET;

// Helper to decode JWT without verification (for header/body extraction)
function base64UrlDecode(str: string): string {
  str += Array(4 - str.length % 4).join("=");
  return Buffer.from(str, "base64").toString();
}

// Extract payload from JWT (without verification)
function extractPayload(jwt: string): Record<string, any> | null {
  try {
    const parts = jwt.split(".");
    if (parts.length !== 3) return null;
    const payload = parts[1];
    return JSON.parse(base64UrlDecode(payload));
  } catch {
    return null;
  }
}

// Validate JWT signature
function isValidToken(token: string): boolean {
  if (!JWT_SECRET) return false;

  try {
    const parts = token.split(".");
    if (parts.length !== 3) return false;

    const [header, payload, signature] = parts;
    const expectedSignature = createHmac("sha256", JWT_SECRET)
      .update(`${header}.${payload}`)
      .digest("base64url");

    const actualSignature = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    return timingSafeEqual(actualSignature, expectedSignatureBuffer);
  } catch {
    return false;
  }
}

// Middleware to handle session management
export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  // Check if JWT_SECRET is set
  if (!JWT_SECRET) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // Check for Authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Missing or invalid authorization header" });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '

  // Validate token signature
  if (!isValidToken(token)) {
    res.status(401).json({ error: "Invalid token" });
    return;
  }

  // Extract payload to check expiration
  const payload = extractPayload(token);
  if (!payload || !payload.exp) {
    res.status(401).json({ error: "Invalid token payload" });
    return;
  }

  // Check if token has expired
  const now = Math.floor(Date.now() / 1000);
  if (payload.exp < now) {
    res.status(401).json({ error: "Token expired" });
    return;
  }

  // Token is valid, proceed
  next();
}

