export const router = Router();

// Mock user database - in a real app this would be a proper database
const users = [
  { id: 1, username: "hradmin", password: "secure123", role: "HR_ADMIN" },
  { id: 2, username: "hrcounselor", password: "secure123", role: "HR_COUNSELOR" },
];

// Mock session store - in a real app this would be a proper session store
const sessions = new Map<string, { userId: number; role: string }>();

// Login endpoint
router.post("/login", (req: Request, res: Response) => {
  const { username, password } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: "Username and password are required" });
  }

  const user = users.find(
    (u) => u.username === username && u.password === password
  );

  if (!user) {
    return res
      .status(401)
      .json({ error: "Invalid username or password" });
  }

  // Generate a mock session ID
  const sessionId = `session_${Math.random().toString(36).substr(2, 9)}`;
  sessions.set(sessionId, { userId: user.id, role: user.role });

  return res.json({
    sessionId,
    userId: user.id,
    role: user.role,
  });
});

// Session validation endpoint
router.get("/validate", (req: Request, res: Response) => {
  const sessionId = req.headers["x-session-id"] as string;

  if (!sessionId) {
    return res.status(401).json({ error: "No session ID provided" });
  }

  const session = sessions.get(sessionId);

  if (!session) {
    return res.status(401).json({ error: "Invalid session ID" });
  }

  return res.json({ valid: true, userId: session.userId, role: session.role });
});

// Logout endpoint
router.post("/logout", (req: Request, res: Response) => {
  const sessionId = req.headers["x-session-id"] as string;

  if (!sessionId) {
    return res.status(400).json({ error: "No session ID provided" });
  }

  sessions.delete(sessionId);

  return res.json({ message: "Logged out successfully" });
});

import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock database functions - in a real app these would come from a database module
const getApplicants = () => Promise.resolve([
  { id: 1, name: "John Doe", email: "john@example.com", position: "Software Engineer" },
  { id: 2, name: "Jane Smith", email: "jane@example.com", position: "Product Manager" }
]);

const getapplicantById = (id: number) => Promise.resolve(
  [{ id: 1, name: "John Doe", email: "john@example.com", position: "Software Engineer" },
   { id: 2, name: "Jane Smith", email: "jane@example.com", position: "Product Manager" }]
  .find(applicant => applicant.id === id)
);

const createApplicant = (applicantData: Omit<Applicant, "id">) => {
  const newApplicant = {
    id: Math.max(0, ...[1, 2].map(Number)) + 1,
    ...applicantData
  };
  return Promise.resolve(newApplicant);
};

const updateApplicant = (id: number, applicantData: Partial<Applicant>) => {
  const updatedApplicant = {
    id,
    ...applicantData
  };
  return Promise.resolve(updatedApplicant);
};

const deleteApplicant = (id: number) => Promise.resolve(true);

interface Applicant {
  id: number;
  name: string;
  email: string;
  position: string;
}

// GET /applicants - List all applicants
router.get("/applicants", async (req: Request, res: Response) => {
  try {
    const applicants = await getApplicants();
    res.json(applicants);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch applicants" });
  }
});

// GET /applicants/:id - Get a specific applicant by ID
router.get("/applicants/:id", async (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid applicant ID" });
    }
    const applicant = await getapplicantById(id);
    if (!applicant) {
      return res.status(404).json({ error: "Applicant not found" });
    }
    res.json(applicant);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch applicant" });
  }
});

// POST /applicants - Create a new applicant
router.post("/applicants", async (req: Request, res: Response) => {
  try {
    const { name, email, position } = req.body;
    if (!name || !email || !position) {
      return res.status(400).json({ error: "Name, email, and position are required" });
    }
    const newApplicant = await createApplicant({ name, email, position });
    res.status(201).json(newApplicant);
  } catch (error) {
    res.status(500).json({ error: "Failed to create applicant" });
  }
});

// PUT /applicants/:id - Update an existing applicant
router.put("/applicants/:id", async (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid applicant ID" });
    }
    const { name, email, position } = req.body;
    const updatedApplicant = await updateApplicant(id, { name, email, position });
    res.json(updatedApplicant);
  } catch (error) {
    res.status(500).json({ error: "Failed to update applicant" });
  }
});

// DELETE /applicants/:id - Delete an applicant
router.delete("/applicants/:id", async (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid applicant ID" });
    }
    const deleted = await deleteApplicant(id);
    if (!deleted) {
      return res.status(404).json({ error: "Applicant not found" });
    }
    res.json({ message: "Applicant deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete applicant" });
  }
});

