// Mock event data structure
interface Event {
  id: number;
  title: string;
  description: string;
  date: string;
  location: string;
}

// Mock database functions (these would be replaced with actual DB calls)
const mockEvents: Event[] = [
  { id: 1, title: "Community Picnic", description: "Annual picnic event", date: "2023-07-15", location: "Central Park" },
  { id: 2, title: "Tech Workshop", description: "Learn about web development", date: "2023-08-20", location: "Community Center" }
];

const getAllEvents = (): Event[] => {
  return mockEvents;
};

const getEventById = (id: number): Event | undefined => {
  return mockEvents.find(event => event.id === id);
};

const createEvent = (eventData: Omit<Event, 'id'>): Event => {
  const newEvent: Event = {
    id: mockEvents.length > 0 ? Math.max(...mockEvents.map(e => e.id)) + 1 : 1,
    ...eventData
  };
  mockEvents.push(newEvent);
  return newEvent;
};

const updateEvent = (id: number, eventData: Partial<Omit<Event, 'id'>>): Event | undefined => {
  const index = mockEvents.findIndex(event => event.id === id);
  if (index === -1) return undefined;

  mockEvents[index] = { ...mockEvents[index], ...eventData };
  return mockEvents[index];
};

const deleteEvent = (id: number): boolean => {
  const initialLength = mockEvents.length;
  const filteredEvents = mockEvents.filter(event => event.id !== id);
  mockEvents.length = 0;
  mockEvents.push(...filteredEvents);
  return mockEvents.length < initialLength;
};

// List all events
router.get("/events", (req: Request, res: Response) => {
  try {
    const events = getAllEvents();
    return res.json(events);
  } catch (error) {
    return res.status(500).json({ error: "Internal server error" });
  }
});

// Get one event by ID
router.get("/events/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid event ID" });
    }

    const event = getEventById(id);
    if (!event) {
      return res.status(404).json({ error: "Event not found" });
    }

    return res.json(event);
  } catch (error) {
    return res.status(500).json({ error: "Internal server error" });
  }
});

// Create a new event
router.post("/events", (req: Request, res: Response) => {
  try {
    const { title, description, date, location } = req.body;

    if (!title || !description || !date || !location) {
      return res.status(400).json({ error: "Missing required fields" });
    }

    const newEvent = createEvent({ title, description, date, location });
    return res.status(201).json(newEvent);
  } catch (error) {
    return res.status(500).json({ error: "Internal server error" });
  }
});

// Update an existing event
router.put("/events/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid event ID" });
    }

    const { title, description, date, location } = req.body;

    const updatedEvent = updateEvent(id, { title, description, date, location });

    if (!updatedEvent) {
      return res.status(404).json({ error: "Event not found" });
    }

    return res.json(updatedEvent);
  } catch (error) {
    return res.status(500).json({ error: "Internal server error" });
  }
});

// Delete an event
router.delete("/events/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid event ID" });
    }

    const deleted = deleteEvent(id);

    if (!deleted) {
      return res.status(404).json({ error: "Event not found" });
    }

    return res.json({ message: "Event deleted successfully" });
  } catch (error) {
    return res.status(500).json({ error: "Internal server error" });
  }
});

import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock user database
const users = new Map<string, { email: string; password: string }>();

// Mock session storage
const sessions = new Map<string, string>(); // sessionId -> userId

// Login route
router.post("/login", (req: Request, res: Response) => {
  const { email, password } = req.body;

  if (!email || !password) {
    return res.status(400).json({ error: "Email and password are required" });
  }

  const user = users.get(email);
  if (!user || user.password !== password) {
    return res.status(401).json({ error: "Invalid email or password" });
  }

  // Create session
  const sessionId = Math.random().toString(36).substring(2, 15);
  sessions.set(sessionId, email);

  res.json({ sessionId });
});

// Register route
router.post("/register", (req: Request, res: Response) => {
  const { email, password } = req.body;

  if (!email || !password) {
    return res.status(400).json({ error: "Email and password are required" });
  }

  if (users.has(email)) {
    return res.status(409).json({ error: "User already exists" });
  }

  users.set(email, { email, password });

  // Create session
  const sessionId = Math.random().toString(36).substring(2, 15);
  sessions.set(sessionId, email);

  res.status(201).json({ sessionId });
});

// Logout route
router.post("/logout", (req: Request, res: Response) => {
  const { sessionId } = req.body;

  if (!sessionId) {
    return res.status(400).json({ error: "Session ID is required" });
  }

  if (!sessions.has(sessionId)) {
    return res.status(401).json({ error: "Invalid session" });
  }

  sessions.delete(sessionId);
  res.json({ message: "Logged out successfully" });
});

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only enforce auth for event-related routes
  const eventRoutes = /^\/events(\/|$)/;
  if (!eventRoutes.test(req.path)) {
    next();
    return;
  }

  // Check if user is authenticated
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error: JWT_SECRET not set" });
    return;
  }

  // Verify token signature
  const [payload, signature] = token.split(".");
  if (!payload || !signature) {
    res.status(401).json({ error: "Unauthorized: Invalid token format" });
    return;
  }

  // Recreate the signature
  const expectedSignature = createHmac("sha256", secret)
    .update(payload)
    .digest("base64url");

  // Use timingSafeEqual to prevent timing attacks
  const isValid = timingSafeEqual(
    Buffer.from(signature, "base64url"),
    Buffer.from(expectedSignature, "base64url")
  );

  if (!isValid) {
    res.status(401).json({ error: "Unauthorized: Invalid token signature" });
    return;
  }

  // Decode payload (basic base64 decoding - in real app, proper JWT parsing would be used)
  try {
    const decodedPayload = Buffer.from(payload, "base64").toString("utf-8");
    const payloadObj = JSON.parse(decodedPayload);

    // Check if user has required permissions
    const isEventCreation = req.method === "POST" && req.path === "/events";
    const isEventEdit = req.method === "PUT" && req.path.match(/^\/events\/[^\/]+$/);
    const isAdminEdit = req.method === "DELETE" && req.path.match(/^\/events\/[^\/]+$/);

    if (isEventCreation || isEventEdit || isAdminEdit) {
      // For now, we'll assume valid token means authorized
      // In a real implementation, you'd check roles here
      next();
      return;
    }

    // If it's not an event creation/edit/delete, allow through
    next();
  } catch (err) {
    res.status(401).json({ error: "Unauthorized: Invalid token payload" });
    return;
  }
}

