          method: "DELETE",
        });
        if (!response.ok) {
          throw new Error(`Failed to delete event: ${response.status}`);
        }
        // In a real app, you'd redirect to a list page or show success message
        alert("Event deleted successfully");
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      }
    }
  };

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
