import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to specific routes and methods
  const protectedPaths = ["/api/trucks", "/api/maintenance", "/api/users"];
  const protectedMethods = ["POST", "PUT", "DELETE"];

  const isProtectedPath = protectedPaths.some(path =>
    req.path.startsWith(path)
  );

  if (!isProtectedPath || !protectedMethods.includes(req.method)) {
    next();
    return;
  }

  // Extract role from authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error: JWT_SECRET not set" });
    return;
  }

  try {
    // Simple token validation (in a real app, you'd decode and verify properly)
    const [role, signature] = token.split(":");
    if (!role || !signature) {
      res.status(401).json({ error: "Unauthorized: Invalid token format" });
      return;
    }

    // Verify signature using HMAC-SHA256
    const expectedSignature = createHmac("sha256", secret)
      .update(role)
      .digest("hex");

    const expectedBuffer = Buffer.from(expectedSignature);
    const actualBuffer = Buffer.from(signature);

    if (actualBuffer.length !== expectedBuffer.length ||
        !timingSafeEqual(expectedBuffer, actualBuffer)) {
      res.status(401).json({ error: "Unauthorized: Invalid token signature" });
      return;
    }

    // Check role permissions
    const allowedRoles = ["admin", "mechanic", "dispatcher"];
    if (!allowedRoles.includes(role)) {
      res.status(403).json({ error: "Forbidden: Insufficient permissions" });
      return;
    }

    // Attach role to request for downstream middleware/routes
    (req as any).userRole = role;
    next();
  } catch (error) {
    res.status(401).json({ error: "Unauthorized: Invalid token" });
  }
}

import { useEffect, useState } from "react";

interface Truck {
  id: number;
  make: string;
  model: string;
  year: number;
  licensePlate: string;
}

export function TruckManagementPage() {
  const [trucks, setTrucks] = useState<Truck[]>([]);
  const [searchTerm, setSearchTerm] = useState("");
  const [newTruck, setNewTruck] = useState({
    make: "",
    model: "",
    year: "",
    licensePlate: ""
  });
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchTrucks();
  }, []);

  const fetchTrucks = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/trucks");
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      const data = await response.json();
      setTrucks(data);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleSearchChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setSearchTerm(e.target.value);
  };

  const handleAddTruck = (e: React.FormEvent) => {
    e.preventDefault();

    // In a real app, this would POST to an API endpoint
    // For now, we'll just simulate adding a truck
    const truckToAdd: Truck = {
      id: trucks.length + 1,
      make: newTruck.make,
      model: newTruck.model,
      year: parseInt(newTruck.year),
      licensePlate: newTruck.licensePlate
    };

    setTrucks([...trucks, truckToAdd]);

    // Reset form
    setNewTruck({
      make: "",
      model: "",
      year: "",
      licensePlate: ""
    });
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setNewTruck({
      ...newTruck,
      [name]: value
    });
  };

  const filteredTrucks = trucks.filter(truck =>
    truck.make.toLowerCase().includes(searchTerm.toLowerCase()) ||
    truck.model.toLowerCase().includes(searchTerm.toLowerCase()) ||
    truck.licensePlate.toLowerCase().includes(searchTerm.toLowerCase())
  );

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  return (
    <div style={{
      maxWidth: "800px",
      margin: "0 auto",
      padding: "20px",
      fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif"
    }}>
      <h1 style={{ textAlign: "center" }}>Truck Management</h1>

      <div style={{ marginBottom: "20px" }}>
        <input
          type="text"
          placeholder="Search trucks..."
          value={searchTerm}
          onChange={handleSearchChange}
          style={{
            width: "100%",
            padding: "10px",
            borderRadius: "4px",
            border: "1px solid #ccc",
            fontSize: "16px"
          }}
        />
      </div>

      <div style={{ marginBottom: "30px" }}>
        <h2>Add New Truck</h2>
        <form onSubmit={handleAddTruck} style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          <input
            type="text"
            name="make"
            placeholder="Make"
            value={newTruck.make}
            onChange={handleInputChange}
            style={{
              padding: "10px",
              borderRadius: "4px",
              border: "1px solid #ccc",
              fontSize: "16px"
            }}
            required
          />
          <input
            type="text"
            name="model"
            placeholder="Model"
            value={newTruck.model}
            onChange={handleInputChange}
            style={{
              padding: "10px",
              borderRadius: "4px",
              border: "1px solid #ccc",
              fontSize: "16px"
            }}
            required
          />
          <input
            type="text"
            name="year"
            placeholder="Year"
            value={newTruck.year}
            onChange={handleInputChange}
            style={{
              padding: "10px",
              borderRadius: "4px",
              border: "1px solid #ccc",
              fontSize: "16px"
            }}
            required
          />
          <input
            type="text"
            name="licensePlate"
            placeholder="License Plate"
            value={newTruck.licensePlate}
            onChange={handleInputChange}
            style={{
              padding: "10px",
              borderRadius: "4px",
              border: "1px solid #ccc",
              fontSize: "16px"
            }}
            required
          />
          <button
            type="submit"
            style={{
              padding: "10px 15px",
              backgroundColor: "#007bff",
              color: "white",
              border: "none",
              borderRadius: "4px",
              cursor: "pointer",
              fontSize: "16px"
            }}
          >
            Add Truck
          </button>
        </form>
      </div>

      <h2>Truck List</h2>
      {filteredTrucks.length === 0 ? (
        <p style={{ textAlign: "center", padding: "20px" }}>No trucks found.</p>
      ) : (
        <div style={{ display: "flex", flexWrap: "wrap", gap: "15px" }}>
          {filteredTrucks.map(truck => (
            <div
              key={truck.id}
              style={{
                border: "1px solid #ddd",
                borderRadius: "8px",
                padding: "15px",
                width: "calc(50% - 15px)",
                boxSizing: "border-box"
              }}
            >
              <h3>{truck.make} {truck.model}</h3>
              <p>Year: {truck.year}</p>
              <p>License Plate: {truck.licensePlate}</p>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

