  const [tasks, setTasks] = useState<MaintenanceTask[]>([]);
  const [trucks, setTrucks] = useState<Truck[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedTruck, setSelectedTruck] = useState<number | "all">("all");
  const [startDate, setStartDate] = useState<string>("");
  const [endDate, setEndDate] = useState<string>("");

  useEffect(() => {
    const fetchData = async () => {
      try {
        setLoading(true);
        // In a real app, these would be API calls
        // For now, we'll simulate with mock data

        // Mock trucks
        const mockTrucks: Truck[] = [
          { id: 1, make: "Volvo", model: "VNL", year: 2020 },
          { id: 2, make: "Scania", model: "S", year: 2019 },
          { id: 3, make: "Mercedes-Benz", model: "Actros", year: 2021 },
        ];

        // Mock tasks
        const mockTasks: MaintenanceTask[] = [
          { id: 1, truckId: 1, description: "Oil Change", scheduledDate: "2023-06-15", status: "pending" },
          { id: 2, truckId: 2, description: "Brake Inspection", scheduledDate: "2023-06-18", status: "pending" },
          { id: 3, truckId: 1, description: "Tire Rotation", scheduledDate: "2023-06-20", status: "pending" },
          { id: 4, truckId: 3, description: "Engine Service", scheduledDate: "2023-06-22", status: "pending" },
        ];

        setTrucks(mockTrucks);
        setTasks(mockTasks);
        setError(null);
      } catch (err) {
        setError("Failed to load maintenance schedule");
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  const filteredTasks = tasks.filter(task => {
    const matchesTruck = selectedTruck === "all" || task.truckId === selectedTruck;

    if (!startDate && !endDate) return matchesTruck;

    const taskDate = new Date(task.scheduledDate);
    const start = startDate ? new Date(startDate) : null;
    const end = endDate ? new Date(endDate) : null;

    const afterStart = !start || taskDate >= start;
    const beforeEnd = !end || taskDate <= end;

    return matchesTruck && afterStart && beforeEnd;
  });

  const formatDate = (dateString: string) => {
    const options: Intl.DateTimeFormatOptions = { year: "numeric", month: "short", day: "numeric" };
    return new Date(dateString).toLocaleDateString(undefined, options);
  };

  const getTruckName = (truckId: number) => {
    const truck = trucks.find(t => t.id === truckId);
    return truck ? `${truck.make} ${truck.model}` : "Unknown Truck";
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Maintenance Schedule</h1>

      <div style={{ marginBottom: "20px", display: "flex", flexDirection: "column", gap: "10px" }}>
        <div style={{ display: "flex", flexDirection: "column", gap: "5px" }}>
          <label htmlFor="truckFilter" style={{ fontWeight: "bold" }}>Truck:</label>
          <select
            id="truckFilter"
            value={selectedTruck}
            onChange={(e) => setSelectedTruck(e.target.value === "all" ? "all" : Number(e.target.value))}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
          >
            <option value="all">All Trucks</option>
            {trucks.map(truck => (
              <option key={truck.id} value={truck.id}>
                {truck.make} {truck.model} ({truck.year})
              </option>
            ))}
          </select>
        </div>

        <div style={{ display: "flex", gap: "10px", flexDirection: "column" }}>
          <div style={{ display: "flex", flexDirection: "column", gap: "5px" }}>
            <label htmlFor="startDate" style={{ fontWeight: "bold" }}>Start Date:</label>
            <input
              type="date"
              id="startDate"
              value={startDate}
              onChange={(e) => setStartDate(e.target.value)}
              style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
            />
          </div>

          <div style={{ display: "flex", flexDirection: "column", gap: "5px" }}>
            <label htmlFor="endDate" style={{ fontWeight: "bold" }}>End Date:</label>
            <input
              type="date"
              id="endDate"
              value={endDate}
              onChange={(e) => setEndDate(e.target.value)}
              style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
            />
          </div>
        </div>
      </div>

      <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
        {filteredTasks.length === 0 ? (
          <p style={{ textAlign: "center", padding: "20px" }}>No maintenance tasks found.</p>
        ) : (
          filteredTasks.map(task => (
            <div 
              key={task.id} 
              style={{ 
                border: "1px solid #ddd", 
                borderRadius: "8px", 
                padding: "15px", 
                backgroundColor: "#f9f9f9",
                display: "flex",
                flexDirection: "column",
                gap: "8px"
              }}
            >
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                <h3 style={{ margin: 0 }}>{task.description}</h3>
                <span style={{ 
                  backgroundColor: task.status === "pending" ? "#fff3cd" : "#d4edda", 
                  color: task.status === "pending" ? "#856404" : "#155724", 
                  padding: "4px 8px", 
                  borderRadius: "4px", 
                  fontSize: "0.9em" 
                }}>
                  {task.status.charAt(0).toUpperCase() + task.status.slice(1)}
                </span>
              </div>

              <div style={{ display: "flex", justifyContent: "space-between", fontSize: "0.9em" }}>
                <span><strong>Truck:</strong> {getTruckName(task.truckId)}</span>
                <span><strong>Date:</strong> {formatDate(task.scheduledDate)}</span>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
}

