export function ServiceLogPage() {
  const [serviceRecords, setServiceRecords] = useState<ServiceRecord[]>([]);
  const [filteredRecords, setFilteredRecords] = useState<ServiceRecord[]>([]);
  const [searchTerm, setSearchTerm] = useState("");
  const [filterTruckId, setFilterTruckId] = useState("");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    const fetchServiceRecords = async () => {
      try {
        const response = await fetch('/api/service-records');
        if (!response.ok) {
          throw new Error('Failed to fetch service records');
        }
        const records = await response.json();
        setServiceRecords(records);
        setFilteredRecords(records);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'An unknown error occurred');
      } finally {
        setLoading(false);
      }
    };

    fetchServiceRecords();
  }, []);

  useEffect(() => {
    let result = serviceRecords;

    if (searchTerm) {
      const term = searchTerm.toLowerCase();
      result = result.filter(record => 
        record.description.toLowerCase().includes(term) ||
        record.partsUsed.toLowerCase().includes(term)
      );
    }

    if (filterTruckId) {
      const truckId = Number(filterTruckId);
      result = result.filter(record => record.truckId === truckId);
    }

    setFilteredRecords(result);
  }, [searchTerm, filterTruckId, serviceRecords]);

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  return (
    <div style={{
      maxWidth: "800px",
      margin: "0 auto",
      padding: "20px",
      fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif"
    }}>
      <h1 style={{ textAlign: "center" }}>Service Logs</h1>

      <div style={{ marginBottom: "20px", display: "flex", flexDirection: "column", gap: "10px" }}>
        <input
          type="text"
          placeholder="Search by description or parts used..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          style={{
            width: "100%",
            padding: "10px",
            borderRadius: "4px",
            border: "1px solid #ccc"
          }}
        />

        <select
          value={filterTruckId}
          onChange={(e) => setFilterTruckId(e.target.value)}
          style={{
            width: "100%",
            padding: "10px",
            borderRadius: "4px",
            border: "1px solid #ccc"
          }}
        >
          <option value="">All Trucks</option>
          <option value="1">Truck 1</option>
          <option value="2">Truck 2</option>
          <option value="3">Truck 3</option>
        </select>
      </div>

      {filteredRecords.length === 0 ? (
        <p style={{ textAlign: "center", padding: "20px" }}>No service records found.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
          {filteredRecords.map(record => (
            <div 
              key={record.id} 
              style={{
                border: "1px solid #ddd",
                borderRadius: "8px",
                padding: "15px",
                backgroundColor: "#f9f9f9"
              }}
            >
              <div style={{ display: "flex", justifyContent: "space-between", marginBottom: "10px" }}>
                <strong>Truck #{record.truckId}</strong>
                <span>{new Date(record.date).toLocaleDateString()}</span>
              </div>
              <p>{record.description}</p>
              <div style={{ display: "flex", justifyContent: "space-between", marginTop: "10px" }}>
                <span>Parts: {record.partsUsed}</span>
                <strong>${record.cost.toFixed(2)}</strong>
