import { Router, type Request, type Response } from "express";

export const router = Router();

// In-memory storage for demonstration purposes
let reminders: any[] = [];
let nextId = 1;

// Get all reminders
router.get("/reminders", (req: Request, res: Response) => {
  res.json(reminders);
});

// Get a reminder by ID
router.get("/reminders/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const reminder = reminders.find(r => r.id === id);

  if (!reminder) {
    return res.status(404).json({ error: "Reminder not found" });
  }

  res.json(reminder);
});

// Create a new reminder
router.post("/reminders", (req: Request, res: Response) => {
  const { medicationName, dosage, time, daysOfWeek } = req.body;

  // Validate required fields
  if (!medicationName || !dosage || !time || !daysOfWeek) {
    return res.status(400).json({ error: "Missing required fields: medicationName, dosage, time, daysOfWeek" });
  }

  // Validate time format (HH:MM)
  const timeRegex = /^([0-1]?[0-9]|2[0-3]):[0-5][0-9]$/;
  if (!timeRegex.test(time)) {
    return res.status(400).json({ error: "Invalid time format. Expected HH:MM" });
  }

  // Validate daysOfWeek
  if (!Array.isArray(daysOfWeek) || daysOfWeek.length === 0) {
    return res.status(400).json({ error: "daysOfWeek must be a non-empty array" });
  }

  const newReminder = {
    id: nextId++,
    medicationName,
    dosage,
    time,
    daysOfWeek,
    isActive: true
  };

  reminders.push(newReminder);
  res.status(201).json(newReminder);
});

// Update a reminder
router.put("/reminders/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const reminderIndex = reminders.findIndex(r => r.id === id);

  if (reminderIndex === -1) {
    return res.status(404).json({ error: "Reminder not found" });
  }

  const { medicationName, dosage, time, daysOfWeek, isActive } = req.body;

  // Validate time format (HH:MM)
  if (time) {
    const timeRegex = /^([0-1]?[0-9]|2[0-3]):[0-5][0-9]$/;
    if (!timeRegex.test(time)) {
      return res.status(400).json({ error: "Invalid time format. Expected HH:MM" });
    }
  }

  // Update the reminder
  reminders[reminderIndex] = {
    ...reminders[reminderIndex],
    medicationName: medicationName ?? reminders[reminderIndex].medicationName,
    dosage: dosage ?? reminders[reminderIndex].dosage,
    time: time ?? reminders[reminderIndex].time,
    daysOfWeek: daysOfWeek ?? reminders[reminderIndex].daysOfWeek,
    isActive: isActive !== undefined ? isActive : reminders[reminderIndex].isActive
  };

  res.json(reminders[reminderIndex]);
});

// Delete a reminder
router.delete("/reminders/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const reminderIndex = reminders.findIndex(r => r.id === id);

  if (reminderIndex === -1) {
    return res.status(404).json({ error: "Reminder not found" });
  }

  reminders.splice(reminderIndex, 1);
  res.json({ message: "Reminder deleted successfully" });
});

