import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only enforce password policy on POST /auth/register and PUT /auth/update-password
  if ((req.method === "POST" && req.path === "/auth/register") || 
      (req.method === "PUT" && req.path === "/auth/update-password")) {
    const { password } = req.body;

    // Check if password is provided
    if (!password) {
      return res.status(400).json({
        error: "Password is required"
      });
    }

    // Check minimum length (at least 8 characters)
    if (password.length < 8) {
      return res.status(400).json({
        error: "Password must be at least 8 characters long"
      });
    }

    // Check for at least one uppercase letter
    if (!/[A-Z]/.test(password)) {
      return res.status(400).json({
        error: "Password must contain at least one uppercase letter"
      });
    }

    // Check for at least one lowercase letter
    if (!/[a-z]/.test(password)) {
      return res.status(400).json({
        error: "Password must contain at least one lowercase letter"
      });
    }

    // Check for at least one digit
    if (!/[0-9]/.test(password)) {
      return res.status(400).json({
        error: "Password must contain at least one digit"
      });
    }

    // Check for at least one special character
    if (!/[!@#$%^&*(),.?":{}|<>]/.test(password)) {
      return res.status(400).json({
        error: "Password must contain at least one special character"
      });
    }

    // Check that password is not too common (basic check)
    const commonPasswords = ["password", "12345678", "qwertyui", "admin123"];
    if (commonPasswords.includes(password.toLowerCase())) {
      return res.status(400).json({
        error: "Password is too common and not allowed"
      });
    }

    // If all checks pass, continue to next middleware/route handler
    return next();
  }

  // For all other requests, skip password policy validation
  return next();
}

