import { Router, type Request, type Response } from "express";

export const router = Router();

// In-memory storage for classes and enrollments
const classes = [
  { id: 1, name: "Ballet Basics", schedule: "Mon 6:00 PM", maxStudents: 10 },
  { id: 2, name: "Hip Hop Fundamentals", schedule: "Tue 7:00 PM", maxStudents: 15 },
];

const enrollments: { id: number; studentId: number; classId: number }[] = [];

// Get all classes
router.get("/classes", (req: Request, res: Response) => {
  res.json(classes);
});

// Get a specific class by ID
router.get("/classes/:id", (req: Request, res: Response) => {
  const classId = Number(req.params.id);
  const classItem = classes.find(c => c.id === classId);

  if (!classItem) {
    return res.status(404).json({ error: "Class not found" });
  }

  res.json(classItem);
});

// Create a new class
router.post("/classes", (req: Request, res: Response) => {
  const { name, schedule, maxStudents } = req.body;

  if (!name || !schedule || maxStudents === undefined) {
    return res.status(400).json({ error: "Name, schedule, and maxStudents are required" });
  }

  const newClass = {
    id: classes.length > 0 ? Math.max(...classes.map(c => c.id)) + 1 : 1,
    name,
    schedule,
    maxStudents: Number(maxStudents)
  };

  classes.push(newClass);
  res.status(201).json(newClass);
});

// Update a class
router.put("/classes/:id", (req: Request, res: Response) => {
  const classId = Number(req.params.id);
  const classIndex = classes.findIndex(c => c.id === classId);

  if (classIndex === -1) {
    return res.status(404).json({ error: "Class not found" });
  }

  const { name, schedule, maxStudents } = req.body;

  if (!name || !schedule || maxStudents === undefined) {
    return res.status(400).json({ error: "Name, schedule, and maxStudents are required" });
  }

  classes[classIndex] = {
    ...classes[classIndex],
    name,
    schedule,
    maxStudents: Number(maxStudents)
  };

  res.json(classes[classIndex]);
});

// Delete a class
router.delete("/classes/:id", (req: Request, res: Response) => {
  const classId = Number(req.params.id);
  const classIndex = classes.findIndex(c => c.id === classId);

  if (classIndex === -1) {
    return res.status(404).json({ error: "Class not found" });
  }

  classes.splice(classIndex, 1);
  res.json({ message: "Class deleted successfully" });
});

// Enroll a student in a class
router.post("/classes/:id/enroll", (req: Request, res: Response) => {
  const classId = Number(req.params.id);
  const { studentId } = req.body;

  if (!studentId) {
    return res.status(400).json({ error: "Student ID is required" });
  }

  const classItem = classes.find(c => c.id === classId);

  if (!classItem) {
    return res.status(404).json({ error: "Class not found" });
  }

  const currentEnrollments = enrollments.filter(e => e.classId === classId);

  if (currentEnrollments.length >= classItem.maxStudents) {
    return res.status(400).json({ error: "Class is full" });
  }

  const newEnrollment = {
    id: enrollments.length > 0 ? Math.max(...enrollments.map(e => e.id)) + 1 : 1,
    studentId: Number(studentId),
    classId
  };

  enrollments.push(newEnrollment);
  res.status(201).json(newEnrollment);
});

// Get all enrollments for a class
router.get("/classes/:id/enrollments", (req: Request, res: Response) => {
  const classId = Number(req.params.id);

  const classItem = classes.find(c => c.id === classId);

  if (!classItem) {
    return res.status(404).json({ error: "Class not found" });
  }

  const currentEnrollments = enrollments.filter(e => e.classId === classId);
  res.json(currentEnrollments);
});

