import { useEffect, useState } from "react";

interface Prescription {
  id: string;
  patientName: string;
  medication: string;
  dosage: string;
  status: "pending" | "dispensed" | "cancelled";
  date: string;
}

export function PrescriptionManagement() {
  const [prescriptions, setPrescriptions] = useState<Prescription[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState("");
  const [statusFilter, setStatusFilter] = useState<"all" | Prescription["status"]>("all");

  useEffect(() => {
    fetchPrescriptions();
  }, []);

  const fetchPrescriptions = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/prescriptions");
      if (!response.ok) {
        throw new Error(`Failed to fetch: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setPrescriptions(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleDispense = async (id: string) => {
    try {
      const response = await fetch(`/api/prescriptions/${id}/dispense`, {
        method: "PUT",
      });
      if (!response.ok) {
        throw new Error(`Failed to dispense: ${response.status} ${response.statusText}`);
      }
      await fetchPrescriptions();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleCancel = async (id: string) => {
    try {
      const response = await fetch(`/api/prescriptions/${id}/cancel`, {
        method: "PUT",
      });
      if (!response.ok) {
        throw new Error(`Failed to cancel: ${response.status} ${response.statusText}`);
      }
      await fetchPrescriptions();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const filteredPrescriptions = prescriptions.filter(prescription => {
    const matchesSearch = prescription.patientName.toLowerCase().includes(searchTerm.toLowerCase()) ||
                          prescription.medication.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesStatus = statusFilter === "all" || prescription.status === statusFilter;
    return matchesSearch && matchesStatus;
  });

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Prescription Management</h1>

      <div style={{ marginBottom: "20px", display: "flex", flexDirection: "column", gap: "10px" }}>
        <input
          type="text"
          placeholder="Search by patient name or medication..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          style={{ width: "100%", padding: "10px", borderRadius: "4px", border: "1px solid #ccc" }}
        />

        <select
          value={statusFilter}
          onChange={(e) => setStatusFilter(e.target.value as "all" | Prescription["status"])}
          style={{ width: "100%", padding: "10px", borderRadius: "4px", border: "1px solid #ccc" }}
        >
          <option value="all">All Statuses</option>
          <option value="pending">Pending</option>
          <option value="dispensed">Dispensed</option>
          <option value="cancelled">Cancelled</option>
        </select>
      </div>

      {filteredPrescriptions.length === 0 ? (
        <p style={{ textAlign: "center", padding: "20px" }}>No prescriptions found.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
          {filteredPrescriptions.map((prescription) => (
            <div 
              key={prescription.id} 
              style={{ 
                border: "1px solid #ddd", 
                borderRadius: "8px", 
                padding: "15px", 
                backgroundColor: "#f9f9f9" 
              }}
            >
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                <div>
                  <h3>{prescription.patientName}</h3>
                  <p><strong>Medication:</strong> {prescription.medication}</p>
                  <p><strong>Dosage:</strong> {prescription.dosage}</p>
                  <p><strong>Date:</strong> {prescription.date}</p>
                  <p><strong>Status:</strong> {prescription.status}</p>
                </div>
                <div style={{ display: "flex", flexDirection: "column", gap: "5px" }}>
                  {prescription.status === "pending" && (
                    <button 
                      onClick={() => handleDispense(prescription.id)}
                      style={{ 
                        backgroundColor: "#4CAF50", 
                        color: "white", 
                        border: "none", 
                        padding: "8px 12px", 
                        borderRadius: "4px", 
                        cursor: "pointer" 
                      }}
                    >
                      Dispense
                    </button>
                  )}
                  {prescription.status === "pending" && (
                    <button 
                      onClick={() => handleCancel(prescription.id)}
                      style={{ 
                        backgroundColor: "#f44336", 
                        color: "white", 
                        border: "none", 
                        padding: "8px 12px", 
                        borderRadius: "4px", 
                        cursor: "pointer" 
                      }}
                    >
                      Cancel
                    </button>
                  )}
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

