import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply RBAC to protected routes
  if (!req.path.startsWith('/api/applications') && !req.path.startsWith('/api/schemes')) {
    next();
    return;
  }

  // Check if user has required role and clearance
  const userRole = req.headers['x-user-role'] as string | undefined;
  const userClearance = req.headers['x-user-clearance'] as string | undefined;

  if (!userRole || !userClearance) {
    res.status(401).json({ error: 'Unauthorized: Missing role or clearance' });
    return;
  }

  // Define role-based permissions
  const permissions: Record<string, string[]> = {
    'admin': ['view', 'edit', 'delete'],
    'reviewer': ['view', 'edit'],
    'viewer': ['view']
  };

  // Define clearance levels
  const clearanceLevels: Record<string, number> = {
    'public': 1,
    'confidential': 2,
    'secret': 3,
    'top-secret': 4
  };

  const requiredClearance = 'confidential';

  // Validate role permissions
  const userPermissions = permissions[userRole] || [];
  const userClearanceLevel = clearanceLevels[userClearance] || 0;
  const requiredClearanceLevel = clearanceLevels[requiredClearance] || 0;

  // Check if user has sufficient clearance
  if (userClearanceLevel < requiredClearanceLevel) {
    res.status(403).json({ error: 'Forbidden: Insufficient clearance level' });
    return;
  }

  // Check if user has permission to access the resource
  const allowedMethods = ['GET', 'POST', 'PUT', 'DELETE'];
  const method = req.method;

  if (!allowedMethods.includes(method)) {
    res.status(405).json({ error: 'Method Not Allowed' });
    return;
  }

  // For GET requests, allow view access
  if (method === 'GET' && !userPermissions.includes('view')) {
    res.status(403).json({ error: 'Forbidden: Insufficient permissions' });
    return;
  }

  // For POST, PUT, DELETE requests, check edit permissions
  if ((method === 'POST' || method === 'PUT' || method === 'DELETE') && !userPermissions.includes('edit')) {
    res.status(403).json({ error: 'Forbidden: Insufficient permissions' });
    return;
  }

  // If all checks pass, proceed
  next();
}

