import { useEffect, useState } from "react";

interface Application {
  id: string;
  applicantName: string;
  schemeType: string;
  status: string;
  submissionDate: string;
}

export function ApplicationList() {
  const [applications, setApplications] = useState<Application[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Filter states
  const [statusFilter, setStatusFilter] = useState("all");
  const [schemeTypeFilter, setSchemeTypeFilter] = useState("all");
  const [dateFrom, setDateFrom] = useState("");
  const [dateTo, setDateTo] = useState("");

  useEffect(() => {
    const fetchApplications = async () => {
      try {
        // In a real app, this would be an API call
        // For demo purposes, we'll simulate data
        await new Promise(resolve => setTimeout(resolve, 500));

        const mockApplications: Application[] = [
          {
            id: "1",
            applicantName: "John Smith",
            schemeType: "Education Grant",
            status: "Approved",
            submissionDate: "2023-05-15"
          },
          {
            id: "2",
            applicantName: "Jane Doe",
            schemeType: "Business Loan",
            status: "Pending",
            submissionDate: "2023-06-20"
          },
          {
            id: "3",
            applicantName: "Robert Johnson",
            schemeType: "Education Grant",
            status: "Rejected",
            submissionDate: "2023-04-10"
          },
          {
            id: "4",
            applicantName: "Emily Davis",
            schemeType: "Housing Support",
            status: "Approved",
            submissionDate: "2023-07-01"
          }
        ];

        setApplications(mockApplications);
        setLoading(false);
      } catch (err) {
        setError("Failed to load applications");
        setLoading(false);
      }
    };

    fetchApplications();
  }, []);

  const filteredApplications = applications.filter(app => {
    const matchesStatus = statusFilter === "all" || app.status === statusFilter;
    const matchesSchemeType = schemeTypeFilter === "all" || app.schemeType === schemeTypeFilter;

    let matchesDate = true;
    if (dateFrom || dateTo) {
      const appDate = new Date(app.submissionDate);
      if (dateFrom && appDate < new Date(dateFrom)) {
        matchesDate = false;
      }
      if (dateTo && appDate > new Date(dateTo)) {
        matchesDate = false;
      }
    }

    return matchesStatus && matchesSchemeType && matchesDate;
  });

  const uniqueSchemeTypes = [...new Set(applications.map(app => app.schemeType))];

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: "1200px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Government Scheme Applications</h1>

      <div style={{ marginBottom: "20px", display: "flex", flexDirection: "column", gap: "10px" }}>
        <div style={{ display: "flex", flexWrap: "wrap", gap: "10px" }}>
          <div style={{ flex: "1", minWidth: "200px" }}>
            <label style={{ display: "block", marginBottom: "5px" }}>Status:</label>
            <select 
              value={statusFilter}
              onChange={(e) => setStatusFilter(e.target.value)}
              style={{ width: "100%", padding: "8px" }}
            >
              <option value="all">All Statuses</option>
              <option value="Pending">Pending</option>
              <option value="Approved">Approved</option>
              <option value="Rejected">Rejected</option>
            </select>
          </div>

          <div style={{ flex: "1", minWidth: "200px" }}>
            <label style={{ display: "block", marginBottom: "5px" }}>Scheme Type:</label>
            <select 
              value={schemeTypeFilter}
              onChange={(e) => setSchemeTypeFilter(e.target.value)}
              style={{ width: "100%", padding: "8px" }}
            >
              <option value="all">All Types</option>
              {uniqueSchemeTypes.map(type => (
                <option key={type} value={type}>{type}</option>
              ))}
            </select>
          </div>

          <div style={{ flex: "1", minWidth: "200px" }}>
            <label style={{ display: "block", marginBottom: "5px" }}>From Date:</label>
            <input 
              type="date" 
              value={dateFrom}
              onChange={(e) => setDateFrom(e.target.value)}
              style={{ width: "100%", padding: "8px" }}
            />
          </div>

          <div style={{ flex: "1", minWidth: "200px" }}>
            <label style={{ display: "block", marginBottom: "5px" }}>To Date:</label>
            <input 
              type="date" 
              value={dateTo}
              onChange={(e) => setDateTo(e.target.value)}
              style={{ width: "100%", padding: "8px" }}
            />
          </div>
        </div>

        <button 
          onClick={() => {
            setStatusFilter("all");
            setSchemeTypeFilter("all");
            setDateFrom("");
            setDateTo("");
          }}
          style={{ 
            padding: "8px 16px", 
            backgroundColor: "#007bff", 
            color: "white", 
            border: "none", 
            borderRadius: "4px", 
            cursor: "pointer" 
          }}
        >
          Clear Filters
        </button>
      </div>

      {filteredApplications.length === 0 ? (
        <div style={{ textAlign: "center", padding: "20px" }}>
          No applications found.
        </div>
      ) : (
        <div style={{ overflowX: "auto" }}>
          <table style={{ width: "100%", borderCollapse: "collapse", marginBottom: "20px" }}>
            <thead>
              <tr style={{ backgroundColor: "#f8f9fa" }}>
                <th style={{ border: "1px solid #dee2e6", padding: "12px", textAlign: "left" }}>Applicant Name</th>
                <th style={{ border: "1px solid #dee2e6", padding: "12px", textAlign: "left" }}>Scheme Type</th>
                <th style={{ border: "1px solid #dee2e6", padding: "12px", textAlign: "left" }}>Status</th>
                <th style={{ border: "1px solid #dee2e6", padding: "12px", textAlign: "left" }}>Submission Date</th>
              </tr>
            </thead>
            <tbody>
              {filteredApplications.map(app => (
                <tr key={app.id} style={{ borderBottom: "1px solid #dee2e6" }}>
                  <td style={{ border: "1px solid #dee2e6", padding: "12px" }}>{app.applicantName}</td>
                  <td style={{ border: "1px solid #dee2e6", padding: "12px" }}>{app.schemeType}</td>
                  <td style={{ border: "1px solid #dee2e6", padding: "12px" }}>{app.status}</td>
                  <td style={{ border: "1px solid #dee2e6", padding: "12px" }}>{app.submissionDate}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

import { useEffect, useState } from "react";

interface Application {
  id: string;
  applicantName: string;
  applicantEmail: string;
  applicationDate: string;
  status: string;
  fields: Record<string, string>;
  statusHistory: StatusChange[];
}

interface StatusChange {
  date: string;
  oldStatus: string;
  newStatus: string;
  changedBy: string;
}

export function ApplicationDetail({ applicationId }: { applicationId: string }) {
  const [application, setApplication] = useState<Application | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [newStatus, setNewStatus] = useState("");

  useEffect(() => {
    const fetchApplication = async () => {
      try {
        const response = await fetch(`/api/applications/${applicationId}`);
        if (!response.ok) {
          throw new Error(`Failed to fetch application: ${response.status}`);
        }
        const data = await response.json();
        setApplication(data);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    };

    fetchApplication();
  }, [applicationId]);

  const handleStatusUpdate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!application || !newStatus) return;

    try {
      const response = await fetch(`/api/applications/${applicationId}/status`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ status: newStatus }),
      });

      if (!response.ok) {
        throw new Error(`Failed to update status: ${response.status}`);
      }

      // Refresh the application data
      const updatedResponse = await fetch(`/api/applications/${applicationId}`);
      if (!updatedResponse.ok) {
        throw new Error(`Failed to refresh application: ${updatedResponse.status}`);
      }
      const updatedData = await updatedResponse.json();
      setApplication(updatedData);
      setNewStatus("");
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  if (!application) {
    return <div style={{ textAlign: "center", padding: "20px" }}>No application found</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Application Details</h1>

      <div style={{ marginBottom: "20px", padding: "15px", border: "1px solid #ccc", borderRadius: "8px" }}>
        <h2>Applicant Information</h2>
        <p><strong>Name:</strong> {application.applicantName}</p>
        <p><strong>Email:</strong> {application.applicantEmail}</p>
        <p><strong>Application Date:</strong> {application.applicationDate}</p>
        <p><strong>Status:</strong> {application.status}</p>
      </div>

      <div style={{ marginBottom: "20px", padding: "15px", border: "1px solid #ccc", borderRadius: "8px" }}>
        <h2>Submitted Fields</h2>
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(200px, 1fr))", gap: "10px" }}>
          {Object.entries(application.fields).map(([key, value]) => (
            <div key={key} style={{ marginBottom: "10px" }}>
              <strong>{key}:</strong>
              <div>{value}</div>
            </div>
          ))}
        </div>
      </div>

      <div style={{ marginBottom: "20px", padding: "15px", border: "1px solid #ccc", borderRadius: "8px" }}>
        <h2>Status History</h2>
        {application.statusHistory.length > 0 ? (
          <table style={{ width: "100%", borderCollapse: "collapse" }}>
            <thead>
              <tr style={{ borderBottom: "1px solid #ccc" }}>
                <th style={{ textAlign: "left", padding: "8px" }}>Date</th>
                <th style={{ textAlign: "left", padding: "8px" }}>Old Status</th>
                <th style={{ textAlign: "left", padding: "8px" }}>New Status</th>
                <th style={{ textAlign: "left", padding: "8px" }}>Changed By</th>
              </tr>
            </thead>
            <tbody>
              {application.statusHistory.map((change, index) => (
                <tr key={index} style={{ borderBottom: "1px solid #eee" }}>
                  <td style={{ padding: "8px" }}>{change.date}</td>
                  <td style={{ padding: "8px" }}>{change.oldStatus}</td>
                  <td style={{ padding: "8px" }}>{change.newStatus}</td>
                  <td style={{ padding: "8px" }}>{change.changedBy}</td>
                </tr>
              ))}
            </tbody>
          </table>
        ) : (
          <p>No status changes recorded.</p>
        )}
      </div>

      <div style={{ padding: "15px", border: "1px solid #ccc", borderRadius: "8px" }}>
        <h2>Update Status</h2>
        <form onSubmit={handleStatusUpdate}>
          <div style={{ marginBottom: "10px" }}>
            <label htmlFor="statusSelect" style={{ display: "block", marginBottom: "5px" }}>
              New Status:
            </label>
            <select
              id="statusSelect"
              value={newStatus}
              onChange={(e) => setNewStatus(e.target.value)}
              style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
            >
              <option value="">Select a status</option>
              <option value="pending">Pending</option>
              <option value="approved">Approved</option>
              <option value="rejected">Rejected</option>
              <option value="completed">Completed</option>
            </select>
          </div>
          <button
            type="submit"
            style={{
              backgroundColor: "#007bff",
              color: "white",
              border: "none",
              padding: "10px 20px",
              borderRadius: "4px",
              cursor: "pointer",
              fontSize: "16px"
            }}
          >
            Update Status
          </button>
        </form>
      </div>
    </div>
  );
}

