import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Skip validation for non-protected routes
  const protectedPaths = ["/passes"];
  const isProtectedPath = protectedPaths.some(path =>
    req.path.startsWith(path)
  );

  if (!isProtectedPath) {
    next();
    return;
  }

  // Check HTTP method
  const allowedMethods = ["GET", "POST", "PUT", "DELETE"];
  if (!allowedMethods.includes(req.method)) {
    next();
    return;
  }

  // Extract token from Authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Internal Server Error: JWT_SECRET not configured" });
    return;
  }

  // Simple token verification (in a real app, use proper JWT library)
  try {
    const [payload, signature] = token.split(".");
    if (!payload || !signature) {
      res.status(401).json({ error: "Unauthorized: Invalid token format" });
      return;
    }

    // Verify signature
    const expectedSignature = createHmac("sha256", secret)
      .update(payload)
      .digest("base64url");

    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      res.status(401).json({ error: "Unauthorized: Invalid token signature" });
      return;
    }

    // Decode payload (simplified)
    const decodedPayload = JSON.parse(
      Buffer.from(payload, "base64url").toString()
    );

    // Check role
    const { role } = decodedPayload;
    if (!role) {
      res.status(401).json({ error: "Unauthorized: Role not found in token" });
      return;
    }

    // Allow access based on role and path
    if (req.path === "/passes") {
      if (req.method === "GET") {
        // Visitors can only view their own passes
        if (role === "visitor") {
          const visitorId = decodedPayload.visitorId;
          const passId = req.params.id;
          if (passId && passId !== visitorId) {
            res.status(403).json({ error: "Forbidden: Cannot view other visitor's pass" });
            return;
          }
        }
        // Staff can view all passes
        next();
        return;
      }

      if (req.method === "POST" || req.method === "PUT" || req.method === "DELETE") {
        // Only staff can create, modify, or delete passes
        if (role === "staff") {
          next();
          return;
        } else {
          res.status(403).json({ error: "Forbidden: Insufficient permissions" });
          return;
        }
      }
    }

    // Default case - allow access
    next();
  } catch (err) {
    res.status(401).json({ error: "Unauthorized: Invalid token" });
  }
}

