import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

// In-memory storage for sessions (in production, use a proper database)
const sessions = new Map<string, { expiresAt: number }>();

// Helper to generate a secure random token
function generateToken(): string {
  return Math.random().toString(36).substring(2, 15) + Math.random().toString(36).substring(2, 15);
}

// Helper to check if a token is valid
function isValidToken(token: string): boolean {
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    return false;
  }

  // Simple token format: <token>.<signature>
  const parts = token.split(".");
  if (parts.length !== 2) return false;

  const [tokenPart, signature] = parts;
  const expectedSignature = createHmac("sha256", secret)
    .update(tokenPart)
    .digest("hex");

  try {
    const expectedBuffer = Buffer.from(expectedSignature, "hex");
    const actualBuffer = Buffer.from(signature, "hex");
    return timingSafeEqual(expectedBuffer, actualBuffer);
  } catch {
    return false;
  }
}

// Middleware function
export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only handle POST requests with a body containing a token
  if (req.method !== "POST" || !req.body || !req.body.token) {
    return next();
  }

  const token = req.body.token;

  // Check if JWT_SECRET is set
  if (!process.env.JWT_SECRET) {
    return res.status(500).json({ error: "Server configuration error" });
  }

  // Validate token
  if (!token) {
    return res.status(401).json({ error: "No token provided" });
  }

  if (!isValidToken(token)) {
    return res.status(401).json({ error: "Invalid or expired token" });
  }

  // Extract token part (before the dot)
  const tokenPart = token.split(".")[0];

  // Check if session exists
  const session = sessions.get(tokenPart);
  if (!session) {
    return res.status(401).json({ error: "Session not found" });
  }

  // Check if session has expired
  if (Date.now() > session.expiresAt) {
    sessions.delete(tokenPart);
    return res.status(401).json({ error: "Session expired" });
  }

  // If we get here, the session is valid
  next();
}

