import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const SESSION_TIMEOUT = 30 * 60 * 1000; // 30 minutes
const JWT_SECRET = process.env.JWT_SECRET;

// Helper to check if a string is a valid base64url encoded string
function isValidBase64Url(str: string): boolean {
  return /^[A-Za-z0-9_-]+$/.test(str);
}

// Helper to decode base64url string
function base64UrlDecode(str: string): Buffer {
  const base64 = str.replace(/-/g, '+').replace(/_/g, '/');
  const padding = 4 - (base64.length % 4);
  if (padding !== 4) {
    for (let i = 0; i < padding; i++) {
      base64 += '=';
    }
  }
  return Buffer.from(base64, 'base64');
}

// Helper to verify JWT signature
function verifyJwtSignature(token: string, secret: string): boolean {
  const parts = token.split('.');
  if (parts.length !== 3) return false;

  const [header, payload, signature] = parts;

  if (!isValidBase64Url(header) || !isValidBase64Url(payload)) {
    return false;
  }

  const expectedSignature = createHmac('sha256', secret)
    .update(`${header}.${payload}`)
    .digest('base64url');

  const actualSignature = base64UrlDecode(signature);
  const expectedSignatureBuffer = base64UrlDecode(expectedSignature);

  try {
    return timingSafeEqual(actualSignature, expectedSignatureBuffer);
  } catch {
    return false;
  }
}

// Session management middleware
export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests with a body containing a token
  if (req.method !== 'POST' || !req.body || !req.body.token) {
    return next();
  }

  // Check if JWT_SECRET is set
  if (!JWT_SECRET) {
    return res.status(500).json({ error: 'Server configuration error' });
  }

  const token = req.body.token;

  // Verify token structure
  if (typeof token !== 'string') {
    return res.status(401).json({ error: 'Invalid token format' });
  }

  // Verify JWT signature
  if (!verifyJwtSignature(token, JWT_SECRET)) {
    return res.status(401).json({ error: 'Invalid token signature' });
  }

  // Parse token payload to check expiration
  try {
    const payload = JSON.parse(
      Buffer.from(
        token.split('.')[1].replace(/-/g, '+').replace(/_/g, '/'),
        'base64'
      ).toString()
    );

    const currentTime = Date.now();
    const tokenExpiry = payload.exp * 1000; // Convert seconds to milliseconds

    if (currentTime > tokenExpiry) {
      return res.status(401).json({ error: 'Token expired' });
    }

    // Token is valid and not expired
    // In a real implementation, we might want to update last activity time
    // For now, just pass through
    return next();
  } catch (err) {
    return res.status(401).json({ error: 'Invalid token payload' });
  }
}

