  condition: string;
  date: string;
  donorName: string;
}

interface Filters {
  itemType: string;
  condition: string;
  startDate: string;
  endDate: string;
  donorName: string;
}

export function DonationList() {
  const [donations, setDonations] = useState<Donation[]>([]);
  const [filters, setFilters] = useState<Filters>({
    itemType: '',
    condition: '',
    startDate: '',
    endDate: '',
    donorName: '',
  });
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchDonations = async () => {
      try {
        // Simulate API call
        await new Promise(resolve => setTimeout(resolve, 500));

        // Mock data
        const mockData: Donation[] = [
          { id: 1, itemType: 'Shirt', condition: 'New', date: '2023-05-15', donorName: 'John Doe' },
          { id: 2, itemType: 'Pants', condition: 'Good', date: '2023-06-20', donorName: 'Jane Smith' },
          { id: 3, itemType: 'Jacket', condition: 'Fair', date: '2023-07-10', donorName: 'Bob Johnson' },
          { id: 4, itemType: 'Dress', condition: 'New', date: '2023-08-05', donorName: 'Alice Brown' },
        ];

        setDonations(mockData);
        setLoading(false);
      } catch (err) {
        setError('Failed to load donations');
        setLoading(false);
      }
    };

    fetchDonations();
  }, []);

  const handleFilterChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFilters(prev => ({ ...prev, [name]: value }));
  };

  const filteredDonations = donations.filter(donation => {
    const matchesItemType = filters.itemType === '' || donation.itemType.toLowerCase().includes(filters.itemType.toLowerCase());
    const matchesCondition = filters.condition === '' || donation.condition === filters.condition);
    const matchesStartDate = filters.startDate === '' || donation.date >= filters.startDate;
    const matchesEndDate = filters.endDate === '' || donation.date <= filters.endDate;
    const matchesDonorName = filters.donorName === '' || donation.donorName.toLowerCase().includes(filters.donorName.toLowerCase());

    return (
      matchesItemType &&
      matchesCondition &&
      matchesStartDate &&
      matchesEndDate &&
      matchesDonorName
    );
  });

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
