import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock data to simulate database operations
const restaurants = new Map<string, { id: string; name: string; ratings: number[] }>();

// Helper function to calculate average rating
const calculateAverageRating = (ratings: number[]): number => {
  if (ratings.length === 0) return 0;
  const sum = ratings.reduce((acc, rating) => acc + rating, 0);
  return Math.round((sum / ratings.length) * 10) / 10; // Round to 1 decimal place
};

// GET /restaurants/:id - Get restaurant by ID
router.get("/restaurants/:id", (req: Request, res: Response) => {
  const { id } = req.params;
  const restaurant = restaurants.get(id);

  if (!restaurant) {
    return res.status(404).json({ error: "Restaurant not found" });
  }

  const averageRating = calculateAverageRating(restaurant.ratings);

  return res.json({
    id: restaurant.id,
    name: restaurant.name,
    averageRating,
    totalRatings: restaurant.ratings.length
  });
});

// POST /restaurants - Create a new restaurant
router.post("/restaurants", (req: Request, res: Response) => {
  const { id, name } = req.body;

  if (!id || !name) {
    return res.status(400).json({ error: "ID and name are required" });
  }

  if (restaurants.has(id)) {
    return res.status(400).json({ error: "Restaurant already exists" });
  }

  restaurants.set(id, { id, name, ratings: [] });

  return res.status(201).json({ id, name, averageRating: 0, totalRatings: 0 });
});

// PUT /restaurants/:id/ratings - Add a rating to a restaurant
router.put("/restaurants/:id/ratings", (req: Request, res: Response) => {
  const { id } = req.params;
  const { rating } = req.body;

  if (typeof rating !== "number" || rating < 1 || rating > 5) {
    return res.status(400).json({ error: "Rating must be a number between 1 and 5" });
  }

  const restaurant = restaurants.get(id);

  if (!restaurant) {
    return res.status(404).json({ error: "Restaurant not found" });
  }

  restaurant.ratings.push(rating);
  const averageRating = calculateAverageRating(restaurant.ratings);

  return res.json({
    id: restaurant.id,
    name: restaurant.name,
    averageRating,
    totalRatings: restaurant.ratings.length
  });
});

// DELETE /restaurants/:id - Delete a restaurant
router.delete("/restaurants/:id", (req: Request, res: Response) => {
  const { id } = req.params;

  if (!restaurants.has(id)) {
    return res.status(404).json({ error: "Restaurant not found" });
  }

  restaurants.delete(id);

  return res.json({ message: "Restaurant deleted successfully" });
});

