import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

// Define rate limiting configuration
const MAX_REQUESTS = 10;
const TIME_WINDOW_MS = 15 * 60 * 1000; // 15 minutes

// Track requests per IP
const requestCounts = new Map<string, { count: number; windowStart: number }>();

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply rate limiting to feedback submission endpoints
  const isFeedbackEndpoint = req.path.startsWith('/feedback') && req.method === 'POST';

  if (!isFeedbackEndpoint) {
    next();
    return;
  }

  const clientIP = getClientIP(req);
  const now = Date.now();

  // Initialize or update request count for this IP
  const ipData = requestCounts.get(clientIP) || { count: 0, windowStart: now };

  // Reset counter if time window has passed
  if (now - ipData.windowStart > TIME_WINDOW_MS) {
    ipData.count = 0;
    ipData.windowStart = now;
  }

  // Increment request count
  ipData.count += 1;
  requestCounts.set(clientIP, ipData);

  // Check if limit exceeded
  if (ipData.count > MAX_REQUESTS) {
    res.status(429).json({
      error: "Too many requests",
      message: "Rate limit exceeded. Please try again later."
    });
    return;
  }

  next();
}

function getClientIP(req: Request): string {
  return (
    req.headers['x-forwarded-for'] as string ||
    req.connection.remoteAddress ||
    req.socket.remoteAddress ||
    (req.connection as any).socket?.remoteAddress ||
    ''
  ).split(',')[0].trim();
}

