export function RestaurantDetailPage({
  restaurantId,
}: {
  restaurantId: string;
}) {
  const [restaurant, setRestaurant] = useState<Restaurant | null>(null);
  const [ratings, setRatings] = useState<Rating[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [newRating, setNewRating] = useState({
    rating: 5,
    comment: "",
  });

  useEffect(() => {
    const fetchRestaurantData = async () => {
      try {
        const res = await fetch(`/api/restaurants/${restaurantId}`);
        if (!res.ok) throw new Error("Failed to fetch restaurant");
        const data = await res.json();
        setRestaurant(data);

        const ratingsRes = await fetch(`/api/restaurants/${restaurantId}/ratings`);
        if (!ratingsRes.ok) throw new Error("Failed to fetch ratings");
        const ratingsData = await ratingsRes.json();
        setRatings(ratingsData);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    };

    fetchRestaurantData();
  }, [restaurantId]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const res = await fetch(`/api/restaurants/${restaurantId}/ratings`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          rating: newRating.rating,
          comment: newRating.comment,
        }),
      });

      if (!res.ok) throw new Error("Failed to submit rating");

      // Refresh ratings after submission
      const ratingsRes = await fetch(`/api/restaurants/${restaurantId}/ratings`);
      if (!ratingsRes.ok) throw new Error("Failed to fetch ratings");
      const ratingsData = await ratingsRes.json();
      setRatings(ratingsData);

      // Reset form
      setNewRating({ rating: 5, comment: "" });
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) return <div style={styles.centered}>Loading...</div>;
  if (error) return <div style={styles.centered}>Error: {error}</div>;
  if (!restaurant) return <div style={styles.centered}>Restaurant not found</div>;

  return (
    <div style={styles.container}>
      <div style={styles.header}>
        <h1 style={styles.title}>{restaurant.name}</h1>
      </div>

      <div style={styles.infoCard}>
        <div style={styles.infoRow}>
          <span>Description:</span>
          <span>{restaurant.description}</span>
        </div>
        <div style={styles.infoRow}>
          <span>Address:</span>
          <span>{restaurant.address}</span>
        </div>
        <div style={styles.infoRow}>
          <span>Phone:</span>
          <span>{restaurant.phone}</span>
        </div>
        <div style={styles.infoRow}>
          <span>Average Rating:</span>
          <span>{restaurant.averageRating.toFixed(1)} ({restaurant.totalRatings} ratings)</span>
        </div>
      </div>

      <h2>Ratings</h2>
      <div style={styles.ratingsContainer}>
        {ratings.length > 0 ? (
          ratings.map((rating) => (
            <div key={rating.id} style={styles.ratingCard}>
              <div>
                <strong>Rating: {rating.rating}/5</strong>
              </div>
              <div>{rating.comment}</div>
              <div style={{ fontSize: "12px", color: "#666" }}>
                {new Date(rating.date).toLocaleDateString()}
              </div>
            </div>
          ))
        ) : (
          <p>No ratings yet.</p>
        )}
      </div>

      <h2>Submit Your Rating</h2>
      <form onSubmit={handleSubmit} style={styles.form}>
        <label>
          Rating:
          <select
            value={newRating.rating}
            onChange={(e) =>
              setNewRating({
                ...newRating,
                rating: parseInt(e.target.value),
              })
            }
            style={styles.input}
          >
            {[1, 2, 3, 4, 5].map((num) => (
              <option key={num} value={num}>
                {num}
              </option>
            ))}
          </select>
        </label>
        <label>
          Comment:
          <textarea
            value={newRating.comment}
            onChange={(e) =>
              setNewRating({
                ...newRating,
                comment: e.target.value,
              })
            }
            style={styles.textarea}
            placeholder="Share your experience..."
          />
        </label>
        <button type="submit" style={styles.button}>Submit Rating</button>
      </form>
    </div>
  );
}

import { FC, useState } from "react";

interface FeedbackFormProps {
  restaurantId: string;
}

export function FeedbackForm({ restaurantId }: FeedbackFormProps) {
  const [rating, setRating] = useState<number | null>(null);
  const [review, setReview] = useState<string>("");
  const [isSubmitting, setIsSubmitting] = useState<boolean>(false);
  const [submitSuccess, setSubmitSuccess] = useState<boolean>(false);
  const [submitError, setSubmitError] = useState<string | null>(null);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!rating || !review.trim()) {
      setSubmitError("Please provide both a rating and a review.");
      return;
    }

    setIsSubmitting(true);
    setSubmitError(null);

    try {
      const response = await fetch(`/api/restaurants/${restaurantId}/feedback`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          rating,
          review,
        }),
      });

      if (!response.ok) {
        throw new Error(`Failed to submit feedback: ${response.status}`);
      }

      setSubmitSuccess(true);
      setRating(null);
      setReview("");
    } catch (error) {
      setSubmitError(error instanceof Error ? error.message : "An unknown error occurred");
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div style={{
      maxWidth: "600px",
      margin: "0 auto",
      padding: "20px",
      fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
    }}>
      <h1 style={{ textAlign: "center", marginBottom: "30px" }}>Rate This Restaurant</h1>

      {submitSuccess ? (
        <div style={{
          backgroundColor: "#d4edda",
          color: "#155724",
          padding: "15px",
          borderRadius: "5px",
          textAlign: "center",
          marginBottom: "20px",
        }}>
          Thank you for your feedback!
        </div>
      ) : null}

      {submitError ? (
        <div style={{
          backgroundColor: "#f8d7da",
          color: "#721c24",
          padding: "15px",
          borderRadius: "5px",
          textAlign: "center",
          marginBottom: "20px",
        }}>
          {submitError}
        </div>
      ) : null}

      <form onSubmit={handleSubmit} style={{ display: "flex", flexDirection: "column", gap: "20px" }}>
        <div>
          <label style={{ display: "block", marginBottom: "10px", fontWeight: "bold" }}>
            Rating:
          </label>
          <div style={{ display: "flex", gap: "10px", flexWrap: "wrap" }}>
            {[1, 2, 3, 4, 5].map((star) => (
              <button
                key={star}
                type="button"
                onClick={() => setRating(star)}
                style={{
                  fontSize: "24px",
                  border: "none",
                  background: "none",
                  cursor: "pointer",
                  color: rating && star <= rating ? "#ffc107" : "#ddd",
                }}
              >
                ★
              </button>
            ))}
          </div>
        </div>

        <div>
          <label style={{ display: "block", marginBottom: "10px", fontWeight: "bold" }}>
            Review:
          </label>
          <textarea
            value={review}
            onChange={(e) => setReview(e.target.value)}
            placeholder="Share your experience..."
            style={{
              width: "100%",
              padding: "10px",
              borderRadius: "5px",
              border: "1px solid #ccc",
              minHeight: "100px",
              fontFamily: "inherit",
            }}
            required
          />
        </div>

        <button
          type="submit"
          disabled={isSubmitting}
          style={{
            padding: "12px 20px",
            backgroundColor: "#007bff",
            color: "white",
            border: "none",
            borderRadius: "5px",
            cursor: "pointer",
            fontSize: "16px",
            fontWeight: "bold",
            alignSelf: "flex-start",
          }}
        >
          {isSubmitting ? "Submitting..." : "Submit Feedback"}
        </button>
      </form>
    </div>
  );
}

