// Mock database - in a real app this would be a proper database
const mockDatabase = {
  restaurants: [
    { id: 1, name: "Bella Italia", location: "Downtown", cuisineType: "Italian", averageRating: 4.5 },
    { id: 2, name: "Sakura Sushi", location: "Midtown", cuisineType: "Japanese", averageRating: 4.7 }
  ]
};

// Get all restaurants
router.get("/", (req: Request, res: Response) => {
  res.json(mockDatabase.restaurants);
});

// Get a restaurant by ID
router.get("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const restaurant = mockDatabase.restaurants.find(r => r.id === id);

  if (!restaurant) {
    return res.status(404).json({ error: "Restaurant not found" });
  }

  res.json(restaurant);
});

// Create a new restaurant
router.post("/", (req: Request, res: Response) => {
  const { name, location, cuisineType, averageRating } = req.body;

  // Validate required fields
  if (!name || !location || !cuisineType) {
    return res.status(400).json({ error: "Name, location, and cuisineType are required" });
  }

  const newRestaurant = {
    id: mockDatabase.restaurants.length > 0 
      ? Math.max(...mockDatabase.restaurants.map(r => r.id)) + 1 
      : 1,
    name,
    location,
    cuisineType,
    averageRating: averageRating || 0
  };

  mockDatabase.restaurants.push(newRestaurant);

  res.status(201).json(newRestaurant);
});

// Update a restaurant
router.put("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { name, location, cuisineType, averageRating } = req.body;

  const restaurantIndex = mockDatabase.restaurants.findIndex(r => r.id === id);

  if (restaurantIndex === -1) {
    return res.status(404).json({ error: "Restaurant not found" });
  }

  // Validate required fields
  if (!name || !location || !cuisineType) {
    return res.status(400).json({ error: "Name, location, and cuisineType are required" });
  }

  const updatedRestaurant = {
    ...mockDatabase.restaurants[restaurantIndex],
    name,
    location,
    cuisineType,
    averageRating: averageRating !== undefined ? averageRating : mockDatabase.restaurants[restaurantIndex].averageRating
  };

  mockDatabase.restaurants[restaurantIndex] = updatedRestaurant;

  res.json(updatedRestaurant);
});

// Delete a restaurant
router.delete("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const restaurantIndex = mockDatabase.restaurants.findIndex(r => r.id === id);

  if (restaurantIndex === -1) {
    return res.status(404).json({ error: "Restaurant not found" });
  }

  mockDatabase.restaurants.splice(restaurantIndex, 1);

  res.json({ message: "Restaurant deleted successfully" });
});

