import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock user database
const users = [
  {
    id: 1,
    username: "admin",
    password: "admin123",
    role: "admin"
  },
  {
    id: 2,
    username: "pharmacist",
    password: "pharm123",
    role: "pharmacist"
  }
];

// Mock session storage
const sessions = new Map<string, { userId: number; role: string }>();

// User registration
router.post("/register", (req: Request, res: Response) => {
  const { username, password, role } = req.body;

  if (!username || !password || !role) {
    return res.status(400).json({ error: "Username, password, and role are required" });
  }

  // Check if user already exists
  const existingUser = users.find(user => user.username === username);
  if (existingUser) {
    return res.status(400).json({ error: "User already exists" });
  }

  // Create new user
  const newUser = {
    id: users.length + 1,
    username,
    password,
    role
  };

  users.push(newUser);

  return res.status(201).json(newUser);
});

// User login
router.post("/login", (req: Request, res: Response) => {
  const { username, password } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: "Username and password are required" });
  }

  // Find user
  const user = users.find(u => u.username === username && u.password === password);
  if (!user) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  // Generate session token
  const token = `session_${Math.random().toString(36).substring(2, 15)}`;
  sessions.set(token, { userId: user.id, role: user.role });

  return res.json({ token, role: user.role });
});

// Session validation
router.get("/validate", (req: Request, res: Response) => {
  const token = req.headers.authorization?.split(" ")[1];

  if (!token) {
    return res.status(401).json({ error: "No token provided" });
  }

  const session = sessions.get(token);
  if (!session) {
    return res.status(401).json({ error: "Invalid token" });
  }

  return res.json({ valid: true, userId: session.userId, role: session.role });
});

import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock database functions - in a real app these would come from a database module
const mockMedications = [
  { id: 1, name: "Ibuprofen", dosage: "200mg", stock: 100, price: 5.99 },
  { id: 2, name: "Aspirin", dosage: "325mg", stock: 50, price: 3.49 }
];

const findMedicationById = (id: number) => {
  return mockMedications.find(med => med.id === id);
};

const createMedication = (medication: Omit<Medication, 'id'>) => {
  const newId = Math.max(0, ...mockMedications.map(m => m.id)) + 1;
  const newMedication = { ...medication, id: newId };
  mockMedications.push(newMedication);
  return newMedication;
};

const updateMedication = (id: number, updates: Partial<Medication>) => {
  const index = mockMedications.findIndex(med => med.id === id);
  if (index === -1) return null;
  mockMedications[index] = { ...mockMedications[index], ...updates };
  return mockMedications[index];
};

const deleteMedication = (id: number) => {
  const index = mockMedications.findIndex(med => med.id === id);
  if (index === -1) return false;
  mockMedications.splice(index, 1);
  return true;
};

interface Medication {
  id: number;
  name: string;
  dosage: string;
  stock: number;
  price: number;
}

// GET /medications - List all medications
router.get("/medications", (req: Request, res: Response) => {
  res.json(mockMedications);
});

// GET /medications/:id - Get a specific medication by ID
router.get("/medications/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid medication ID" });
  }

  const medication = findMedicationById(id);
  if (!medication) {
    return res.status(404).json({ error: "Medication not found" });
  }

  res.json(medication);
});

// POST /medications - Create a new medication
router.post("/medications", (req: Request, res: Response) => {
  const { name, dosage, stock, price } = req.body;

  // Basic validation
  if (!name || !dosage || stock === undefined || price === undefined) {
    return res.status(400).json({ error: "Name, dosage, stock, and price are required" });
  }

  if (typeof stock !== "number" || stock < 0) {
    return res.status(400).json({ error: "Stock must be a non-negative number" });
  }

  if (typeof price !== "number" || price < 0) {
    return res.status(400).json({ error: "Price must be a non-negative number" });
  }

  const newMedication = createMedication({ name, dosage, stock, price });
  res.status(201).json(newMedication);
});

// PUT /medications/:id - Update a medication
router.put("/medications/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid medication ID" });
  }

  const { name, dosage, stock, price } = req.body;

  // Validation
  if ((stock !== undefined && typeof stock !== "number") || (price !== undefined && typeof price !== "number")) {
