import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const JWT_SECRET = process.env.JWT_SECRET;

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only protect POST, PUT, DELETE requests to specific paths
  const isProtectedMethod = req.method === "POST" || req.method === "PUT" || req.method === "DELETE";
  const isProtectedPath = req.path.startsWith("/prescriptions") || req.path.startsWith("/stock");

  if (!isProtectedMethod || !isProtectedPath) {
    next();
    return;
  }

  // Check if JWT secret is set
  if (!JWT_SECRET) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // Extract token from Authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Missing or invalid authorization header" });
    return;
  }

  const token = authHeader.substring(7);

  try {
    // Basic token structure validation
    const parts = token.split(".");
    if (parts.length !== 3) {
      res.status(401).json({ error: "Invalid token format" });
      return;
    }

    // Verify signature
    const [header, payload, signature] = parts;
    const expectedSignature = createHmac("sha256", JWT_SECRET)
      .update(`${header}.${payload}`)
      .digest("base64url");

    // Use timingSafeEqual to prevent timing attacks
    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      res.status(401).json({ error: "Invalid token signature" });
      return;
    }

    // Decode payload to check role (simplified for this example)
    const decodedPayload = JSON.parse(Buffer.from(payload, "base64url").toString());
    const userRole = decodedPayload.role;

    // Define allowed roles for protected endpoints
    const allowedRoles = ["pharmacist", "manager"];

    if (!allowedRoles.includes(userRole)) {
      res.status(403).json({ error: "Insufficient permissions" });
      return;
    }

    // If we get here, the user has proper role
    next();
  } catch (error) {
    res.status(401).json({ error: "Invalid token" });
  }
}

import type { Request, Response, NextFunction } from "express";
import { createHash, scryptSync, randomBytes, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // This middleware is designed to handle password encryption for user registration
  // It should only process POST requests to the /register endpoint
  if (req.method !== "POST" || req.path !== "/register") {
    next();
    return;
  }

  // Check if password exists in request body
  if (!req.body || typeof req.body.password !== "string") {
    next();
    return;
  }

  // Hash the password using scrypt
  const salt = randomBytes(16).toString("hex");
  const key = scryptSync(req.body.password, salt, 32);
  const hashedPassword = key.toString("hex");

  // Replace the password with the hashed version
  req.body.password = hashedPassword;
  req.body.salt = salt;

  next();
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

// In-memory session store - in production, use a proper database
const sessions: Map<string, { userId: string; expiresAt: number }> = new Map();

const SESSION_TIMEOUT = 30 * 60 * 1000; // 30 minutes

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only handle POST /login and GET /logout requests
  if (!(req.method === "POST" && req.path === "/login") && !(req.method === "GET" && req.path === "/logout")) {
    next();
    return;
  }

  const jwtSecret = process.env.JWT_SECRET;
  if (!jwtSecret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  if (req.method === "POST" && req.path === "/login") {
    // Handle login - generate session token
    const { userId } = req.body;
    if (!userId) {
      res.status(400).json({ error: "User ID required" });
      return;
    }

    const sessionId = createHmac("sha256", jwtSecret)
      .update(userId + Date.now())
      .digest("hex");

    sessions.set(sessionId, {
      userId,
      expiresAt: Date.now() + SESSION_TIMEOUT
    });

    res.json({ token: sessionId });
    return;
  }

  if (req.method === "GET" && req.path === "/logout") {
    // Handle logout - invalidate session token
    const authHeader = req.headers.authorization;
    if (!authHeader || !authHeader.startsWith("Bearer ")) {
      res.status(401).json({ error: "No session token provided" });
      return;
    }

    const token = authHeader.substring(7); // Remove "Bearer " prefix

    // Verify token signature
    const expectedSignature = createHmac("sha256", jwtSecret)
      .update(token)
      .digest("hex");

    const tokenSignature = token.split(".")[1] || "";
    const expectedBuffer = Buffer.from(expectedSignature);
    const actualBuffer = Buffer.from(tokenSignature);

    try {
      if (!timingSafeEqual(expectedBuffer, actualBuffer)) {
        res.status(401).json({ error: "Invalid token signature" });
        return;
      }
    } catch {
      res.status(401).json({ error: "Invalid token signature" });
      return;
    }

    // Check if session exists and is valid
    const session = sessions.get(token);
    if (!session) {
      res.status(401).json({ error: "Invalid session token" });
      return;
    }

    // Check expiration
    if (Date.now() > session.expiresAt) {
      sessions.delete(token);
      res.status(401).json({ error: "Session expired" });
      return;
    }

    // Invalidate session
    sessions.delete(token);
    res.json({ message: "Logged out successfully" });
    return;
  }

  next();
}

