import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

// In-memory session store - in production, use a proper database
const sessions: Map<string, { userId: string; expiresAt: number }> = new Map();

const SESSION_TIMEOUT = 30 * 60 * 1000; // 30 minutes

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only handle POST /login and GET /logout requests
  if (!(req.method === "POST" && req.path === "/login") && !(req.method === "GET" && req.path === "/logout")) {
    next();
    return;
  }

  const jwtSecret = process.env.JWT_SECRET;
  if (!jwtSecret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  if (req.method === "POST" && req.path === "/login") {
    // Handle login - generate session token
    const { userId } = req.body;
    if (!userId) {
      res.status(400).json({ error: "User ID required" });
      return;
    }

    const sessionId = createHmac("sha256", jwtSecret)
      .update(userId + Date.now())
      .digest("hex");

    sessions.set(sessionId, {
      userId,
      expiresAt: Date.now() + SESSION_TIMEOUT
    });

    res.json({ token: sessionId });
    return;
  }

  if (req.method === "GET" && req.path === "/logout") {
    // Handle logout - invalidate session token
    const authHeader = req.headers.authorization;
    if (!authHeader || !authHeader.startsWith("Bearer ")) {
      res.status(401).json({ error: "No session token provided" });
      return;
    }

    const token = authHeader.substring(7); // Remove "Bearer " prefix

    // Verify token signature
    const expectedSignature = createHmac("sha256", jwtSecret)
      .update(token)
      .digest("hex");

    const tokenSignature = token.split(".")[1] || "";
    const expectedBuffer = Buffer.from(expectedSignature);
    const actualBuffer = Buffer.from(tokenSignature);

    try {
      if (!timingSafeEqual(expectedBuffer, actualBuffer)) {
        res.status(401).json({ error: "Invalid token signature" });
        return;
      }
    } catch {
      res.status(401).json({ error: "Invalid token signature" });
      return;
    }

    // Check if session exists and is valid
    const session = sessions.get(token);
    if (!session) {
      res.status(401).json({ error: "Invalid session token" });
      return;
    }

    // Check expiration
    if (Date.now() > session.expiresAt) {
      sessions.delete(token);
      res.status(401).json({ error: "Session expired" });
      return;
    }

    // Invalidate session
    sessions.delete(token);
    res.json({ message: "Logged out successfully" });
    return;
  }

  next();
}

