import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to POST /bookings and PUT /bookings routes
  if (!(req.method === "POST" || req.method === "PUT") || !req.path.startsWith("/bookings")) {
    next();
    return;
  }

  // Check if user has admin role
  const userRole = req.headers["x-user-role"] as string | undefined;

  if (userRole !== "admin") {
    res.status(403).json({ error: "Access denied. Admin role required." });
    return;
  }

  next();
}

