import { useEffect, useState } from "react";

interface Slot {
  id: number;
  location: string;
  status: "available" | "booked";
  bookedBy?: string;
  bookingTime?: string;
}

export function SlotList() {
  const [slots, setSlots] = useState<Slot[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchSlots();
  }, []);

  const fetchSlots = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/slots");
      if (!response.ok) {
        throw new Error(`Failed to fetch slots: ${response.status}`);
      }
      const data = await response.json();
      setSlots(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  if (slots.length === 0) {
    return <div style={{ textAlign: "center", padding: "20px" }}>No parking slots available.</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Parking Slots</h1>
      <div style={{ display: "flex", flexWrap: "wrap", gap: "15px" }}>
        {slots.map((slot) => (
          <div 
            key={slot.id} 
            style={{ 
              border: "1px solid #ccc", 
              borderRadius: "8px", 
              padding: "15px", 
              width: "100%", 
              maxWidth: "300px",
              backgroundColor: slot.status === "available" ? "#e8f5e8" : "#ffe8e8"
            }}
          >
            <h3>Slot #{slot.id}</h3>
            <p><strong>Location:</strong> {slot.location}</p>
            <p><strong>Status:</strong> <span style={{ color: slot.status === "available" ? "green" : "red" }}>{slot.status}</span></p>
            {slot.bookedBy && (
              <>
                <p><strong>Booked By:</strong> {slot.bookedBy}</p>
                <p><strong>Booking Time:</strong> {slot.bookingTime}</p>
              </>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}

