import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to protected routes
  const protectedPaths = [
    "/api/pickup",
    "/api/delivery",
    "/api/orders",
    "/api/staff"
  ];

  const isProtectedPath = protectedPaths.some(path =>
    req.path.startsWith(path)
  );

  if (!isProtectedPath) {
    next();
    return;
  }

  // Check if user has proper role
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error: JWT_SECRET not set" });
    return;
  }

  try {
    // Simple token validation (in a real app, you'd decode and verify properly)
    const [userId, role] = token.split(":");

    if (!userId || !role) {
      res.status(401).json({ error: "Unauthorized: Invalid token format" });
      return;
    }

    // For demo purposes, we'll just check if role is valid
    // In a real implementation, you'd verify the token signature
    if (role !== "customer" && role !== "staff") {
      res.status(403).json({ error: "Forbidden: Invalid role" });
      return;
    }

    // Add role to request for downstream middleware/route handlers
    (req as any).userRole = role;

    // Allow access for both customer and staff to these endpoints
    if (req.path.startsWith("/api/pickup") || 
        req.path.startsWith("/api/delivery") ||
        req.path.startsWith("/api/orders")) {
      next();
      return;
    }

    // Staff-only endpoints
    if (req.path.startsWith("/api/staff")) {
      if (role === "staff") {
        next();
        return;
      } else {
        res.status(403).json({ error: "Forbidden: Staff only" });
        return;
      }
    }

    next();
  } catch (error) {
    res.status(401).json({ error: "Unauthorized: Invalid token" });
  }
}

