// PUT /assignments/:id - Update an existing assignment
router.put("/assignments/:id", (req: Request, res: Response) => {
  const id = req.params.id;
  const { title, description, dueDate } = req.body;

  const assignmentIndex = assignments.findIndex(a => a.id === id);

  if (assignmentIndex === -1) {
    return res.status(404).json({ error: "Assignment not found" });
  }

  if (!title || !description || !dueDate) {
    return res.status(400).json({ error: "Title, description, and dueDate are required" });
  }

  assignments[assignmentIndex] = {
    ...assignments[assignmentIndex],
    title,
    description,
    dueDate
  };

  res.json(assignments[assignmentIndex]);
});

// DELETE /assignments/:id - Delete an assignment
router.delete("/assignments/:id", (req: Request, res: Response) => {
  const id = req.params.id;
  const assignmentIndex = assignments.findIndex(a => a.id === id);

  if (assignmentIndex === -1) {
    return res.status(404).json({ error: "Assignment not found" });
  }

  assignments.splice(assignmentIndex, 1);

  res.json({ message: "Assignment deleted successfully" });
});

