import type { Request, Response, NextFunction } from "express";
import { createHash, randomBytes } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // This middleware is designed to handle password hashing for user registration
  // It should only process POST requests to the /register endpoint
  if (req.method !== "POST" || req.path !== "/register") {
    next();
    return;
  }

  // Check if password exists in request body
  if (!req.body || typeof req.body.password !== "string") {
    next();
    return;
  }

  // Hash the password using SHA-256 with a salt
  const salt = randomBytes(32).toString("hex");
  const hashedPassword = createHash("sha256")
    .update(req.body.password + salt)
    .digest("hex");

  // Replace the password with the hashed version in the request body
  req.body.password = hashedPassword;
  req.body.salt = salt;

  next();
}

import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST and PUT requests with file uploads
  if ((req.method !== "POST" && req.method !== "PUT") || !req.path.includes("upload")) {
    next();
    return;
  }

  // Define allowed file extensions
  const allowedExtensions = [".pdf", ".doc", ".docx", ".txt", ".jpg", ".jpeg", ".png"];

  // Define maximum file size (10MB)
  const maxSizeInBytes = 10 * 1024 * 1024;

  // Check if file exists in request
  if (!req.file) {
    return res.status(400).json({ error: "No file uploaded" });
  }

  // Validate file size
  if (req.file.size > maxSizeInBytes) {
    return res.status(400).json({ error: "File size exceeds limit of 10MB" });
  }

  // Validate file extension
  const fileExtension = "".concat(req.file.originalname).slice(-4).toLowerCase();
  if (!allowedExtensions.includes(fileExtension)) {
    return res.status(400).json({ error: "File type not allowed" });
  }

  // Simulate malware scan (in a real application, integrate with antivirus)
  // For now, we'll just assume no malware is present
  const hasMalware = false;
  if (hasMalware) {
    return res.status(400).json({ error: "File contains malware" });
  }

  // If all validations pass, continue to next middleware/route handler
  next();
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to submission-related routes
  if (!req.path.startsWith("/submissions") || req.method === "GET") {
    next();
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  try {
    // Basic token structure validation
    const parts = token.split(".");
    if (parts.length !== 3) {
      res.status(401).json({ error: "Invalid token format" });
      return;
    }

    const [header, payload, signature] = parts;
    const expectedSignature = createHmac("sha256", secret)
      .update(`${header}.${payload}`)
      .digest("base64url");

    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    if (signatureBuffer.length !== expectedSignatureBuffer.length ||
        !timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      res.status(401).json({ error: "Invalid token signature" });
      return;
    }

    // Decode payload to get user role and ID
    const payloadJson = Buffer.from(payload, "base64url").toString("utf-8");
    const payloadObj = JSON.parse(payloadJson);

    const userRole = payloadObj.role;
    const userId = payloadObj.userId;

    if (!userRole || !userId) {
      res.status(401).json({ error: "Invalid token payload" });
      return;
    }

    // For instructor, allow access to all submissions
    if (userRole === "instructor") {
      next();
      return;
    }

    // For student, check if they can access the specific submission
    if (userRole === "student") {
      const submissionId = req.params.id;
      const studentId = userId;

      // Check if the submission belongs to the student
      if (submissionId && req.path.includes(submissionId)) {
        // In a real implementation, we would check the database here
        // For now, we'll assume the student can only access their own submissions
        // This is a simplified check - in practice, you'd query the DB
        next();
        return;
      }

      // If no specific submission is being accessed, deny access
      res.status(403).json({ error: "Forbidden" });
      return;
    }

    // Unknown role
    res.status(401).json({ error: "Invalid role" });
    return;
  } catch (error) {
    res.status(401).json({ error: "Invalid token" });
    return;
  }
}

