import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST and PUT requests with file uploads
  if ((req.method !== "POST" && req.method !== "PUT") || !req.path.includes("upload")) {
    next();
    return;
  }

  // Define allowed file extensions
  const allowedExtensions = [".pdf", ".doc", ".docx", ".txt", ".jpg", ".jpeg", ".png"];

  // Define maximum file size (10MB)
  const maxSizeInBytes = 10 * 1024 * 1024;

  // Check if file exists in request
  if (!req.file) {
    return res.status(400).json({ error: "No file uploaded" });
  }

  // Validate file size
  if (req.file.size > maxSizeInBytes) {
    return res.status(400).json({ error: "File size exceeds limit of 10MB" });
  }

  // Validate file extension
  const fileExtension = "".concat(req.file.originalname).slice(-4).toLowerCase();
  if (!allowedExtensions.includes(fileExtension)) {
    return res.status(400).json({ error: "File type not allowed" });
  }

  // Simulate malware scan (in a real application, integrate with antivirus)
  // For now, we'll just assume no malware is present
  const hasMalware = false;
  if (hasMalware) {
    return res.status(400).json({ error: "File contains malware" });
  }

  // If all validations pass, continue to next middleware/route handler
  next();
}

