const calculateNextDueDate = (bill: any): Date => {
  const nextDate = new Date(bill.dueDate);
  nextDate.setDate(nextDate.getDate() + 30);
  return nextDate;
};

// GET /bills - List all bills
router.get("/bills", (req: Request, res: Response) => {
  res.json(mockBills);
});

// GET /bills/:id - Get a specific bill by ID
router.get("/bills/:id", (req: Request, res: Response) => {
  const bill = findBillById(req.params.id);
  if (!bill) {
    return res.status(404).json({ error: "Bill not found" });
  }
  res.json(bill);
});

// POST /bills - Create a new bill
router.post("/bills", (req: Request, res: Response) => {
  const { title, amount, dueDate, isRecurring, category } = req.body;

  // Validate required fields
  if (!title || !amount || !dueDate || !category) {
    return res.status(400).json({ error: "Title, amount, dueDate, and category are required" });
  }

  // Validate amount is a number
  if (isNaN(amount)) {
    return res.status(400).json({ error: "Amount must be a number" });
  }

  // Validate dueDate is a valid date
  const parsedDueDate = new Date(dueDate);
  if (isNaN(parsedDueDate.getTime())) {
    return res.status(400).json({ error: "Invalid due date format" });
  }

  const newBill = {
    id: String(mockBills.length + 1),
    title,
    amount: Number(amount),
    dueDate: parsedDueDate,
    isRecurring: isRecurring === true || isRecurring === "true",
    category
  };

  mockBills.push(newBill);
  res.status(201).json(newBill);
});

// PUT /bills/:id - Update an existing bill
router.put("/bills/:id", (req: Request, res: Response) => {
  const billIndex = mockBills.findIndex(bill => bill.id === req.params.id);

  if (billIndex === -1) {
    return res.status(404).json({ error: "Bill not found" });
  }

  const { title, amount, dueDate, isRecurring, category } = req.body;

  // Validate required fields
  if (!title || !amount || !dueDate || !category) {
    return res.status(400).json({ error: "Title, amount, dueDate, and category are required" });
  }

  // Validate amount is a number
  if (isNaN(amount)) {
    return res.status(400).json({ error: "Amount must be a number" });
  }

  // Validate dueDate is a valid date
  const parsedDueDate = new Date(dueDate);
  if (isNaN(parsedDueDate.getTime())) {
    return res.status(400).json({ error: "Invalid due date format" });
  }

  const updatedBill = {
    ...mockBills[billIndex],
    title,
    amount: Number(amount),
    dueDate: parsedDueDate,
    isRecurring: isRecurring === true || isRecurring === "true",
    category
  };

  mockBills[billIndex] = updatedBill;
  res.json(updatedBill);
});

// DELETE /bills/:id - Delete a bill
router.delete("/bills/:id", (req: Request, res: Response) => {
  const billIndex = mockBills.findIndex(bill => bill.id === req.params.id);

  if (billIndex === -1) {
    return res.status(404).json({ error: "Bill not found" });
  }

  mockBills.splice(billIndex, 1);
  res.json({ message: "Bill deleted successfully" });
});

