import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to /login endpoint
  if (!(req.method === "POST" && req.path === "/login")) {
    next();
    return;
  }

  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Internal server error" });
    return;
  }

  const token = req.headers.authorization?.split(" ")[1];

  if (!token) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  try {
    const [header, payload, signature] = token.split(".");

    if (!header || !payload || !signature) {
      res.status(401).json({ error: "Unauthorized" });
      return;
    }

    const expectedSignature = createHmac("sha256", secret)
      .update(`${header}.${payload}`)
      .digest("base64url");

    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    if (signatureBuffer.length !== expectedSignatureBuffer.length ||
        !timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      res.status(401).json({ error: "Unauthorized" });
      return;
    }

    next();
  } catch (error) {
    res.status(401).json({ error: "Unauthorized" });
  }
}

import type { Request, Response, NextFunction } from "express";
import { createHash, randomBytes } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // This middleware runs on every request, but password encryption is only needed for specific routes
  // We'll assume it's meant for password-related operations, so we check for POST requests to /users or /auth

  // If it's not a POST request to /users or /auth, skip processing
  if (!(req.method === "POST" && (req.path === "/users" || req.path === "/auth"))) {
    next();
    return;
  }

  // For demonstration purposes, we'll simulate password hashing
  // In a real implementation, this would hash the password before storing

  // Check if password exists in request body
  if (typeof req.body.password !== "string") {
    next();
    return;
  }

  // Simulate password hashing - in reality, use bcrypt or similar
  const salt = randomBytes(16).toString("hex");
  const hashedPassword = createHash("sha256").update(req.body.password + salt).digest("hex");

  // Replace password with hashed version in request body
  req.body.password = hashedPassword;
  req.body.salt = salt;

  next();
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only validate POST, PUT, PATCH requests with a body
  if (!['POST', 'PUT', 'PATCH'].includes(req.method)) {
    return next();
  }

  // Validate and sanitize input
  if (req.body) {
    // Sanitize string fields
    Object.keys(req.body).forEach(key => {
      const value = req.body[key];
      if (typeof value === 'string') {
        // Remove potentially dangerous characters
        req.body[key] = value.replace(/[<>'"&]/g, '');
      }
    });
  }

  next();
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const MAX_REQUESTS = 100;
const TIME_WINDOW_MS = 15 * 60 * 1000; // 15 minutes

// In-memory storage for rate limits
const requestCounts: Map<string, { count: number; windowStart: number }> = new Map();

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply rate limiting to POST requests to protected endpoints
  if (req.method !== "POST" || !req.path.startsWith("/api/")) {
    next();
    return;
  }

  const clientIdentifier = getClientIdentifier(req);
  const now = Date.now();

  let clientData = requestCounts.get(clientIdentifier);

  if (!clientData) {
    clientData = { count: 0, windowStart: now };
    requestCounts.set(clientIdentifier, clientData);
  }

  // Reset window if time has passed
  if (now - clientData.windowStart > TIME_WINDOW_MS) {
    clientData.count = 0;
    clientData.windowStart = now;
  }

  // Check if request limit exceeded
  if (clientData.count >= MAX_REQUESTS) {
    res.status(429).json({
      error: "Rate limit exceeded",
      message: "Too many requests, please try again later"
    });
    return;
  }

  // Increment request count
  clientData.count++;

  next();
}

function getClientIdentifier(req: Request): string {
  // Use IP address as identifier
  return (
    req.headers["x-forwarded-for"]?.toString().split(",")[0].trim() ||
    req.connection.remoteAddress ||
    req.socket.remoteAddress ||
    "unknown"
  );
}

