import { useEffect, useState } from "react";

interface Payment {
  id: string;
  date: string;
  amount: number;
  billId: string;
}

interface Bill {
  id: string;
  title: string;
  description: string;
}

export function PaymentHistory() {
  const [payments, setPayments] = useState<Payment[]>([]);
  const [bills, setBills] = useState<Bill[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    async function fetchPaymentHistory() {
      try {
        const [paymentsResponse, billsResponse] = await Promise.all([
          fetch("/api/payments"),
          fetch("/api/bills"),
        ]);

        if (!paymentsResponse.ok || !billsResponse.ok) {
          throw new Error("Failed to fetch payment history or bills");
        }

        const paymentsData = await paymentsResponse.json();
        const billsData = await billsResponse.json();

        setPayments(paymentsData);
        setBills(billsData);
        setLoading(false);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
        setLoading(false);
      }
    }

    fetchPaymentHistory();
  }, []);

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  if (payments.length === 0) {
    return <div style={{ textAlign: "center", padding: "20px" }}>No payment history found.</div>;
  }

  const getBillTitle = (billId: string) => {
    const bill = bills.find(b => b.id === billId);
    return bill ? bill.title : "Unknown Bill";
  };

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Payment History</h1>
      <div style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
        {payments.map(payment => (
          <div 
            key={payment.id} 
            style={{ 
              border: "1px solid #ccc", 
              borderRadius: "8px", 
              padding: "15px", 
              display: "flex", 
              justifyContent: "space-between", 
              alignItems: "center",
              flexWrap: "wrap"
            }}
          >
            <div>
              <h3 style={{ margin: "0 0 5px 0" }}>
                {getBillTitle(payment.billId)}
              </h3>
              <p style={{ margin: "0", color: "#666" }}>
                Date: {new Date(payment.date).toLocaleDateString()}
              </p>
              <p style={{ margin: "0", color: "#666" }}>
                Amount: ${payment.amount.toFixed(2)}
              </p>
            </div>
            <div>
              <span style={{ backgroundColor: "#e0e0e0", padding: "5px 10px", borderRadius: "4px" }}>
                ID: {payment.id}
              </span>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

