router.get("/bugs/:bugId/comments", (req: Request, res: Response) => {
  const bugId = Number(req.params.bugId);

  if (isNaN(bugId)) {
    return res.status(400).json({ error: "Invalid bug ID" });
  }

  const bugComments = comments.filter(comment => comment.bugId === bugId);

  return res.json(bugComments);
});

// Get a specific comment by ID
router.get("/comments/:id", (req: Request, res: Response) => {
  const commentId = Number(req.params.id);

  if (isNaN(commentId)) {
    return res.status(400).json({ error: "Invalid comment ID" });
  }

  const comment = comments.find(c => c.id === commentId);

  if (!comment) {
    return res.status(404).json({ error: "Comment not found" });
  }

  return res.json(comment);
});

// Create a new comment
router.post("/bugs/:bugId/comments", (req: Request, res: Response) => {
  const bugId = Number(req.params.bugId);

  if (isNaN(bugId)) {
    return res.status(400).json({ error: "Invalid bug ID" });
  }

  const { author, content } = req.body;

  if (!author || !content) {
    return res.status(400).json({ error: "Author and content are required" });
  }

  const newComment = {
    id: nextCommentId++,
    bugId,
    author,
    content,
    createdAt: new Date()
  };

  comments.push(newComment);

  return res.status(201).json(newComment);
});

// Update a comment
router.put("/comments/:id", (req: Request, res: Response) => {
  const commentId = Number(req.params.id);

  if (isNaN(commentId)) {
    return res.status(400).json({ error: "Invalid comment ID" });
  }

  const commentIndex = comments.findIndex(c => c.id === commentId);

  if (commentIndex === -1) {
    return res.status(404).json({ error: "Comment not found" });
  }

  const { author, content } = req.body;

  if (!author || !content) {
    return res.status(400).json({ error: "Author and content are required" });
  }

  comments[commentIndex] = {
    ...comments[commentIndex],
    author,
    content
  };

  return res.json(comments[commentIndex]);
});

// Delete a comment
router.delete("/comments/:id", (req: Request, res: Response) => {
  const commentId = Number(req.params.id);

  if (isNaN(commentId)) {
    return res.status(400).json({ error: "Invalid comment ID" });
  }

  const commentIndex = comments.findIndex(c => c.id === commentId);

  if (commentIndex === -1) {
    return res.status(404).json({ error: "Comment not found" });
  }

  comments.splice(commentIndex, 1);

  return res.json({ message: "Comment deleted successfully" });
});

import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock attachment service - in a real implementation, this would connect to a database
const attachments = new Map<string, { id: string; fileName: string; fileSize: number; uploadDate: Date }>();

// GET /attachments - List all attachments
router.get("/", (req: Request, res: Response) => {
  const attachmentList = Array.from(attachments.values());
  return res.json(attachmentList);
});

// GET /attachments/:id - Get a specific attachment by ID
router.get("/:id", (req: Request, res: Response) => {
  const id = req.params.id;
  const attachment = attachments.get(id);

  if (!attachment) {
    return res.status(404).json({ error: "Attachment not found" });
  }

  return res.json(attachment);
});

// POST /attachments - Create a new attachment
router.post("/", (req: Request, res: Response) => {
  // Validate required fields
  if (!req.body.fileName || !req.body.fileSize) {
    return res.status(400).json({ error: "fileName and fileSize are required" });
  }

  const newId = Math.random().toString(36).substring(2, 15);
  const newAttachment = {
    id: newId,
    fileName: req.body.fileName,
    fileSize: req.body.fileSize,
    uploadDate: new Date()
  };

  attachments.set(newId, newAttachment);

  return res.status(201).json(newAttachment);
});

// PUT /attachments/:id - Update an existing attachment
router.put("/:id", (req: Request, res: Response) => {
  const id = req.params.id;

  if (!attachments.has(id)) {
    return res.status(404).json({ error: "Attachment not found" });
  }

  const existingAttachment = attachments.get(id)!;

  // Update fields if provided
  if (req.body.fileName !== undefined) {
    existingAttachment.fileName = req.body.fileName;
  }

  if (req.body.fileSize !== undefined) {
    existingAttachment.fileSize = req.body.fileSize;
  }

  attachments.set(id, existingAttachment);

  return res.json(existingAttachment);
});

// DELETE /attachments/:id - Delete an attachment
router.delete("/:id", (req: Request, res: Response) => {
  const id = req.params.id;

  if (!attachments.has(id)) {
    return res.status(404).json({ error: "Attachment not found" });
  }

  attachments.delete(id);

  return res.json({ message: "Attachment deleted successfully" });
});

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

// Define role types and their permission levels
const roles = {
  developer: 1,
  manager: 2,
  admin: 3,
} as const;

type UserRole = keyof typeof roles;

// Helper to check if user has required role level
function hasRequiredRole(userRole: UserRole, requiredRole: UserRole): boolean {
  return roles[userRole] >= roles[requiredRole];
}

// Middleware function for role-based access control
export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role checking to protected routes
  if (!(req.path.startsWith('/api/projects') || 
        req.path.startsWith('/api/issues') || 
        req.path.startsWith('/api/users'))) {
    next();
    return;
  }

  // For demonstration purposes, we'll assume user role is in req.user.role
  // In a real implementation, this would come from a verified JWT or session
  const userRole = req.user?.role as UserRole | undefined;
  const requiredRole = getRequiredRole(req.path);

  // If no role is set or user doesn't meet required role, deny access
  if (!userRole || !hasRequiredRole(userRole, requiredRole)) {
    res.status(403).json({ error: "Forbidden: Insufficient permissions" });
    return;
  }

  next();
}

// Helper to determine required role based on path
function getRequiredRole(path: string): UserRole {
  if (path.startsWith('/api/projects')) {
    // Example: projects require manager or higher
    return 'manager';
  } else if (path.startsWith('/api/issues')) {
    // Example: issues require developer or higher
    return 'developer';
  } else if (path.startsWith('/api/users')) {
    // Example: users require admin
    return 'admin';
  }
  // Default to developer for unknown paths
  return 'developer';
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  // Check if JWT secret is set
  const jwtSecret = process.env.JWT_SECRET;
  if (!jwtSecret) {
    res.status(500).json({ error: "JWT secret not configured" });
    return;
  }

  // In a real implementation, we would verify the JWT token here
  // For now, we'll just simulate the verification process
  // This is a placeholder for actual JWT validation logic

  // Simulate token verification
  const token = req.headers.authorization?.split(" ")[1];
  if (!token) {
    res.status(401).json({ error: "No token provided" });
    return;
  }

  // Verify token signature (simplified example)
  try {
    const [header, payload, signature] = token.split(".");
    const expectedSignature = createHmac("sha256", jwtSecret)
      .update(`${header}.${payload}`)
      .digest("base64url");

    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      res.status(401).json({ error: "Invalid token signature" });
      return;
    }

    // If we get here, token is valid
    next();
  } catch (error) {
    res.status(401).json({ error: "Invalid token format" });
  }
}

