import { useEffect, useState } from "react";

interface Bug {
  id: number;
  title: string;
  status: string;
  priority: string;
  assignee: string;
}

export function BugListPage() {
  const [bugs, setBugs] = useState<Bug[]>([]);
  const [filteredBugs, setFilteredBugs] = useState<Bug[]>([]);
  const [searchTerm, setSearchTerm] = useState("");
  const [statusFilter, setStatusFilter] = useState("");
  const [priorityFilter, setPriorityFilter] = useState("");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    fetchBugs();
  }, []);

  useEffect(() => {
    let result = bugs;

    if (searchTerm) {
      const term = searchTerm.toLowerCase();
      result = result.filter(bug => 
        bug.title.toLowerCase().includes(term) ||
        bug.assignee.toLowerCase().includes(term)
      );
    }

    if (statusFilter) {
      result = result.filter(bug => bug.status === statusFilter);
    }

    if (priorityFilter) {
      result = result.filter(bug => bug.priority === priorityFilter);
    }

    setFilteredBugs(result);
  }, [searchTerm, statusFilter, priorityFilter, bugs]);

  const fetchBugs = async () => {
    try {
      setLoading(true);
      // Simulate API call
      await new Promise(resolve => setTimeout(resolve, 500));

      // Mock data - in a real app this would be an actual API call
      const mockBugs: Bug[] = [
        { id: 1, title: "Login page crashes on mobile", status: "Open", priority: "High", assignee: "John Doe" },
        { id: 2, title: "Dark mode not working properly", status: "In Progress", priority: "Medium", assignee: "Jane Smith" },
        { id: 3, title: "Missing error messages", status: "Closed", priority: "Low", assignee: "Bob Johnson" },
        { id: 4, title: "Performance issues with large datasets", status: "Open", priority: "High", assignee: "Alice Brown" },
        { id: 5, title: "UI elements misaligned on tablet", status: "Open", priority: "Medium", assignee: "Charlie Wilson" },
      ];

      setBugs(mockBugs);
      setFilteredBugs(mockBugs);
    } catch (err) {
      setError("Failed to load bugs");
    } finally {
      setLoading(false);
    }
  };

  const handleSearchChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setSearchTerm(e.target.value);
  };

  const handleStatusChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    setStatusFilter(e.target.value);
  };

  const handlePriorityChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    setPriorityFilter(e.target.value);
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case "Open": return "#ff6b6b";
      case "In Progress": return "#4ecdc4";
      case "Closed": return "#45b7d1";
      default: return "#95a5a6";
    }
  };

  const getPriorityColor = (priority: string) => {
    switch (priority) {
      case "High": return "#ff6b6b";
      case "Medium": return "#f39c12";
      case "Low": return "#27ae60";
      default: return "#95a5a6";
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: "1200px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center", marginBottom: "30px" }}>Bug Tracker</h1>

      <div style={{ marginBottom: "30px", display: "flex", flexDirection: "column", gap: "15px" }}>
        <input
          type="text"
          placeholder="Search bugs..."
          value={searchTerm}
          onChange={handleSearchChange}
          style={{
            padding: "10px",
            borderRadius: "5px",
            border: "1px solid #ddd",
            fontSize: "16px",
            width: "100%"
          }}
        />

        <div style={{ display: "flex", gap: "15px", flexWrap: "wrap" }}>
          <select
            value={statusFilter}
            onChange={handleStatusChange}
            style={{
              padding: "10px",
              borderRadius: "5px",
              border: "1px solid #ddd",
              fontSize: "16px",
