  author: string;
  content: string;
  timestamp: string;
}

interface Attachment {
  id: number;
  filename: string;
  url: string;
  uploadDate: string;
}

interface HistoryItem {
  id: number;
  action: string;
  actor: string;
  timestamp: string;
}

interface Bug {
  id: number;
  title: string;
  description: string;
  stepsToReproduce: string;
