  priority: string;
  reporter: string;
  assignee: string;
  createdAt: string;
  updatedAt: string;
  comments: Comment[];
  attachments: Attachment[];
  history: HistoryItem[];
}

export function BugDetailPage({ bugId }: { bugId: string }) {
  const [bug, setBug] = useState<Bug | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchBug = async () => {
      try {
        const response = await fetch(`/api/bugs/${bugId}`);
        if (!response.ok) {
          throw new Error(`Failed to fetch bug: ${response.status} ${response.statusText}`);
        }
        const bugData = await response.json();
        setBug(bugData);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    };

    fetchBug();
  }, [bugId]);

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;

  if (!bug) return <div style={{ textAlign: "center", padding: "20px" }}>Bug not found</div>;

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ fontSize: "24px", marginBottom: "10px" }}>{bug.title}</h1>

      <div style={{ display: "flex", justifyContent: "space-between", marginBottom: "20px" }}>
        <span style={{ backgroundColor: "#e0e0e0", padding: "4px 8px", borderRadius: "4px" }}>
          Status: {bug.status}
        </span>
        <span style={{ backgroundColor: "#e0e0e0", padding: "4px 8px", borderRadius: "4px" }}>
          Priority: {bug.priority}
        </span>
      </div>

      <div style={{ marginBottom: "20px" }}>
        <h2>Description</h2>
        <p>{bug.description}</p>
      </div>

      <div style={{ marginBottom: "20px" }}>
        <h2>Steps to Reproduce</h2>
        <p>{bug.stepsToReproduce}</p>
      </div>

      <div style={{ marginBottom: "20px" }}>
        <h2>Attachments</h2>
        {bug.attachments.length > 0 ? (
          <ul style={{ listStyle: "none", padding: 0 }}>
            {bug.attachments.map(attachment => (
              <li key={attachment.id} style={{ marginBottom: "10px" }}>
                <a href={attachment.url} target="_blank" rel="noopener noreferrer">
                  {attachment.filename}
                </a>
                <span style={{ marginLeft: "10px", color: "#666" }}>
                  ({new Date(attachment.uploadDate).toLocaleDateString()})
                </span>
              </li>
            ))}
          </ul>
        ) : (
          <p>No attachments</p>
        )}
      </div>

      <div style={{ marginBottom: "20px" }}>
        <h2>Comments</h2>
        {bug.comments.length > 0 ? (
          <div>
            {bug.comments.map(comment => (
              <div key={comment.id} style={{ border: "1px solid #ddd", borderRadius: "4px", padding: "10px", marginBottom: "10px" }}>
                <div style={{ fontWeight: "bold" }}>{comment.author}</div>
                <div style={{ fontSize: "14px", color: "#666", marginBottom: "5px" }}>
                  {new Date(comment.timestamp).toLocaleString()}
                </div>
                <p>{comment.content}</p>
              </div>
            ))}
          </div>
        ) : (
          <p>No comments yet</p>
        )}
      </div>

      <div>
        <h2>History</h2>
        {bug.history.length > 0 ? (
          <table style={{ width: "100%", borderCollapse: "collapse" }}>
            <thead>
              <tr style={{ borderBottom: "1px solid #ddd" }}>
                <th style={{ textAlign: "left", padding: "8px" }}>Action</th>
                <th style={{ textAlign: "left", padding: "8px" }}>Actor</th>
                <th style={{ textAlign: "left", padding: "8px" }}>Timestamp</th>
              </tr>
            </thead>
            <tbody>
              {bug.history.map(historyItem => (
                <tr key={historyItem.id} style={{ borderBottom: "1px solid #eee" }}>
                  <td style={{ padding: "8px" }}>{historyItem.action}</td>
                  <td style={{ padding: "8px" }}>{historyItem.actor}</td>
                  <td style={{ padding: "8px" }}>{new Date(historyItem.timestamp).toLocaleString()}</td>
                </tr>
              ))}
            </tbody>
          </table>
        ) : (
          <p>No history available</p>
        )}
      </div>
    </div>
  );
}

