interface Bug {
  id: number;
  title: string;
  description: string;
  status: 'open' | 'in-progress' | 'resolved' | 'closed';
  priority: 'low' | 'medium' | 'high' | 'critical';
  assignee: string;
  resolutionNotes?: string;
}

export function BugEditForm({ bugId }: { bugId: number }) {
  const [bug, setBug] = useState<Bug | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    async function fetchBug() {
      try {
        const response = await fetch(`/api/bugs/${bugId}`);
        if (!response.ok) {
          throw new Error(`Failed to fetch bug: ${response.status}`);
        }
        const bugData = await response.json();
        setBug(bugData);
        setLoading(false);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'An unknown error occurred');
        setLoading(false);
      }
    }

    fetchBug();
  }, [bugId]);

  if (loading) return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;

  if (error) return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;

  if (!bug) return <div style={{ textAlign: 'center', padding: '20px' }}>Bug not found</div>;

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
      const response = await fetch(`/api/bugs/${bugId}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(bug),
      });

      if (!response.ok) {
        throw new Error(`Failed to update bug: ${response.status}`);
      }

      // In a real app, we might redirect or refresh the page
      alert('Bug updated successfully');
    } catch (err) {
      alert(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  return (
    <div style={{ maxWidth: '600px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Edit Bug</h1>

      <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
        <div>
          <label htmlFor="title" style={{ display: 'block', marginBottom: '5px' }}>Title</label>
          <input
            id="title"
            type="text"
            value={bug.title}
            onChange={(e) => setBug({...bug, title: e.target.value})}
            style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
          />
        </div>

        <div>
          <label htmlFor="description" style={{ display: 'block', marginBottom: '5px' }}>Description</label>
          <textarea
            id="description"
            value={bug.description}
            onChange={(e) => setBug({...bug, description: e.target.value})}
            style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ccc', minHeight: '100px' }}
          />
        </div>

        <div>
          <label htmlFor="status" style={{ display: 'block', marginBottom: '5px' }}>Status</label>
          <select
            id="status"
            value={bug.status}
            onChange={(e) => setBug({...bug, status: e.target.value as any})}
            style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
          >
            <option value="open">Open</option>
