import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock data and handlers for demonstration purposes
const donations = [
  { id: 1, donorId: 1, amount: 50, date: "2023-01-01" },
  { id: 2, donorId: 2, amount: 100, date: "2023-01-02" }
];

const donors = [
  { id: 1, name: "John Doe", email: "john@example.com" },
  { id: 2, name: "Jane Smith", email: "jane@example.com" }
];

// GET /api/donations - List all donations
router.get("/donations", (req: Request, res: Response) => {
  res.json(donations);
});

// GET /api/donations/:id - Get donation by ID
router.get("/donations/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const donation = donations.find(d => d.id === id);

  if (!donation) {
    return res.status(404).json({ error: "Donation not found" });
  }

  res.json(donation);
});

// POST /api/donations - Create a new donation
router.post("/donations", (req: Request, res: Response) => {
  const { donorId, amount, date } = req.body;

  if (!donorId || !amount || !date) {
    return res.status(400).json({ error: "Missing required fields: donorId, amount, date" });
  }

  const newDonation = {
    id: donations.length + 1,
    donorId,
    amount,
