import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only enforce role-based access control on protected routes
  const protectedPaths = ["/admin", "/staff", "/volunteer"];
  const isProtectedPath = protectedPaths.some(path =>
    req.path.startsWith(path)
  );

  if (!isProtectedPath) {
    next();
    return;
  }

  // Check if user has required role
  const userRole = req.headers["x-user-role"] as string | undefined;

  if (!userRole) {
    res.status(401).json({ error: "Unauthorized: Missing role header" });
    return;
  }

  // Define role hierarchy
  const roleHierarchy = {
    admin: 3,
    staff: 2,
    volunteer: 1
  };

  // Get required role based on path
  let requiredRole: string;
  if (req.path.startsWith("/admin")) {
    requiredRole = "admin";
  } else if (req.path.startsWith("/staff")) {
    requiredRole = "staff";
  } else if (req.path.startsWith("/volunteer")) {
    requiredRole = "volunteer";
  } else {
    next();
    return;
  }

  // Validate role permissions
  const userLevel = roleHierarchy[userRole as keyof typeof roleHierarchy];
  const requiredLevel = roleHierarchy[requiredRole as keyof typeof roleHierarchy];

  if (!userLevel || !requiredLevel || userLevel < requiredLevel) {
    res.status(403).json({ error: "Forbidden: Insufficient permissions" });
    return;
  }

  next();
}

import { useState } from "react";

export function DonationForm() {
