            color: "#155724",
            padding: "15px",
            borderRadius: "5px",
            marginBottom: "20px"
          }}>
            Thank you for your donation!
          </div>
        ) : null}

        {submitError ? (
          <div style={{
            backgroundColor: "#f8d7da",
            color: "#721c24",
            padding: "15px",
            borderRadius: "5px",
            marginBottom: "20px"
