import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const JWT_SECRET = process.env.JWT_SECRET;

function isValidToken(token: string): boolean {
  if (!JWT_SECRET) return false;

  const parts = token.split(".");
  if (parts.length !== 3) return false;

  const [header, payload, signature] = parts;

  const expectedSignature = createHmac("sha256", JWT_SECRET)
    .update(`${header}.${payload}`)
    .digest("base64url");

  try {
    const expectedBytes = Buffer.from(expectedSignature, "base64url");
    const actualBytes = Buffer.from(signature, "base64url");

    return timingSafeEqual(expectedBytes, actualBytes);
  } catch {
    return false;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to /login
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  const authHeader = req.header("Authorization");

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Missing or invalid Authorization header" });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '

  if (!isValidToken(token)) {
    res.status(401).json({ error: "Invalid token" });
    return;
  }

  next();
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

// In-memory storage for rate limits
const rateLimits = new Map<string, { count: number; windowStart: number }>();

// Configuration
const MAX_ATTEMPTS = 5;
const WINDOW_SIZE_MS = 15 * 60 * 1000; // 15 minutes
const MAX_API_CALLS = 100;
const API_WINDOW_SIZE_MS = 60 * 60 * 1000; // 1 hour

export function middleware(req: Request, res: Response, next: NextFunction): void {
  const clientIP = getClientIP(req);

  // Only apply rate limiting to specific routes
  if (req.path === "/auth" && req.method === "POST") {
    // Rate limit authentication attempts
    const authKey = `auth:${clientIP}`;
    const authLimit = rateLimits.get(authKey);

    if (authLimit) {
      const now = Date.now();
      if (now - authLimit.windowStart < WINDOW_SIZE_MS) {
        if (authLimit.count >= MAX_ATTEMPTS) {
          return res.status(429).json({
            error: "Too many authentication attempts. Please try again later."
          });
        }

        // Increment counter
        authLimit.count += 1;
      } else {
        // Reset window
        authLimit.count = 1;
        authLimit.windowStart = now;
      }
    } else {
      rateLimits.set(authKey, { count: 1, windowStart: Date.now() });
    }
  }

  // Apply API rate limiting for all requests
  const apiKey = `api:${clientIP}`;
  const apiLimit = rateLimits.get(apiKey);

  if (apiLimit) {
    const now = Date.now();
    if (now - apiLimit.windowStart < API_WINDOW_SIZE_MS) {
      if (apiLimit.count >= MAX_API_CALLS) {
        return res.status(429).json({
          error: "Rate limit exceeded. Please try again later."
        });
      }

      // Increment counter
      apiLimit.count += 1;
    } else {
      // Reset window
      apiLimit.count = 1;
      apiLimit.windowStart = now;
    }
  } else {
    rateLimits.set(apiKey, { count: 1, windowStart: Date.now() });
  }

  next();
}

function getClientIP(req: Request): string {
  return (
    req.headers["x-forwarded-for"] ||
    req.headers["x-real-ip"] ||
    req.connection.remoteAddress ||
    req.socket.remoteAddress ||
    (req.connection as any).socket?.remoteAddress ||
    ""
  ).toString();
}

