import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to POST /orders and PUT /orders routes
  if (!(req.method === "POST" && req.path === "/orders") && !(req.method === "PUT" && req.path === "/orders")) {
    next();
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid authorization header" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    res.status(500).json({ error: "Internal Server Error: JWT_SECRET not configured" });
    return;
  }

  // Split token into parts
  const parts = token.split(".");
  if (parts.length !== 3) {
    res.status(401).json({ error: "Unauthorized: Invalid token format" });
    return;
  }

  const [header, payload, signature] = parts;

  // Verify signature
  const expectedSignature = createHmac("sha256", secret)
    .update(`${header}.${payload}`)
    .digest("base64url");

  const signatureBuffer = Buffer.from(signature, "base64url");
  const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

  try {
    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      res.status(401).json({ error: "Unauthorized: Invalid token signature" });
      return;
    }
  } catch {
    res.status(401).json({ error: "Unauthorized: Invalid token signature" });
    return;
  }

  // Decode payload
  const decodedPayload = JSON.parse(Buffer.from(payload, "base64url").toString());

  // Check role
  const { role } = decodedPayload;
  if (role !== "admin" && role !== "staff") {
    res.status(403).json({ error: "Forbidden: Insufficient permissions" });
    return;
  }

  // Attach role to request for downstream middleware/routes
  (req as any).userRole = role;
  next();
}

import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(":memory:");

interface User {
  id: number;
  name: string;
  email: string;
  role: string;
  password_hash: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS users (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    email TEXT UNIQUE NOT NULL,
    role TEXT NOT NULL,
    password_hash TEXT NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllUsers(): User[] {
  const stmt = db.prepare("SELECT * FROM users");
  return stmt.all() as unknown as User[];
}

export function getUserById(id: number): User | undefined {
  const stmt = db.prepare("SELECT * FROM users WHERE id = ?");
  return stmt.get(id) as unknown as User | undefined;
}

export function insertUser(user: Omit<User, "id">): number {
  const stmt = db.prepare(
    "INSERT INTO users (name, email, role, password_hash) VALUES (?, ?, ?, ?)"
  );
  const result = stmt.run(user.name, user.email, user.role, user.password_hash);
  return Number(result.lastInsertRowid);
}

export function updateUser(id: number, user: Partial<Omit<User, "id">>): boolean {
  const fields = [];
  const values = [];

  if (user.name !== undefined) {
    fields.push("name = ?");
    values.push(user.name);
  }

  if (user.email !== undefined) {
    fields.push("email = ?");
    values.push(user.email);
  }

  if (user.role !== undefined) {
    fields.push("role = ?");
    values.push(user.role);
  }

  if (user.password_hash !== undefined) {
    fields.push("password_hash = ?");
    values.push(user.password_hash);
  }

  if (fields.length === 0) return false;

  values.push(id);

  const sql = `UPDATE users SET ${fields.join(", ")} WHERE id = ?`;
  const stmt = db.prepare(sql);
  stmt.run(...values);

  return true;
}

export function deleteUser(id: number): boolean {
  const stmt = db.prepare("DELETE FROM users WHERE id = ?");
  const result = stmt.run(id);
  return result.changes > 0;
}

