import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";
import { router as authRouter } from "../routes/authentication-service";
import { router as thesisRouter } from "../routes/thesis-management-api";
import { router as activityRouter } from "../routes/activity-tracking-api";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Skip validation for authentication routes
  if (req.path.startsWith("/auth") || 
      req.path.startsWith("/login") || 
      req.path.startsWith("/register")) {
    return next();
  }

  // Check if the request is for thesis or activity routes
  const isThesisRoute = req.path.startsWith("/thesis");
  const isActivityRoute = req.path.startsWith("/activity");

  if (!isThesisRoute && !isActivityRoute) {
    return next();
  }

  // Get token from headers
  const token = req.headers.authorization?.split(" ")[1];

  if (!token) {
    return res.status(401).json({ error: "Unauthorized" });
  }

  // Verify token signature
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    return res.status(500).json({ error: "Server configuration error" });
  }

  const payload = token.split(".")[0] + "." + token.split(".")[1];
  const expectedSignature = createHmac("sha256", secret)
    .update(payload)
    .digest("hex");

  const actualSignature = token.split(".")[2];

  try {
    const expectedBuffer = Buffer.from(expectedSignature, "hex");
    const actualBuffer = Buffer.from(actualSignature, "hex");

    if (timingSafeEqual(expectedBuffer, actualBuffer)) {
      // Token is valid, proceed
      return next();
    } else {
      return res.status(401).json({ error: "Invalid token" });
    }
  } catch (err) {
    return res.status(401).json({ error: "Invalid token" });
  }
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";
import { router as authRouter } from "../routes/authentication-service";
import { router as thesisRouter } from "../routes/thesis-management-api";
import { router as activityRouter } from "../routes/activity-tracking-api";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Skip authentication for login route
  if (req.method === "POST" && req.path === "/login") {
    return next();
  }

  // Skip authentication for authentication service routes
  if (req.path.startsWith("/auth")) {
    return next();
  }

  // Skip authentication for thesis management API routes
  if (req.path.startsWith("/thesis")) {
    return next();
  }

  // Skip authentication for activity tracking API routes
  if (req.path.startsWith("/activity")) {
    return next();
  }

  // For all other requests, check if user is authenticated
  const token = req.header("Authorization")?.replace("Bearer ", "");

  if (!token) {
    return res.status(401).json({ error: "Unauthorized" });
  }

  const secret = process.env.JWT_SECRET;

  if (!secret) {
    return res.status(500).json({ error: "Server configuration error" });
  }

  try {
    const [payload, signature] = token.split(".");
    const expectedSignature = createHmac("sha256", secret)
      .update(payload)
      .digest("base64url");

    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      return res.status(401).json({ error: "Invalid token" });
    }

    // If we get here, the token is valid
    next();
  } catch (error) {
    return res.status(401).json({ error: "Invalid token" });
  }
}

import { useEffect, useState } from "react";

interface Thesis {
  id: string;
  title: string;
  studentName: string;
  supervisorId: string;
  deadline: string;
}

interface Activity {
  id: string;
  description: string;
  date: string;
}

export function Dashboard() {
  const [theses, setTheses] = useState<Thesis[]>([]);
  const [activities, setActivities] = useState<Activity[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [thesesResponse, activitiesResponse] = await Promise.all([
          fetch("/api/thesis-management-api/theses"),
          fetch("/api/activity-tracking-api/")
        ]);

        if (!thesesResponse.ok || !activitiesResponse.ok) {
          throw new Error("Failed to fetch data");
        }

        const thesesData = await thesesResponse.json();
        const activitiesData = await activitiesResponse.json();

        setTheses(thesesData);
        setActivities(activitiesData);
        setLoading(false);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  // Filter upcoming deadlines (within next 7 days)
  const upcomingDeadlines = theses.filter(thesis => {
    const deadlineDate = new Date(thesis.deadline);
    const now = new Date();
    const diffTime = deadlineDate.getTime() - now.getTime();
    const diffDays = diffTime / (1000 * 60 * 60 * 24);
    return diffDays >= 0 && diffDays <= 7;
  });

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Thesis Supervision Dashboard</h1>

      <div style={{ marginBottom: "30px" }}>
        <h2>Upcoming Deadlines</h2>
        {upcomingDeadlines.length === 0 ? (
          <p>No upcoming deadlines in the next 7 days.</p>
        ) : (
          <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
            {upcomingDeadlines.map(thesis => (
              <div key={thesis.id} style={{ border: "1px solid #ccc", borderRadius: "8px", padding: "15px" }}>
                <strong>{thesis.title}</strong> - {thesis.studentName}
                <br />
                Deadline: {new Date(thesis.deadline).toLocaleDateString()}
              </div>
            ))}
          </div>
        )}
      </div>

      <div style={{ marginBottom: "30px" }}>
        <h2>Recent Activities</h2>
        {activities.length === 0 ? (
          <p>No recent activities.</p>
        ) : (
          <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
            {activities.slice(0, 5).map(activity => (
              <div key={activity.id} style={{ border: "1px solid #ccc", borderRadius: "8px", padding: "15px" }}>
                {activity.description}
                <br />
                <small>{new Date(activity.date).toLocaleString()}</small>
              </div>
            ))}
          </div>
        )}
      </div>

      <div>
        <h2>My Theses</h2>
        {theses.length === 0 ? (
          <p>No theses found.</p>
        ) : (
          <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
            {theses.map(thesis => (
              <div key={thesis.id} style={{ border: "1px solid #ccc", borderRadius: "8px", padding: "15px" }}>
                <strong>{thesis.title}</strong> - {thesis.studentName}
                <br />
                Deadline: {new Date(thesis.deadline).toLocaleDateString()}
              </div>
            ))}
          </div>
        )}
      </div>

      <div style={{ marginTop: "30px", textAlign: "center" }}>
        <button style={{ backgroundColor: "#007bff", color: "white", border: "none", borderRadius: "4px", padding: "10px 20px", cursor: "pointer" }}>
          Add New Thesis
        </button>
      </div>
    </div>
  );
}

