            <label htmlFor="email" style={{ display: "block", marginBottom: "4px", fontWeight: "bold" }}>Email</label>
            <input
              id="email"
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              style={{ width: "100%", padding: "8px", border: "1px solid #ccc", borderRadius: "4px" }}
              required
            />
          </div>

          <div>
            <label htmlFor="password" style={{ display: "block", marginBottom: "4px", fontWeight: "bold" }}>Password</label>
            <input
              id="password"
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              style={{ width: "100%", padding: "8px", border: "1px solid #ccc", borderRadius: "4px" }}
              required
            />
          </div>

          {error && (
            <div style={{ color: "#d32f2f", padding: "8px", backgroundColor: "#ffebee", borderRadius: "4px" }}>
              {error}
            </div>
          )}

          <button
            type="submit"
            disabled={isLoading}
            style={{
              padding: "10px",
              backgroundColor: "#1976d2",
              color: "white",
              border: "none",
              borderRadius: "4px",
              cursor: isLoading ? "not-allowed" : "pointer",
              fontWeight: "bold",
              fontSize: "16px"
            }}
          >
            {isLoading ? "Logging in..." : "Login"}
          </button>
        </form>

        <p style={{ textAlign: "center", marginTop: "20px", color: "#666", fontSize: "14px" }}>
          Enter your professor credentials to access the system
        </p>
      </div>
    </div>
  );
}

