import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";
import { router as authRouter } from "../routes/authentication-service";
import { router as thesisRouter } from "../routes/thesis-management-api";
import { router as activityRouter } from "../routes/activity-tracking-api";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Skip authentication for login route
  if (req.method === "POST" && req.path === "/login") {
    return next();
  }

  // Skip authentication for authentication service routes
  if (req.path.startsWith("/auth")) {
    return next();
  }

  // Skip authentication for thesis management API routes
  if (req.path.startsWith("/thesis")) {
    return next();
  }

  // Skip authentication for activity tracking API routes
  if (req.path.startsWith("/activity")) {
    return next();
  }

  // For all other requests, check if user is authenticated
  const token = req.header("Authorization")?.replace("Bearer ", "");

  if (!token) {
    return res.status(401).json({ error: "Unauthorized" });
  }

  const secret = process.env.JWT_SECRET;

  if (!secret) {
    return res.status(500).json({ error: "Server configuration error" });
  }

  try {
    const [payload, signature] = token.split(".");
    const expectedSignature = createHmac("sha256", secret)
      .update(payload)
      .digest("base64url");

    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      return res.status(401).json({ error: "Invalid token" });
    }

    // If we get here, the token is valid
    next();
  } catch (error) {
    return res.status(401).json({ error: "Invalid token" });
  }
}

