import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Skip validation for non-booking routes and non-POST/PUT/DELETE methods
  if (!req.path.startsWith('/bookings') && !req.path.startsWith('/courts')) {
    next();
    return;
  }

  const method = req.method;
  if (!(method === 'POST' || method === 'PUT' || method === 'DELETE')) {
    next();
    return;
  }

  // Check for authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    res.status(401).json({ error: 'Unauthorized: Missing or invalid token' });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '

  // Validate JWT signature
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    res.status(500).json({ error: 'Server configuration error: JWT_SECRET not set' });
    return;
  }

  try {
    // Simple JWT structure validation
    const parts = token.split('.');
    if (parts.length !== 3) {
      res.status(401).json({ error: 'Unauthorized: Invalid token format' });
      return;
    }

    const [header, payload, signature] = parts;
    const expectedSignature = createHmac('sha256', secret)
      .update(`${header}.${payload}`)
      .digest('base64url');

    const expectedBuffer = Buffer.from(expectedSignature, 'base64url');
    const actualBuffer = Buffer.from(signature, 'base64url');

    if (!timingSafeEqual(expectedBuffer, actualBuffer)) {
      res.status(401).json({ error: 'Unauthorized: Invalid token signature' });
      return;
    }

    // Decode payload to check role
    const decodedPayload = JSON.parse(Buffer.from(payload, 'base64url').toString());
    const userRole = decodedPayload.role;

    if (userRole === 'admin') {
      next();
      return;
    }

    // For regular users, allow only GET requests to courts
    if (userRole === 'user' && req.path.startsWith('/courts') && req.method === 'GET') {
      next();
      return;
    }

    // For regular users, allow only GET requests to their own bookings
    if (userRole === 'user' && req.path.startsWith('/bookings') && req.method === 'GET') {
      const userId = decodedPayload.id;
      const bookingId = req.params.id;

      // This is a simplified check - in practice, you'd want to verify
      // that the booking belongs to the user
      if (bookingId && !bookingId.includes(userId)) {
        res.status(403).json({ error: 'Forbidden: Cannot access this booking' });
        return;
      }

      next();
      return;
    }

    // All other cases should be forbidden
    res.status(403).json({ error: 'Forbidden: Insufficient permissions' });
  } catch (error) {
    res.status(401).json({ error: 'Unauthorized: Invalid token' });
  }
}

import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only validate POST requests to the booking endpoint
  if (req.method !== "POST" || !req.path.startsWith("/bookings")) {
    next();
    return;
  }

  // Check if body exists
  if (!req.body) {
    res.status(400).json({ error: "Request body is required" });
    return;
  }

  const { date, time, duration } = req.body;

  // Validate date format (YYYY-MM-DD)
  if (!date || !/\d{4}-\d{2}-\d{2}/.test(date)) {
    res.status(400).json({ error: "Invalid date format. Expected YYYY-MM-DD" });
    return;
  }

  // Validate time format (HH:MM)
  if (!time || !/\d{2}:\d{2}/.test(time)) {
    res.status(400).json({ error: "Invalid time format. Expected HH:MM" });
    return;
  }

  // Validate duration is a positive integer
  if (!duration || typeof duration !== "number" || duration <= 0 || !Number.isInteger(duration)) {
    res.status(400).json({ error: "Duration must be a positive integer" });
    return;
  }

  // If all validations pass, continue to next middleware/route handler
  next();
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check CSRF protection for POST, PUT, DELETE requests
  if (!['POST', 'PUT', 'DELETE'].includes(req.method)) {
    return next();
  }

  // Define the path patterns that require CSRF protection
  const csrfProtectedPaths = [/^\/bookings\//];
  const isProtectedPath = csrfProtectedPaths.some(pattern => pattern.test(req.path));

  if (!isProtectedPath) {
    return next();
  }

  // Get the expected CSRF token from session
  const expectedToken = req.session?.csrfToken;

  // If no token in session, generate one
  if (!expectedToken) {
    return res.status(500).json({ error: "CSRF secret not configured" });
  }

  // Get the provided token from headers or body
  const providedToken = req.headers['x-csrf-token'] || (req.body && req.body._csrf);

  if (!providedToken) {
    return res.status(403).json({ error: "Missing CSRF token" });
  }

  // Validate the token
  const expectedHash = createHmac('sha256', process.env.JWT_SECRET || '').update(req.session?.id || '').digest('hex');

  try {
    const providedHash = Buffer.from(providedToken.toString(), 'utf8');
    const expectedHashBuffer = Buffer.from(expectedHash, 'hex');

    if (!timingSafeEqual(providedHash, expectedHashBuffer)) {
      return res.status(403).json({ error: "Invalid CSRF token" });
    }
  } catch (err) {
    return res.status(403).json({ error: "Invalid CSRF token" });
  }

  next();
}

import { useEffect, useState } from "react";

interface Court {
  id: number;
  name: string;
  location: string;
  status: 'available' | 'booked';
  price: number;
}

export function CourtListPage() {
  const [courts, setCourts] = useState<Court[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchCourts = async () => {
      try {
        const response = await fetch('/api/courts');
        if (!response.ok) {
          throw new Error('Failed to fetch courts');
        }
        const data = await response.json();
        setCourts(data);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'An unknown error occurred');
      } finally {
        setLoading(false);
      }
    };

    fetchCourts();
  }, []);

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  if (courts.length === 0) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>No courts available.</div>;
  }

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Badminton Courts</h1>
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '20px' }}>
        {courts.map((court) => (
          <div 
            key={court.id}
            style={{
              border: '1px solid #ccc',
              borderRadius: '8px',
              padding: '15px',
              width: '100%',
              maxWidth: '300px',
              boxSizing: 'border-box'
            }}
          >
            <h2 style={{ margin: '0 0 10px 0' }}>{court.name}</h2>
            <p style={{ margin: '5px 0' }}>Location: {court.location}</p>
            <p style={{ margin: '5px 0' }}>Status: <span style={{ fontWeight: 'bold', color: court.status === 'available' ? 'green' : 'red' }}>{court.status}</span></p>
            <p style={{ margin: '5px 0' }}>Price: ${court.price}/hour</p>
            <button 
              style={{
                backgroundColor: court.status === 'available' ? '#4CAF50' : '#f44336',
                color: 'white',
                border: 'none',
                borderRadius: '4px',
                padding: '8px 16px',
                cursor: 'pointer',
                marginTop: '10px',
                width: '100%'
              }}
              disabled={court.status !== 'available'}
            >
              {court.status === 'available' ? 'Book Now' : 'Booked'}
            </button>
          </div>
        ))}
      </div>
    </div>
  );
