export function AdminCourtsManagementPage() {
  const [courts, setCourts] = useState<Court[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchCourts();
  }, []);

  const fetchCourts = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/courts');
      if (!response.ok) {
        throw new Error('Failed to fetch courts');
      }
      const data = await response.json();
      setCourts(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleToggleAvailability = async (id: number) => {
    try {
      const court = courts.find(c => c.id === id);
      if (!court) return;

      const response = await fetch(`/api/courts/${id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          ...court,
          isAvailable: !court.isAvailable
        })
      });

      if (!response.ok) {
        throw new Error('Failed to update court availability');
      }

      // Refresh the list
      fetchCourts();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleDeleteCourt = async (id: number) => {
    try {
      const response = await fetch(`/api/courts/${id}`, {
        method: 'DELETE'
      });

      if (!response.ok) {
        throw new Error('Failed to delete court');
      }

      // Refresh the list
      fetchCourts();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Admin Courts Management</h1>

      {courts.length === 0 ? (
        <p style={{ textAlign: 'center' }}>No courts available.</p>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
          {courts.map(court => (
            <div 
              key={court.id} 
              style={{ 
                border: '1px solid #ccc', 
                borderRadius: '8px', 
                padding: '15px', 
                display: 'flex', 
                justifyContent: 'space-between', 
                alignItems: 'center', 
                flexWrap: 'wrap'
              }}
            >
              <div style={{ flex: '1', minWidth: '200px' }}>
                <h3>{court.name}</h3>
                <p><strong>Location:</strong> {court.location}</p>
                <p><strong>Price per hour:</strong> ${court.pricePerHour.toFixed(2)}</p>
                <p><strong>Status:</strong> {court.isAvailable ? 'Available' : 'Not Available'}</p>
              </div>
              <div style={{ display: 'flex', gap: '10px', flexWrap: 'wrap' }}>
                <button 
                  onClick={() => handleToggleAvailability(court.id)}
                  style={{ 
                    backgroundColor: court.isAvailable ? '#ff6b6b' : '#4ecdc4', 
                    color: 'white', 
                    border: 'none', 
                    borderRadius: '4px', 
                    padding: '8px 12px', 
                    cursor: 'pointer'
                  }}
                >
                  {court.isAvailable ? 'Mark Unavailable' : 'Mark Available'}
