import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check CSRF protection for POST, PUT, DELETE requests
  if (!['POST', 'PUT', 'DELETE'].includes(req.method)) {
    return next();
  }

  // Define the path patterns that require CSRF protection
  const csrfProtectedPaths = [/^\/bookings\//];
  const isProtectedPath = csrfProtectedPaths.some(pattern => pattern.test(req.path));

  if (!isProtectedPath) {
    return next();
  }

  // Get the expected CSRF token from session
  const expectedToken = req.session?.csrfToken;

  // If no token in session, generate one
  if (!expectedToken) {
    return res.status(500).json({ error: "CSRF secret not configured" });
  }

  // Get the provided token from headers or body
  const providedToken = req.headers['x-csrf-token'] || (req.body && req.body._csrf);

  if (!providedToken) {
    return res.status(403).json({ error: "Missing CSRF token" });
  }

  // Validate the token
  const expectedHash = createHmac('sha256', process.env.JWT_SECRET || '').update(req.session?.id || '').digest('hex');

  try {
    const providedHash = Buffer.from(providedToken.toString(), 'utf8');
    const expectedHashBuffer = Buffer.from(expectedHash, 'hex');

    if (!timingSafeEqual(providedHash, expectedHashBuffer)) {
      return res.status(403).json({ error: "Invalid CSRF token" });
    }
  } catch (err) {
    return res.status(403).json({ error: "Invalid CSRF token" });
  }

  next();
}

