const mockLessons = [
  { id: "1", title: "Basic Driving", date: "2023-06-15", time: "09:00", duration: 60, maxBookings: 5 },
  { id: "2", title: "Advanced Driving", date: "2023-06-16", time: "14:00", duration: 90, maxBookings: 3 }
];

