  { id: "1", lessonId: "1", studentName: "John Doe", studentEmail: "john@example.com" },
  { id: "2", lessonId: "1", studentName: "Jane Smith", studentEmail: "jane@example.com" }
];

const findLessonById = (id: string) => {
  return mockLessons.find(lesson => lesson.id === id);
};

const findBookingByLessonId = (lessonId: string) => {
  return mockBookings.filter(booking => booking.lessonId === lessonId);
};

const isLessonAvailable = (lessonId: string) => {
  const lesson = findLessonById(lessonId);
  if (!lesson) return false;

  const bookings = findBookingByLessonId(lessonId);
  return bookings.length < lesson.maxBookings;
};

// Get all lessons
router.get("/lessons", (req: Request, res: Response) => {
  res.json(mockLessons);
});

// Get a specific lesson by ID
router.get("/lessons/:id", (req: Request, res: Response) => {
  const lesson = findLessonById(req.params.id);
  if (!lesson) {
    return res.status(404).json({ error: "Lesson not found" });
  }
  res.json(lesson);
});

// Create a new lesson
router.post("/lessons", (req: Request, res: Response) => {
  const { title, date, time, duration, maxBookings } = req.body;

  if (!title || !date || !time || !duration || !maxBookings) {
    return res.status(400).json({ error: "Missing required fields" });
  }

  const newLesson = {
    id: String(mockLessons.length + 1),
    title,
    date,
    time,
    duration,
    maxBookings
  };

  mockLessons.push(newLesson);
  res.status(201).json(newLesson);
});

// Update a lesson
router.put("/lessons/:id", (req: Request, res: Response) => {
  const lessonIndex = mockLessons.findIndex(lesson => lesson.id === req.params.id);

  if (lessonIndex === -1) {
    return res.status(404).json({ error: "Lesson not found" });
  }

  const { title, date, time, duration, maxBookings } = req.body;

  if (!title || !date || !time || !duration || !maxBookings) {
    return res.status(400).json({ error: "Missing required fields" });
  }

  const updatedLesson = {
    id: req.params.id,
    title,
    date,
    time,
    duration,
    maxBookings
  };

  mockLessons[lessonIndex] = updatedLesson;
  res.json(updatedLesson);
});

// Delete a lesson
router.delete("/lessons/:id", (req: Request, res: Response) => {
  const lessonIndex = mockLessons.findIndex(lesson => lesson.id === req.params.id);

  if (lessonIndex === -1) {
    return res.status(404).json({ error: "Lesson not found" });
  }

  mockLessons.splice(lessonIndex, 1);
  res.json({ message: "Lesson deleted successfully" });
});

// Book a lesson
router.post("/lessons/:id/book", (req: Request, res: Response) => {
  const lesson = findLessonById(req.params.id);

  if (!lesson) {
    return res.status(404).json({ error: "Lesson not found" });
  }

  const { studentName, studentEmail } = req.body;

  if (!studentName || !studentEmail) {
    return res.status(400).json({ error: "Missing required fields" });
  }

  if (!isLessonAvailable(req.params.id)) {
    return res.status(400).json({ error: "Lesson is fully booked" });
