import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to protected routes
  const protectedPaths = ["/lessons", "/bookings", "/users"];
  const isProtectedPath = protectedPaths.some(path =>
    req.path.startsWith(path)
  );

  if (!isProtectedPath) {
    next();
    return;
  }

  // Check if user has proper role access
  const userRole = req.headers["x-user-role"] as string | undefined;

  if (!userRole) {
    res.status(401).json({ error: "Unauthorized: Missing role header" });
    return;
  }

  // Define role requirements for different paths
  const roleRequirements: Record<string, string[]> = {
    "/lessons": ["student", "instructor", "admin"],
    "/bookings": ["student", "instructor", "admin"],
    "/users": ["admin"]
  };

  const path = req.path;
  let requiredRoles: string[] = [];

  // Find the appropriate role requirements for the current path
  for (const [route, roles] of Object.entries(roleRequirements)) {
    if (path.startsWith(route)) {
      requiredRoles = roles;
      break;
    }
  }

  // If no specific requirements found, allow all roles
  if (requiredRoles.length === 0) {
    requiredRoles = ["student", "instructor", "admin"];
  }

  // Check if user's role is authorized for this path
  if (!requiredRoles.includes(userRole)) {
    res.status(403).json({ error: "Forbidden: Insufficient role permissions" });
    return;
  }

  next();
}

