export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only handle POST requests to /login
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  const { username, password } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: "Username and password required" });
  }

  // Mock authentication logic
  const storedHash = createHmac("sha256", process.env.JWT_SECRET || "").update(username + password).digest();
  const providedHash = createHmac("sha256", process.env.JWT_SECRET || "").update(username + password).digest();

  try {
    if (timingSafeEqual(storedHash, providedHash)) {
      // In a real app, we'd generate a JWT here
      res.status(200).json({ message: "Login successful" });
    } else {
      res.status(401).json({ error: "Invalid credentials" });
    }
  } catch (error) {
    res.status(401).json({ error: "Authentication failed" });
  }
}

