import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply RBAC to POST, PUT, DELETE requests
  if (!['POST', 'PUT', 'DELETE'].includes(req.method)) {
    next();
    return;
  }

  // Check if user has required role
  const userRole = req.headers['x-user-role'] as string | undefined;

  // If no role header, deny access
  if (!userRole) {
    res.status(403).json({ error: 'Access denied: role not specified' });
    return;
  }

  // Define role permissions
  const permissions: Record<string, string[]> = {
    admin: ['create', 'read', 'update', 'delete'],
    staff: ['read', 'update']
  };

  // Get required permission based on HTTP method
  const requiredPermission = getPermissionFromMethod(req.method);

  // Check if user role has required permission
  const userPermissions = permissions[userRole] || [];

  if (!userPermissions.includes(requiredPermission)) {
    res.status(403).json({ error: 'Access denied: insufficient permissions' });
    return;
  }

  next();
}

function getPermissionFromMethod(method: string): string {
  switch (method) {
    case 'POST': return 'create';
    case 'GET': return 'read';
    case 'PUT': return 'update';
    case 'DELETE': return 'delete';
    default: return 'read';
  }
}

