import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const SESSION_TIMEOUT = 30 * 60 * 1000; // 30 minutes

interface SessionData {
  userId: string;
  sessionId: string;
  createdAt: number;
}

// In-memory session store (in production, use Redis or database)
const sessions: Map<string, SessionData> = new Map();

function generateToken(): string {
  const timestamp = Date.now().toString();
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    throw new Error("JWT_SECRET environment variable is not set");
  }

  const hmac = createHmac("sha256", secret);
  hmac.update(timestamp);
  const signature = hmac.digest("hex");

  return `${timestamp}.${signature}`;
}

function verifyToken(token: string): boolean {
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    return false;
  }

  try {
    const [timestamp, signature] = token.split(".");
    const expectedSignature = createHmac("sha256", secret)
      .update(timestamp)
      .digest("hex");

    const expectedBuffer = Buffer.from(expectedSignature);
    const actualBuffer = Buffer.from(signature);

    return timingSafeEqual(expectedBuffer, actualBuffer);
  } catch {
    return false;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    return next();
  }

  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return res.status(401).json({ error: "Missing or invalid authorization header" });
  }

  const token = authHeader.substring(7); // Remove "Bearer " prefix

  if (!verifyToken(token)) {
    return res.status(401).json({ error: "Invalid session" });
  }

  // Extract user ID from token (simplified for example)
  const [timestamp, _signature] = token.split(".");
  const userId = "user123"; // This would normally be extracted from the token payload

  // Create session
  const sessionId = generateToken();
  const sessionData: SessionData = {
    userId,
    sessionId,
    createdAt: Date.now(),
  };

  sessions.set(sessionId, sessionData);

  // Attach session to response
  res.locals.session = sessionData;

  return next();
}

import { useEffect, useState } from "react";

interface Supplier {
  id: number;
  name: string;
  contactPerson: string;
  email: string;
  phoneNumber: string;
  address: string;
  taxId: string;
}

export function SupplierManagementPage() {
  const [suppliers, setSuppliers] = useState<Supplier[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [formData, setFormData] = useState<Omit<Supplier, "id">>({ 
    name: "",
    contactPerson: "",
    email: "",
    phoneNumber: "",
    address: "",
    taxId: ""
  });
  const [editingId, setEditingId] = useState<number | null>(null);

  useEffect(() => {
    fetchSuppliers();
  }, []);

  const fetchSuppliers = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/suppliers");
      if (!response.ok) {
        throw new Error(`Failed to fetch suppliers: ${response.status}`);
      }
      const data = await response.json();
      setSuppliers(data);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: value
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const url = editingId 
        ? `/api/suppliers/${editingId}`
        : "/api/suppliers";
      const method = editingId ? "PUT" : "POST";

      const response = await fetch(url, {
        method,
        headers: {
          "Content-Type": "application/json"
        },
        body: JSON.stringify(formData)
      });

      if (!response.ok) {
        throw new Error(`Failed to ${method} supplier: ${response.status}`);
      }

      // Reset form and refresh data
      setFormData({ 
        name: "",
        contactPerson: "",
        email: "",
        phoneNumber: "",
        address: "",
        taxId: ""
      });
      setEditingId(null);
      fetchSuppliers();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleEdit = (supplier: Supplier) => {
    setFormData({
      name: supplier.name,
      contactPerson: supplier.contactPerson,
      email: supplier.email,
      phoneNumber: supplier.phoneNumber,
      address: supplier.address,
      taxId: supplier.taxId
    });
    setEditingId(supplier.id);
  };

  const handleDelete = async (id: number) => {
    try {
      const response = await fetch(`/api/suppliers/${id}`, {
        method: "DELETE"
      });

      if (!response.ok) {
        throw new Error(`Failed to delete supplier: ${response.status}`);
      }

      fetchSuppliers();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const containerStyle: React.CSSProperties = {
    maxWidth: "800px",
    margin: "0 auto",
    padding: "20px",
    fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif"
