import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to POST requests to /orders
  if (req.method !== "POST" || !req.path.startsWith("/orders")) {
    next();
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error: JWT_SECRET not set" });
    return;
  }

  // Simple token validation - in a real app, you'd decode and verify the JWT properly
  // For this example, we'll assume the token contains role information
  try {
    // Decode the token (simplified for this example)
    const payload = JSON.parse(Buffer.from(token.split(".")[1], "base64").toString());

    // Check if user has admin or staff role
    if (payload.role === "admin" || payload.role === "staff") {
      next();
    } else {
      res.status(403).json({ error: "Forbidden: Insufficient permissions" });
    }
  } catch (error) {
    res.status(401).json({ error: "Unauthorized: Invalid token format" });
  }
}

import type { Request, Response, NextFunction } from "express";
import { createHash, scryptSync, randomBytes, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to /users endpoint
  if (req.method !== "POST" || !req.path.startsWith("/users")) {
    next();
    return;
  }

  // Check if password exists in request body
  if (!req.body || typeof req.body.password !== "string") {
    next();
    return;
  }

  // Hash the password using scrypt
  const salt = randomBytes(16).toString("hex");
  const key = scryptSync(req.body.password, salt, 32);
  const hashedPassword = key.toString("hex");

  // Replace the password with the hashed version
  req.body.password = hashedPassword;
  req.body.salt = salt;

  next();
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const ACTIVE_SESSIONS = new Map<string, { username: string; expires: number }>();

function generateSessionId(): string {
  return Math.random().toString(36).substring(2, 15) + Math.random().toString(36).substring(2, 15);
}

function isValidSession(sessionId: string): boolean {
  const session = ACTIVE_SESSIONS.get(sessionId);
  if (!session) return false;
  if (Date.now() > session.expires) {
    ACTIVE_SESSIONS.delete(sessionId);
    return false;
  }
  return true;
}

function verifyToken(token: string): { username: string } | null {
  const secret = process.env.JWT_SECRET;
  if (!secret) return null;

  try {
    const [header, payload, signature] = token.split(".");
    if (!header || !payload || !signature) return null;

    const expectedSignature = createHmac("sha256", secret)
      .update(`${header}.${payload}`)
      .digest("base64url");

    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      return null;
    }

    const decodedPayload = JSON.parse(Buffer.from(payload, "base64url").toString());
    return { username: decodedPayload.username };
  } catch {
    return null;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only handle POST requests to /login
  if (req.method !== "POST" || req.path !== "/login") {
    return next();
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return res.status(401).json({ error: "Authorization header missing or invalid" });
  }

  const token = authHeader.substring(7);
  const verifiedUser = verifyToken(token);
  if (!verifiedUser) {
    return res.status(401).json({ error: "Invalid or expired session" });
  }

  const sessionId = generateSessionId();
  const expires = Date.now() + 3600000; // 1 hour
  ACTIVE_SESSIONS.set(sessionId, { username: verifiedUser.username, expires });

  res.cookie("sessionId", sessionId, { httpOnly: true, maxAge: 3600000 });
  return res.status(200).json({ message: "Login successful" });
}

