import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only enforce role-based access control on POST, PUT, DELETE requests
  if (!['POST', 'PUT', 'DELETE'].includes(req.method)) {
    next();
    return;
  }

  // Check if user is authenticated and has proper role
  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    res.status(401).json({ error: 'Unauthorized: Missing or invalid authorization header' });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '

  // Simple token validation - in a real app, you'd want proper JWT verification
  // For this implementation, we'll assume a basic structure
  try {
    const [userId, role, signature] = token.split('|');

    if (!userId || !role || !signature) {
      res.status(401).json({ error: 'Unauthorized: Invalid token format' });
      return;
    }

    // Verify signature using HMAC-SHA256
    const secret = process.env.JWT_SECRET;

    if (!secret) {
      res.status(500).json({ error: 'Server configuration error: JWT_SECRET not set' });
      return;
    }

    const expectedSignature = createHmac('sha256', secret)
      .update(`${userId}|${role}`)
      .digest('hex');

    const signatureBuffer = Buffer.from(signature, 'hex');
    const expectedSignatureBuffer = Buffer.from(expectedSignature, 'hex');

    if (signatureBuffer.length !== expectedSignatureBuffer.length || 
        !timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      res.status(401).json({ error: 'Unauthorized: Invalid token signature' });
      return;
    }

    // Check role permissions
    if (role === 'admin') {
      // Admins can perform all operations
      next();
      return;
    }

    if (role === 'participant') {
      // Participants can only modify their own data
      const userIdFromToken = userId;
      const userIdFromParams = req.params.userId || req.params.id;

      if (userIdFromParams && userIdFromToken !== userIdFromParams) {
        res.status(403).json({ error: 'Forbidden: Participants can only modify their own data' });
        return;
      }

      // Allow participant to proceed
      next();
      return;
    }

    // Unknown role
    res.status(403).json({ error: 'Forbidden: Unknown user role' });
    return;
  } catch (error) {
    res.status(401).json({ error: 'Unauthorized: Invalid token' });
    return;
  }
}

