export const router = Router();

// Mock database functions - in a real app these would come from a database module
const mockComicStrips = [
  { id: "1", title: "Adventure Time", author: "John Doe", description: "A funny adventure", published: true },
  { id: "2", title: "Space Quest", author: "Jane Smith", description: "Exploring the cosmos", published: false }
];

const findComicStripById = (id: string) => {
  return mockComicStrips.find(comic => comic.id === id);
};

const createComicStrip = (comic: any) => {
  const newComic = { ...comic, id: String(mockComicStrips.length + 1) };
  mockComicStrips.push(newComic);
  return newComic;
};

const updateComicStrip = (id: string, updatedComic: any) => {
  const index = mockComicStrips.findIndex(comic => comic.id === id);
  if (index !== -1) {
    mockComicStrips[index] = { ...mockComicStrips[index], ...updatedComic };
    return mockComicStrips[index];
  }
  return null;
};

const deleteComicStrip = (id: string) => {
  const index = mockComicStrips.findIndex(comic => comic.id === id);
  if (index !== -1) {
    mockComicStrips.splice(index, 1);
    return true;
  }
  return false;
};

// GET /api/comics - List all comic strips
router.get("/", (req: Request, res: Response) => {
  res.json(mockComicStrips);
});

// GET /api/comics/:id - Get a specific comic strip by ID
router.get("/:id", (req: Request, res: Response) => {
  const comic = findComicStripById(req.params.id);
  if (!comic) {
    return res.status(404).json({ error: "Comic strip not found" });
  }
  res.json(comic);
});

// POST /api/comics - Create a new comic strip
router.post("/", (req: Request, res: Response) => {
  const { title, author, description, published } = req.body;

  if (!title || !author) {
    return res.status(400).json({ error: "Title and author are required" });
  }

  const newComic = createComicStrip({
    title,
    author,
    description: description || "",
    published: published || false
  });

  res.status(201).json(newComic);
});

// PUT /api/comics/:id - Update a comic strip
router.put("/:id", (req: Request, res: Response) => {
  const { title, author, description, published } = req.body;

  const existingComic = findComicStripById(req.params.id);
  if (!existingComic) {
    return res.status(404).json({ error: "Comic strip not found" });
  }

  const updatedComic = updateComicStrip(req.params.id, {
    title,
    author,
    description,
    published
  });

  if (!updatedComic) {
    return res.status(404).json({ error: "Comic strip not found" });
  }

  res.json(updatedComic);
});

// DELETE /api/comics/:id - Delete a comic strip
router.delete("/:id", (req: Request, res: Response) => {
  const deleted = deleteComicStrip(req.params.id);

  if (!deleted) {
    return res.status(404).json({ error: "Comic strip not found" });
  }

  res.json({ message: "Comic strip deleted successfully" });
});

