import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check authentication for POST /login route
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  // Check if JWT secret is set
  const jwtSecret = process.env.JWT_SECRET;
  if (!jwtSecret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // Check if request has authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Missing or invalid authorization header" });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '

  // Simple token validation (in a real app, you'd decode and verify the JWT)
  try {
    // For demonstration purposes, we'll just check if token matches expected format
    // In a real implementation, you would verify the JWT signature
    const expectedToken = createHmac("sha256", jwtSecret)
      .update("valid-token")
      .digest("hex");

    const tokenBuffer = Buffer.from(token);
    const expectedBuffer = Buffer.from(expectedToken);

    if (tokenBuffer.length !== expectedBuffer.length) {
      res.status(401).json({ error: "Invalid token" });
      return;
    }

    const isValid = timingSafeEqual(tokenBuffer, expectedBuffer);

    if (!isValid) {
      res.status(401).json({ error: "Invalid token" });
      return;
    }

    // If token is valid, proceed to next middleware
    next();
  } catch (error) {
    res.status(401).json({ error: "Invalid token" });
  }
}

