export function ComicStripListPage() {
  const [comicStrips, setComicStrips] = useState<ComicStrip[]>([]);
  const [searchTerm, setSearchTerm] = useState("");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchComicStrips = async () => {
      try {
        const response = await fetch("/api/comic-strips");
        if (!response.ok) {
          throw new Error(`Failed to fetch comic strips: ${response.status}`);
        }
        const data = await response.json();
        setComicStrips(data);
        setLoading(false);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
        setLoading(false);
      }
    };

    fetchComicStrips();
  }, []);

  const filteredComicStrips = comicStrips.filter(comicStrip =>
    comicStrip.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
    comicStrip.description.toLowerCase().includes(searchTerm.toLowerCase())
  );

  if (loading) {
