        <div style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
          {filteredComicStrips.map((comicStrip) => (
            <div 
              key={comicStrip.id}
              style={{
                border: "1px solid #ddd",
                borderRadius: "8px",
                padding: "15px",
                boxShadow: "0 2px 4px rgba(0,0,0,0.1)"
