import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  // Check if JWT_SECRET is set
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // For demonstration purposes, we'll just check if the request has a valid token
  // In a real implementation, this would involve actual token verification
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7);

  // Simple token validation - in reality, this should verify HMAC-SHA256 signature
  try {
    const expectedSignature = createHmac("sha256", secret)
      .update(token.split(".")[0] + "." + token.split(".")[1])
      .digest("hex");

    const actualSignature = token.split(".")[2];

    // Use timingSafeEqual to prevent timing attacks
    const isValid = timingSafeEqual(
      Buffer.from(expectedSignature),
      Buffer.from(actualSignature)
    );

    if (!isValid) {
      res.status(401).json({ error: "Invalid token" });
      return;
    }

    next();
  } catch (error) {
    res.status(401).json({ error: "Invalid token" });
  }
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const JWT_SECRET = process.env.JWT_SECRET;

function isValidToken(token: string): boolean {
  if (!JWT_SECRET) return false;

  const parts = token.split(".");
  if (parts.length !== 3) return false;

  const [header, payload, signature] = parts;

  const expectedSignature = createHmac("sha256", JWT_SECRET)
    .update(`${header}.${payload}`)
    .digest();

  try {
    const actualSignature = Buffer.from(signature, "base64");
    return timingSafeEqual(expectedSignature, actualSignature);
  } catch {
    return false;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only enforce authorization on POST, PUT, DELETE requests to protected routes
  const isProtectedRoute = req.path.startsWith("/clients") && 
                          (req.method === "POST" || 
                           req.method === "PUT" || 
                           req.method === "DELETE");

  if (!isProtectedRoute) {
    next();
    return;
  }

  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid authorization header" });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '

  if (!isValidToken(token)) {
    res.status(401).json({ error: "Unauthorized: Invalid token" });
    return;
  }

  // Token is valid, proceed to next middleware/route handler
  next();
}

