import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock data - in a real app this would come from a database
const mockTourPackages = [
  {
    id: "1",
    name: "Beach Paradise",
    description: "A relaxing vacation by the beach.",
    price: 1200,
    duration: "7 days",
    destination: "Maldives"
  },
  {
    id: "2",
    name: "Mountain Adventure",
    description: "Explore the beautiful mountains and forests.",
    price: 900,
    duration: "5 days",
    destination: "Swiss Alps"
  }
];

// Get all tour packages
router.get("/packages", (req: Request, res: Response) => {
  res.json(mockTourPackages);
});

// Get a specific tour package by ID
router.get("/packages/:id", (req: Request, res: Response) => {
  const id = req.params.id;
  const packageItem = mockTourPackages.find(p => p.id === id);

  if (!packageItem) {
    return res.status(404).json({ error: "Package not found" });
  }

  res.json(packageItem);
});

// Create a new tour package
router.post("/packages", (req: Request, res: Response) => {
  const { name, description, price, duration, destination } = req.body;

  // Basic validation
  if (!name || !description || !price || !duration || !destination) {
    return res.status(400).json({ error: "All fields are required" });
  }

  const newPackage = {
    id: String(mockTourPackages.length + 1),
    name,
    description,
    price: Number(price),
    duration,
    destination
  };

  mockTourPackages.push(newPackage);
  res.status(201).json(newPackage);
});

// Update a tour package
router.put("/packages/:id", (req: Request, res: Response) => {
  const id = req.params.id;
  const { name, description, price, duration, destination } = req.body;

  const packageIndex = mockTourPackages.findIndex(p => p.id === id);

  if (packageIndex === -1) {
    return res.status(404).json({ error: "Package not found" });
  }

  // Basic validation
  if (!name || !description || !price || !duration || !destination) {
    return res.status(400).json({ error: "All fields are required" });
  }

  const updatedPackage = {
    id,
    name,
    description,
    price: Number(price),
    duration,
    destination
  };

  mockTourPackages[packageIndex] = updatedPackage;
  res.json(updatedPackage);
});

// Delete a tour package
router.delete("/packages/:id", (req: Request, res: Response) => {
  const id = req.params.id;
  const packageIndex = mockTourPackages.findIndex(p => p.id === id);

  if (packageIndex === -1) {
    return res.status(404).json({ error: "Package not found" });
  }

  mockTourPackages.splice(packageIndex, 1);
  res.json({ message: "Package deleted successfully" });
});

