import type { Request, Response, NextFunction } from "express";
import { createHash, randomBytes } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // This middleware is designed to handle password hashing for user registration
  // It should only process POST requests to the /register endpoint
  if (req.method !== "POST" || req.path !== "/register") {
    next();
    return;
  }

  // Check if password exists in request body
  if (!req.body || typeof req.body.password !== "string") {
    next();
    return;
  }

  // Hash the password using SHA-256 with a salt
  const salt = randomBytes(32).toString("hex");
  const hashedPassword = createHash("sha256")
    .update(req.body.password + salt)
    .digest("hex");

  // Replace the password with the hashed version in the request body
  req.body.password = hashedPassword;
  req.body.salt = salt;

  next();
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST, PUT, PATCH, DELETE requests
  if (!['POST', 'PUT', 'PATCH', 'DELETE'].includes(req.method)) {
    next();
    return;
  }

  // Validate and sanitize input data
  if (req.body) {
    sanitizeInput(req.body);
  }

  // Validate query parameters
  if (req.query) {
    sanitizeQuery(req.query);
  }

  next();
}

function sanitizeInput(input: any): void {
  if (typeof input === 'object' && input !== null) {
    for (const [key, value] of Object.entries(input)) {
      if (typeof value === 'string') {
        // Basic XSS prevention
        input[key] = value
          .replace(/<script[^>]*>.*?<\/script>/gi, '')
          .replace(/<iframe[^>]*>.*?<\/iframe>/gi, '')
          .replace(/<object[^>]*>.*?<\/object>/gi, '')
          .replace(/<embed[^>]*>.*?<\/embed>/gi, '');
      } else if (typeof value === 'object') {
        sanitizeInput(value);
      }
    }
  }
}

function sanitizeQuery(query: Record<string, any>): void {
  for (const [key, value] of Object.entries(query)) {
    if (typeof value === 'string') {
      // Basic XSS prevention for query params
      query[key] = value
        .replace(/<script[^>]*>.*?<\/script>/gi, '')
        .replace(/<iframe[^>]*>.*?<\/iframe>/gi, '')
        .replace(/<object[^>]*>.*?<\/object>/gi, '')
        .replace(/<embed[^>]*>.*?<\/embed>/gi, '');
    }
  }
}

