export function TourPackageDetailPage({ packageId }: { packageId: string }) {
  const [tourPackage, setTourPackage] = useState<TourPackage | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchTourPackage = async () => {
      try {
        const response = await fetch(`/api/tour-packages/${packageId}`);
        if (!response.ok) {
          throw new Error(`Failed to fetch tour package: ${response.status}`);
        }
        const data = await response.json();
        setTourPackage(data);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    };

    fetchTourPackage();
  }, [packageId]);

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  if (!tourPackage) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Tour package not found</div>;
