              name="fullName"
              value={formData.fullName}
              onChange={handleChange}
              style={{
                width: "100%",
                padding: "8px 12px",
                border: errors.fullName ? "1px solid #ef4444" : "1px solid #d1d5db",
                borderRadius: "4px",
                fontSize: "16px"
              }}
            />
            {errors.fullName && <span style={{ color: "#ef4444", fontSize: "14px" }}>{errors.fullName}</span>}
          </div>

          <div style={{ marginBottom: "12px" }}>
            <label htmlFor="email" style={{ display: "block", marginBottom: "4px", fontWeight: "500" }}>
              Email Address *
            </label>
