              name="email"
              value={formData.email}
              onChange={handleChange}
              style={{
                width: "100%",
                padding: "8px 12px",
                border: errors.email ? "1px solid #ef4444" : "1px solid #d1d5db",
                borderRadius: "4px",
                fontSize: "16px"
              }}
            />
            {errors.email && <span style={{ color: "#ef4444", fontSize: "14px" }}>{errors.email}</span>}
          </div>

          <div style={{ marginBottom: "12px" }}>
