import { useEffect, useState } from "react";

interface Booking {
  id: string;
  packageName: string;
  startDate: string;
  endDate: string;
  status: "confirmed" | "pending" | "cancelled";
}

export function UserDashboard() {
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchBookings();
  }, []);

  const fetchBookings = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/bookings');
      if (!response.ok) {
        throw new Error('Failed to fetch bookings');
      }
      const data = await response.json();
      setBookings(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleCancel = async (id: string) => {
    try {
      const response = await fetch(`/api/bookings/${id}`, {
        method: 'DELETE',
      });
      if (!response.ok) {
        throw new Error('Failed to cancel booking');
      }
      // Refresh the bookings list
      fetchBookings();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  return (
    <div style={{
      fontFamily: 'system-ui, sans-serif',
      maxWidth: '800px',
      margin: '0 auto',
      padding: '20px',
    }}>
      <h1 style={{ textAlign: 'center' }}>My Bookings</h1>

      {bookings.length === 0 ? (
        <p style={{ textAlign: 'center', padding: '20px' }}>You have no bookings yet.</p>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
          {bookings.map(booking => (
            <div 
              key={booking.id} 
              style={{
                border: '1px solid #ccc',
                borderRadius: '8px',
                padding: '15px',
                backgroundColor: '#f9f9f9',
              }}
            >
              <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '10px' }}>
                <h3>{booking.packageName}</h3>
                <span style={{ fontWeight: 'bold', color: booking.status === 'confirmed' ? 'green' : booking.status === 'pending' ? 'orange' : 'red' }}>
                  {booking.status.charAt(0).toUpperCase() + booking.status.slice(1)}
                </span>
              </div>
              <p><strong>Start Date:</strong> {new Date(booking.startDate).toLocaleDateString()}</p>
              <p><strong>End Date:</strong> {new Date(booking.endDate).toLocaleDateString()}</p>
              <div style={{ marginTop: '10px' }}>
                {booking.status === 'confirmed' && (
                  <button 
                    onClick={() => handleCancel(booking.id)}
                    style={{
                      backgroundColor: '#ff4d4d',
                      color: 'white',
                      border: 'none',
                      borderRadius: '4px',
                      padding: '8px 12px',
                      cursor: 'pointer',
                    }}
                  >
                    Cancel Booking
                  </button>
                )}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock data for tour packages
const tourPackages = [
  {
    id: "1",
    name: "Beach Paradise",
    description: "Relax on beautiful beaches with crystal clear waters.",
    price: 1200,
    available: true,
    duration: 7,
    location: "Maldives"
  },
  {
    id: "2",
    name: "Mountain Adventure",
    description: "Explore majestic mountains and hiking trails.",
    price: 900,
    available: true,
    duration: 5,
    location: "Swiss Alps"
  }
];

// Get all tour packages
router.get("/", (req: Request, res: Response) => {
  res.json(tourPackages);
});

// Get a specific tour package by ID
router.get("/:id", (req: Request, res: Response) => {
  const packageId = req.params.id;
  const pkg = tourPackages.find(p => p.id === packageId);

  if (!pkg) {
    return res.status(404).json({ error: "Tour package not found" });
  }

  res.json(pkg);
});

// Create a new tour package
router.post("/", (req: Request, res: Response) => {
  const { name, description, price, available, duration, location } = req.body;

  if (!name || !description || !price || !duration || !location) {
    return res.status(400).json({ error: "Missing required fields" });
  }

  const newPackage = {
    id: (tourPackages.length + 1).toString(),
    name,
    description,
    price: Number(price),
    available: Boolean(available),
    duration: Number(duration),
    location
  };

  tourPackages.push(newPackage);
  res.status(201).json(newPackage);
});

// Update a tour package
router.put("/:id", (req: Request, res: Response) => {
  const packageId = req.params.id;
  const pkgIndex = tourPackages.findIndex(p => p.id === packageId);

  if (pkgIndex === -1) {
    return res.status(404).json({ error: "Tour package not found" });
  }

  const { name, description, price, available, duration, location } = req.body;

  if (!name || !description || !price || !duration || !location) {
    return res.status(400).json({ error: "Missing required fields" });
  }

  tourPackages[pkgIndex] = {
    id: packageId,
    name,
    description,
    price: Number(price),
    available: Boolean(available),
    duration: Number(duration),
    location
  };

  res.json(tourPackages[pkgIndex]);
});

// Delete a tour package
router.delete("/:id", (req: Request, res: Response) => {
  const packageId = req.params.id;
  const pkgIndex = tourPackages.findIndex(p => p.id === packageId);

  if (pkgIndex === -1) {
    return res.status(404).json({ error: "Tour package not found" });
  }

  tourPackages.splice(pkgIndex, 1);
  res.json({ message: "Tour package deleted successfully" });
