export const router = Router();

// Mock data to simulate database operations
let articles = [
  { id: 1, title: "First Article", content: "Content of first article", category: "Technology", author: "John Doe" },
  { id: 2, title: "Second Article", content: "Content of second article", category: "Health", author: "Jane Smith" }
];

let nextId = 3;

// GET /api/articles - List all articles
router.get("/articles", (req: Request, res: Response) => {
  res.json(articles);
});

// GET /api/articles/:id - Get one article by ID
router.get("/articles/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const article = articles.find(a => a.id === id);

  if (!article) {
    return res.status(404).json({ error: "Article not found" });
  }

  res.json(article);
});

// POST /api/articles - Create a new article
router.post("/articles", (req: Request, res: Response) => {
  const { title, content, category, author } = req.body;

  if (!title || !content || !category || !author) {
    return res.status(400).json({ error: "Title, content, category, and author are required" });
  }

  const newArticle = {
    id: nextId++,
    title,
    content,
    category,
    author
  };

  articles.push(newArticle);
  res.status(201).json(newArticle);
});

// PUT /api/articles/:id - Update an existing article
router.put("/articles/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { title, content, category, author } = req.body;

  const articleIndex = articles.findIndex(a => a.id === id);

  if (articleIndex === -1) {
    return res.status(404).json({ error: "Article not found" });
  }

  if (!title || !content || !category || !author) {
    return res.status(400).json({ error: "Title, content, category, and author are required" });
  }

  articles[articleIndex] = {
    id,
    title,
    content,
    category,
    author
  };

  res.json(articles[articleIndex]);
});

// DELETE /api/articles/:id - Delete an article
router.delete("/articles/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const articleIndex = articles.findIndex(a => a.id === id);

  if (articleIndex === -1) {
    return res.status(404).json({ error: "Article not found" });
  }

  articles.splice(articleIndex, 1);
  res.json({ message: "Article deleted successfully" });
});

