import { useEffect, useState } from "react";

interface ContentItem {
  id: number;
  title: string;
  category: string;
  published: boolean;
  createdAt: string;
}

export function AdminDashboard() {
  const [contentItems, setContentItems] = useState<ContentItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchContent();
  }, []);

  const fetchContent = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/content');
      if (!response.ok) {
        throw new Error('Failed to fetch content');
      }
      const data = await response.json();
      setContentItems(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const togglePublishStatus = async (id: number) => {
    try {
      const response = await fetch(`/api/content/${id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ published: !contentItems.find(item => item.id === id)?.published })
      });

      if (!response.ok) {
        throw new Error('Failed to update content status');
      }

      // Refresh the content list
      await fetchContent();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const deleteContent = async (id: number) => {
    try {
      const response = await fetch(`/api/content/${id}`, {
        method: 'DELETE'
      });

      if (!response.ok) {
        throw new Error('Failed to delete content');
      }

      // Refresh the content list
      await fetchContent();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Admin Dashboard</h1>

      {contentItems.length === 0 ? (
        <p style={{ textAlign: 'center', padding: '20px' }}>No content available.</p>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
          {contentItems.map(item => (
            <div key={item.id} style={{ border: '1px solid #ccc', borderRadius: '8px', padding: '15px' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <div>
                  <h3>{item.title}</h3>
                  <p><strong>Category:</strong> {item.category}</p>
                  <p><strong>Status:</strong> {item.published ? 'Published' : 'Draft'}</p>
                  <p><small>Created: {new Date(item.createdAt).toLocaleDateString()}</small></p>
                </div>
                <div style={{ display: 'flex', gap: '10px' }}>
                  <button 
                    onClick={() => togglePublishStatus(item.id)}
                    style={{ backgroundColor: item.published ? '#ff6b6b' : '#4ecdc4', color: 'white', border: 'none', borderRadius: '4px', padding: '8px 12px' }}
                  >
                    {item.published ? 'Unpublish' : 'Publish'}
                  </button>
                  <button 
                    onClick={() => deleteContent(item.id)}
                    style={{ backgroundColor: '#ff6b6b', color: 'white', border: 'none', borderRadius: '4px', padding: '8px 12px' }}
                  >
                    Delete
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}

      <div style={{ marginTop: '30px', textAlign: 'center' }}>
        <a href="/admin/create" style={{ backgroundColor: '#4ecdc4', color: 'white', padding: '10px 20px', textDecoration: 'none', borderRadius: '4px' }}>
          Create New Content
        </a>
      </div>
    </div>
  );
