// Mock user data storage (in a real app, this would be a database)
const users = new Map<string, { email: string; password: string }>();

// Mock JWT token generation (in a real app, use a proper JWT library)
const generateToken = (email: string): string => {
  return `token_${email}`;
};

// User registration endpoint
router.post("/register", (req: Request, res: Response) => {
  const { email, password } = req.body;

  // Validate input
  if (!email || !password) {
    return res.status(400).json({ error: "Email and password are required" });
  }

  // Check if user already exists
  if (users.has(email)) {
    return res.status(400).json({ error: "User already exists" });
  }

  // Store user
  users.set(email, { email, password });

  // Generate token
  const token = generateToken(email);

  // Return success response
  return res.status(201).json({ email, token });
});

// User login endpoint
router.post("/login", (req: Request, res: Response) => {
  const { email, password } = req.body;

  // Validate input
  if (!email || !password) {
    return res.status(400).json({ error: "Email and password are required" });
  }

  // Check if user exists
  const user = users.get(email);
  if (!user || user.password !== password) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  // Generate token
  const token = generateToken(email);

  // Return success response
  return res.json({ email, token });
});

// Session validation endpoint
router.get("/validate", (req: Request, res: Response) => {
  const token = req.headers.authorization?.split(" ")[1];

  if (!token) {
    return res.status(401).json({ error: "No token provided" });
  }

  // In a real app, validate the JWT token here
  // For now, we'll just check if it matches our mock format
  if (!token.startsWith("token_")) {
    return res.status(401).json({ error: "Invalid token" });
  }

  // Extract email from token
  const email = token.split("_")[1];

  // Check if user exists
  if (!users.has(email)) {
    return res.status(401).json({ error: "User not found" });
  }

  // Return success response
  return res.json({ email });
});

