  { id: 2, mood: 3, date: "2023-01-02", notes: "Okay, nothing special." },
  { id: 3, mood: 1, date: "2023-01-03", notes: "Not feeling well." },
  { id: 4, mood: 4, date: "2023-01-04", notes: "Good day!" },
  { id: 5, mood: 2, date: "2023-01-05", notes: "Slightly down." },
];

// Get analytics summary
router.get("/summary", (req: Request, res: Response) => {
  // Calculate basic statistics
  const totalEntries = mockEntries.length;

  const averageMood = mockEntries.reduce((sum, entry) => sum + entry.mood, 0) / totalEntries;

  const moodDistribution = [0, 0, 0, 0, 0, 0]; // 0-5 scale
  mockEntries.forEach(entry => {
    moodDistribution[entry.mood]++;
  });

  const mostCommonMood = moodDistribution.indexOf(Math.max(...moodDistribution));

  // Return summary
  res.json({
    totalEntries,
    averageMood: parseFloat(averageMood.toFixed(2)),
    moodDistribution,
    mostCommonMood
  });
});

// Get trend data
router.get("/trend", (req: Request, res: Response) => {
  // Group entries by week
  const weeklyData = [];

  // For simplicity, we'll just return the raw data grouped by date
  const groupedByDate = mockEntries.reduce((acc, entry) => {
    if (!acc[entry.date]) {
      acc[entry.date] = [];
    }
    acc[entry.date].push(entry);
    return acc;
  }, {} as Record<string, typeof mockEntries>);

  // Calculate average mood per date
  const trendData = Object.entries(groupedByDate).map(([date, entries]) => {
    const avgMood = entries.reduce((sum, entry) => sum + entry.mood, 0) / entries.length;
    return {
      date,
      averageMood: parseFloat(avgMood.toFixed(2))
    };
  });

  res.json(trendData);
});

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const JWT_SECRET = process.env.JWT_SECRET;

function decodeJwt(token: string): Record<string, unknown> | null {
  try {
    const payload = token.split('.')[1];
    const decoded = Buffer.from(payload, 'base64').toString('utf-8');
    return JSON.parse(decoded);
  } catch {
    return null;
  }
}

function verifySignature(token: string, secret: string): boolean {
  const [header, payload, signature] = token.split('.');

  if (!header || !payload || !signature) {
    return false;
  }

  const expectedSignature = createHmac('sha256', secret)
    .update(`${header}.${payload}`)
    .digest('base64url');

  const actualSignature = signature;

  try {
    return timingSafeEqual(
      Buffer.from(actualSignature, 'base64url'),
      Buffer.from(expectedSignature, 'base64url')
    );
  } catch {
    return false;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check authentication for POST requests to /api/journal
  if (!(req.method === 'POST' && req.path === '/api/journal')) {
    next();
    return;
  }

  if (!JWT_SECRET) {
    res.status(500).json({ error: 'Server configuration error' });
    return;
  }

  const authHeader = req.header('Authorization');

  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    res.status(401).json({ error: 'Missing or invalid authorization header' });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '

  if (!token) {
    res.status(401).json({ error: 'Missing token' });
    return;
  }

  const decoded = decodeJwt(token);

  if (!decoded) {
    res.status(401).json({ error: 'Invalid token format' });
    return;
  }

  if (!verifySignature(token, JWT_SECRET)) {
    res.status(401).json({ error: 'Invalid token signature' });
    return;
  }

  // Token is valid, proceed to next middleware/route handler
  next();
}

