import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check role-based access for admin routes
  if (!req.path.startsWith('/admin')) {
    next();
    return;
  }

  // Check if user has required role
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    res.status(401).json({ error: 'Unauthorized' });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: 'Server configuration error' });
    return;
  }

  // Simple token validation (in a real app, you'd want proper JWT verification)
  try {
    const [payload, signature] = token.split('.');
    if (!payload || !signature) {
      res.status(401).json({ error: 'Invalid token format' });
      return;
    }

    // Create expected signature
    const expectedSignature = createHmac('sha256', secret)
      .update(payload)
      .digest('base64url');

    // Compare signatures safely
    const expectedBuffer = Buffer.from(expectedSignature, 'base64url');
    const actualBuffer = Buffer.from(signature, 'base64url');

    if (expectedBuffer.length !== actualBuffer.length || 
        !timingSafeEqual(expectedBuffer, actualBuffer)) {
      res.status(401).json({ error: 'Invalid token signature' });
      return;
    }

    // Decode payload to get role (simplified for this example)
    const decodedPayload = Buffer.from(payload, 'base64url').toString('utf8');
    const payloadObj = JSON.parse(decodedPayload);

    if (payloadObj.role !== 'admin') {
      res.status(403).json({ error: 'Forbidden: Admin access required' });
      return;
    }

    next();
  } catch (error) {
    res.status(401).json({ error: 'Invalid token' });
  }
}

