import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const SESSION_TIMEOUT = 30 * 60 * 1000; // 30 minutes

interface SessionData {
  userId: string;
  sessionId: string;
  createdAt: number;
}

// In-memory session store (in production, use Redis or similar)
const sessions: Map<string, SessionData> = new Map();

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only handle POST requests to /login and /logout endpoints
  if (req.method !== "POST") {
    return next();
  }

  if (req.path === "/login") {
    // For login, we don't need to validate existing session
    return next();
  }

  if (req.path === "/logout") {
    // For logout, we don't need to validate existing session
    return next();
  }

  // For all other POST requests, check session validity
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return res.status(401).json({ error: "No active session" });
  }

  const token = authHeader.substring(7); // Remove "Bearer " prefix
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    return res.status(401).json({ error: "Invalid session" });
  }

  try {
    // Simple token format: sessionId|timestamp|signature
    const parts = token.split("|");
    if (parts.length !== 3) {
      return res.status(401).json({ error: "Invalid session" });
    }

    const [sessionId, timestampStr, signature] = parts;
    const timestamp = parseInt(timestampStr, 10);
    if (isNaN(timestamp)) {
      return res.status(401).json({ error: "Invalid session" });
    }

    const session = sessions.get(sessionId);
    if (!session) {
      return res.status(401).json({ error: "Invalid session" });
    }

    // Check if session has expired
    if (Date.now() - session.createdAt > SESSION_TIMEOUT) {
      sessions.delete(sessionId);
      return res.status(401).json({ error: "Session expired" });
    }

    // Verify signature
    const expectedSignature = createHmac("sha256", secret)
      .update(`${sessionId}|${timestamp}`)
      .digest("hex");

    const expectedBuffer = Buffer.from(expectedSignature);
    const actualBuffer = Buffer.from(signature);

    if (actualBuffer.length !== expectedBuffer.length || !timingSafeEqual(actualBuffer, expectedBuffer)) {
      return res.status(401).json({ error: "Invalid session" });
    }

    // If we get here, session is valid
    next();
  } catch (error) {
    return res.status(401).json({ error: "Invalid session" });
  }
}

