import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock user database
const users = [
  {
    id: 1,
    username: "admin",
    password: "admin123",
    role: "admin"
  },
  {
    id: 2,
    username: "user",
    password: "user123",
    role: "user"
  }
];

// Registration endpoint
router.post("/register", (req: Request, res: Response) => {
  const { username, password, role } = req.body;

  // Validate input
  if (!username || !password) {
    return res.status(400).json({ error: "Username and password are required" });
  }

  // Check if user already exists
  const existingUser = users.find(user => user.username === username);
  if (existingUser) {
    return res.status(400).json({ error: "User already exists" });
  }

  // Create new user
  const newUser = {
    id: users.length + 1,
    username,
    password,
    role: role || "user"
  };

  users.push(newUser);
  res.status(201).json(newUser);
});

// Login endpoint
router.post("/login", (req: Request, res: Response) => {
  const { username, password } = req.body;

  // Validate input
  if (!username || !password) {
    return res.status(400).json({ error: "Username and password are required" });
  }

  // Find user
  const user = users.find(u => u.username === username && u.password === password);
  if (!user) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  // Simulate session creation
  const session = {
    userId: user.id,
    username: user.username,
    role: user.role,
    token: `session-${user.id}-${Date.now()}`
  };

  res.json(session);
});

// Middleware to check role
const requireRole = (requiredRole: string) => {
  return (req: Request, res: Response, next: Function) => {
    // In a real app, this would check the session token
    // For now, we'll just simulate it
    const user = users[0]; // Mock current user
    if (user.role !== requiredRole) {
      return res.status(403).json({ error: "Insufficient permissions" });
    }
    next();
  };
};

// Protected route example
router.get("/profile", requireRole("user"), (req: Request, res: Response) => {
  res.json({ message: "User profile accessed successfully" });
});

// Admin-only route example
router.delete("/user/:id", requireRole("admin"), (req: Request, res: Response) => {
  const userId = Number(req.params.id);
  const userIndex = users.findIndex(user => user.id === userId);

  if (userIndex === -1) {
    return res.status(404).json({ error: "User not found" });
  }

  users.splice(userIndex, 1);
  res.json({ message: "User deleted successfully" });
});

