import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock database functions - in a real app these would come from a database module
const mockSites = [
  { id: 1, name: "Site A", capacity: 4, location: "Forest Area" },
  { id: 2, name: "Site B", capacity: 6, location: "Lake Side" },
  { id: 3, name: "Site C", capacity: 2, location: "Mountain View" }
];

const findSiteById = (id: number) => {
  return mockSites.find(site => site.id === id);
};

const createSite = (siteData: Omit<Site, "id">) => {
  const newSite = {
    id: mockSites.length > 0 ? Math.max(...mockSites.map(s => s.id)) + 1 : 1,
    ...siteData
  };
  mockSites.push(newSite);
  return newSite;
};

const updateSite = (id: number, siteData: Partial<Site>) => {
  const index = mockSites.findIndex(site => site.id === id);
  if (index === -1) return null;
  mockSites[index] = { ...mockSites[index], ...siteData };
  return mockSites[index];
};

const deleteSite = (id: number) => {
  const index = mockSites.findIndex(site => site.id === id);
  if (index === -1) return false;
  mockSites.splice(index, 1);
  return true;
};

