// Mock data structures to simulate calendar service functionality
const calendars = new Map<string, { dates: string[] }>();
const reservations = new Map<string, { startDate: string; endDate: string }>();

// Helper function to check if date range conflicts with existing reservations
const hasConflict = (startDate: string, endDate: string): boolean => {
  // Convert dates to Date objects for comparison
  const start = new Date(startDate);
  const end = new Date(endDate);

  for (const [_, reservation] of reservations) {
    const resStart = new Date(reservation.startDate);
    const resEnd = new Date(reservation.endDate);

    // Check for overlapping date ranges
    if (start <= resEnd && end >= resStart) {
      return true;
    }
  }

  return false;
};

// Get calendar for a specific site
router.get("/calendar/:siteId", (req: Request, res: Response) => {
  const { siteId } = req.params;

  if (!calendars.has(siteId)) {
    return res.status(404).json({ error: "Calendar not found" });
  }

  const calendar = calendars.get(siteId)!;
  return res.json(calendar);
});

// Create a new calendar for a site
router.post("/calendar/:siteId", (req: Request, res: Response) => {
  const { siteId } = req.params;

  if (calendars.has(siteId)) {
    return res.status(400).json({ error: "Calendar already exists" });
  }

  calendars.set(siteId, { dates: [] });
  return res.status(201).json({ siteId, dates: [] });
});

// Update calendar dates for a site
