import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to admin routes
  if (!req.path.startsWith('/admin') || req.method === 'GET') {
    next();
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    res.status(401).json({ error: 'Missing or invalid authorization header' });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: 'Server configuration error: JWT_SECRET not set' });
    return;
  }

  // Simple token validation - in a real system, you'd decode and verify the JWT properly
  // For this implementation, we'll just check if it has the right format
  const parts = token.split('.');
  if (parts.length !== 3) {
    res.status(401).json({ error: 'Invalid token format' });
    return;
  }

  // Verify the signature using HMAC-SHA256
  const [header, payload, signature] = parts;
  const expectedSignature = createHmac('sha256', secret)
    .update(`${header}.${payload}`)
    .digest('base64url');

  // Use timingSafeEqual to prevent timing attacks
  const expectedBuffer = Buffer.from(expectedSignature, 'base64url');
  const actualBuffer = Buffer.from(signature, 'base64url');

  try {
    if (!timingSafeEqual(expectedBuffer, actualBuffer)) {
      res.status(401).json({ error: 'Invalid token signature' });
      return;
    }
  } catch {
    res.status(401).json({ error: 'Invalid token signature' });
    return;
  }

  // In a real implementation, you would decode the payload to check roles
  // For now, we'll assume valid tokens have proper roles
  next();
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only validate POST, PUT, PATCH, DELETE requests
  if (!['POST', 'PUT', 'PATCH', 'DELETE'].includes(req.method)) {
    next();
    return;
  }

  // Skip validation for health check endpoints
  if (req.path === '/health') {
    next();
    return;
  }

  // Validate request body for potential injection attacks
  if (req.body) {
    validateRequestBody(req.body);
  }

  // Validate query parameters
  if (req.query) {
    validateQueryParams(req.query);
  }

  next();
}

function validateRequestBody(body: any): void {
  if (typeof body === 'object' && body !== null) {
    Object.entries(body).forEach(([key, value]) => {
      if (typeof value === 'string') {
        // Check for common injection patterns
        if (value.includes('\\')) {
          throw new Error('Invalid input: backslash characters not allowed');
        }
        if (value.includes('"') || value.includes("'")) {
          throw new Error('Invalid input: quotes not allowed');
        }
        if (value.includes('<') || value.includes('>')) {
          throw new Error('Invalid input: HTML tags not allowed');
        }
      } else if (typeof value === 'object') {
        validateRequestBody(value);
      }
    });
  }
}

function validateQueryParams(query: any): void {
  Object.entries(query).forEach(([key, value]) => {
    if (typeof value === 'string') {
      // Check for common injection patterns
      if (value.includes('\\')) {
        throw new Error('Invalid query parameter: backslash characters not allowed');
      }
      if (value.includes('"') || value.includes("'")) {
        throw new Error('Invalid query parameter: quotes not allowed');
      }
      if (value.includes('<') || value.includes('>')) {
        throw new Error('Invalid query parameter: HTML tags not allowed');
      }
    }
  });
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const SESSION_TIMEOUT = 30 * 60 * 1000; // 30 minutes
const JWT_SECRET = process.env.JWT_SECRET;

// Simple in-memory session store (in production, use Redis or similar)
const sessions = new Map<string, { userId: string; expiresAt: number }>();

function isValidToken(token: string): boolean {
  if (!JWT_SECRET) return false;

  const parts = token.split(".");
  if (parts.length !== 3) return false;

  const [header, payload, signature] = parts;

  try {
    // Verify signature using HMAC-SHA256
    const expectedSignature = createHmac("sha256", JWT_SECRET)
      .update(`${header}.${payload}`)
      .digest("base64url");

    const actualSignature = signature;

    // Use timingSafeEqual to prevent timing attacks
    return timingSafeEqual(
      Buffer.from(expectedSignature, "base64url"),
      Buffer.from(actualSignature, "base64url")
    );
  } catch {
    return false;
  }
}

function getSessionIdFromToken(token: string): string | null {
  try {
    const payload = JSON.parse(Buffer.from(token.split(".")[1], "base64url").toString());
    return payload.sessionId || null;
  } catch {
    return null;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  // Check if authorization header exists
  const authHeader = req.header("Authorization");
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
    return;
  }

  const token = authHeader.substring(7); // Remove "Bearer " prefix

  // Validate token signature
  if (!isValidToken(token)) {
    res.status(401).json({ error: "Unauthorized: Invalid token" });
    return;
  }

  // Extract session ID from token
  const sessionId = getSessionIdFromToken(token);
  if (!sessionId) {
    res.status(401).json({ error: "Unauthorized: Invalid token format" });
    return;
  }

  // Check if session exists and is not expired
  const session = sessions.get(sessionId);
  if (!session || Date.now() > session.expiresAt) {
    sessions.delete(sessionId);
    res.status(401).json({ error: "Unauthorized: Session expired" });
    return;
  }

  // Update session expiration
  session.expiresAt = Date.now() + SESSION_TIMEOUT;
  sessions.set(sessionId, session);

  // Attach user info to request object
  (req as any).user = { id: session.userId };

  next();
}

import type { Request, Response, NextFunction } from "express";
import { createHash, scryptSync } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check password validation on POST /register endpoint
  if (req.method !== "POST" || req.path !== "/register") {
    next();
    return;
  }

  const { password } = req.body;

  // Check if password is provided and is a string
  if (!password) {
    return res.status(400).json({ error: "Password is required" });
  }

  if (typeof password !== "string") {
    return res.status(400).json({ error: "Password must be a string" });
  }

  // Check minimum length
  if (password.length < 8) {
    return res.status(400).json({ error: "Password must be at least 8 characters long" });
  }

  // Check for required character types
  if (!/(?=.*[a-z])(?=.*[A-Z])(?=.*\d)/.test(password)) {
    return res.status(400).json({ error: "Password must contain at least one uppercase letter, one lowercase letter, and one digit" });
  }

  // Hash the password before proceeding
  const salt = "salt"; // In a real application, use a unique salt per user
  const hashedPassword = createHash("sha256").update(password + salt).digest("hex");

  // Replace the password with the hashed version in the request body
  req.body.password = hashedPassword;

  next();
}

