    role: "staff"
  }
];

// Mock password hashing function
const hashPassword = (password: string): string => {
  // In a real implementation, this would hash the password
  return `hashed_${password}`;
};

// Mock password verification function
const verifyPassword = (password: string, hashed: string): boolean => {
  // In a real implementation, this would verify the password
  return `hashed_${password}` === hashed;
};

// Registration endpoint
router.post("/register", (req: Request, res: Response) => {
  const { email, password, role } = req.body;

  if (!email || !password || !role) {
    return res.status(400).json({ error: "Email, password, and role are required" });
  }

  // Check if user already exists
  const existingUser = users.find(user => user.email === email);
  if (existingUser) {
    return res.status(400).json({ error: "User already exists" });
  }

  // Create new user
  const newUser = {
    id: users.length + 1,
    email,
    password: hashPassword(password),
    role
  };

  users.push(newUser);

  return res.status(201).json({
    id: newUser.id,
    email: newUser.email,
    role: newUser.role
  });
});

// Login endpoint
router.post("/login", (req: Request, res: Response) => {
  const { email, password } = req.body;

  if (!email || !password) {
    return res.status(400).json({ error: "Email and password are required" });
  }

  // Find user
  const user = users.find(u => u.email === email);
  if (!user) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  // Verify password
  if (!verifyPassword(password, user.password)) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  // Return user info (in a real app, this would include a JWT token)
  return res.json({
    id: user.id,
    email: user.email,
    role: user.role
  });
});

// Role-based access control middleware
const requireRole = (requiredRole: string) => {
  return (req: Request, res: Response, next: Function) => {
    // In a real app, this would check the JWT token for user role
    // For now, we'll simulate it with a mock header
    const userRole = req.headers.role as string || "staff";

    if (userRole !== requiredRole) {
      return res.status(403).json({ error: "Insufficient permissions" });
    }

    next();
  };
};

// Protected route example - requires admin role
