    res.json(leads);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch leads" });
  }
});

// GET /leads/:id - Get a specific lead by ID
router.get("/leads/:id", async (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid lead ID" });
    }

    const lead = await leadsDatabase.findById(id);
    if (!lead) {
      return res.status(404).json({ error: "Lead not found" });
    }

    res.json(lead);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch lead" });
  }
});

// POST /leads - Create a new lead
router.post("/leads", async (req: Request, res: Response) => {
  try {
    const { name, email } = req.body;

    if (!name || !email) {
      return res.status(400).json({ error: "Name and email are required" });
    }

    const newLead = await leadsDatabase.create({ name, email });
    res.status(201).json(newLead);
  } catch (error) {
    res.status(500).json({ error: "Failed to create lead" });
  }
});

// PUT /leads/:id - Update a lead
router.put("/leads/:id", async (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid lead ID" });
    }

    const { name, email } = req.body;
    if (!name || !email) {
      return res.status(400).json({ error: "Name and email are required" });
    }

    const updatedLead = await leadsDatabase.update(id, { name, email });
    res.json(updatedLead);
  } catch (error) {
    res.status(500).json({ error: "Failed to update lead" });
  }
});

