export const router = Router();

// Mock data to simulate database operations
let leads = [
  { id: "1", status: "lead", progress: "initial contact" },
  { id: "2", status: "qualified", progress: "proposal sent" },
  { id: "3", status: "contracted", progress: "contract signed" }
];

// GET /status - List all leads
