  res.json(leads);
});

// GET /status/:id - Get a specific lead by ID
router.get("/\:id", (req: Request, res: Response) => {
  const lead = leads.find(l => l.id === req.params.id);
  if (!lead) {
    return res.status(404).json({ error: "Lead not found" });
  }
  res.json(lead);
});

// POST /status - Create a new lead
router.post("/", (req: Request, res: Response) => {
  const { id, status, progress } = req.body;

  if (!id || !status || !progress) {
    return res.status(400).json({ error: "ID, status, and progress are required" });
  }

  const newLead = { id, status, progress };
  leads.push(newLead);

  res.status(201).json(newLead);
});

// PUT /status/:id - Update a lead's status and progress
router.put("/\:id", (req: Request, res: Response) => {
  const leadIndex = leads.findIndex(l => l.id === req.params.id);

  if (leadIndex === -1) {
    return res.status(404).json({ error: "Lead not found" });
  }

  const { status, progress } = req.body;

  if (!status || !progress) {
    return res.status(400).json({ error: "Status and progress are required" });
  }

  leads[leadIndex] = { ...leads[leadIndex], status, progress };

  res.json(leads[leadIndex]);
});

// DELETE /status/:id - Delete a lead
router.delete("/\:id", (req: Request, res: Response) => {
  const leadIndex = leads.findIndex(l => l.id === req.params.id);

  if (leadIndex === -1) {
    return res.status(404).json({ error: "Lead not found" });
  }

  leads.splice(leadIndex, 1);

  res.json({ message: "Lead deleted successfully" });
});

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to specific routes
  const protectedPaths = [/^\/leads(\/|$)/];
  const isProtectedPath = protectedPaths.some(path => path.test(req.path));

  if (!isProtectedPath) {
    next();
    return;
  }

  // Check if user has proper role access
  const userRole = req.headers["x-user-role"] as string | undefined;

  // If no role header, deny access
  if (!userRole) {
    res.status(403).json({ error: "Access denied: Role not specified" });
    return;
  }

  // Define role permissions
  const rolePermissions: Record<string, string[]> = {
    admin: ["GET", "POST", "PUT", "DELETE"],
    sales: ["GET", "POST", "PUT"],
    technician: ["GET", "PUT"]
  };

  const allowedMethods = rolePermissions[userRole] || [];

  // If user's role doesn't allow this method, deny access
  if (!allowedMethods.includes(req.method)) {
    res.status(403).json({ error: "Access denied: Insufficient permissions" });
    return;
  }

  // If we reach here, user has proper role and method access
  next();
}

