import { useState } from "react";

export function WorkOrderForm() {
  const [formData, setFormData] = useState({
    productName: "",
    quantity: "",
    requiredDate: "",
    status: "pending",
    assignedWorker: "",
  });

  const [isSubmitting, setIsSubmitting] = useState(false);
  const [submitSuccess, setSubmitSuccess] = useState(false);
  const [error, setError] = useState<null | string>(null);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    setError(null);
    setSubmitSuccess(false);

    try {
      const response = await fetch("/api/work-orders", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          productName: formData.productName,
          quantity: Number(formData.quantity),
          requiredDate: formData.requiredDate,
          status: formData.status,
          assignedWorker: formData.assignedWorker,
        }),
      });

      if (!response.ok) {
        throw new Error(`Failed to create work order: ${response.status}`);
      }

      setSubmitSuccess(true);
      setFormData({
        productName: "",
        quantity: "",
        requiredDate: "",
        status: "pending",
        assignedWorker: "",
      });
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div style={{
      fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
      maxWidth: 600,
      margin: "0 auto",
      padding: "20px",
    }}>
      <h1 style={{ textAlign: "center" }}>Create New Work Order</h1>

      {submitSuccess && (
        <div style={{
          backgroundColor: "#d4edda",
          color: "#155724",
          padding: "10px",
          borderRadius: "4px",
          marginBottom: "20px",
        }}>
          Work order created successfully!
        </div>
      )}

      {error && (
        <div style={{
          backgroundColor: "#f8d7da",
          color: "#721c24",
          padding: "10px",
          borderRadius: "4px",
          marginBottom: "20px",
        }}>
          {error}
        </div>
      )}

      <form onSubmit={handleSubmit} style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
        <div>
          <label htmlFor="productName" style={{ display: "block", marginBottom: "5px" }}>
            Product Name
          </label>
          <input
            type="text"
            id="productName"
            name="productName"
            value={formData.productName}
            onChange={handleChange}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
            required
          />
        </div>

        <div>
          <label htmlFor="quantity" style={{ display: "block", marginBottom: "5px" }}>
            Quantity
          </label>
          <input
            type="number"
            id="quantity"
            name="quantity"
            value={formData.quantity}
            onChange={handleChange}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
            required
          />
        </div>

        <div>
          <label htmlFor="requiredDate" style={{ display: "block", marginBottom: "5px" }}>
            Required Date
          </label>
          <input
            type="date"
            id="requiredDate"
            name="requiredDate"
            value={formData.requiredDate}
            onChange={handleChange}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
            required
          />
        </div>

        <div>
          <label htmlFor="status" style={{ display: "block", marginBottom: "5px" }}>
            Status
          </label>
          <select
            id="status"
            name="status"
            value={formData.status}
            onChange={handleChange}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
          >
            <option value="pending">Pending</option>
            <option value="in-progress">In Progress</option>
            <option value="completed">Completed</option>
          </select>
        </div>

        <div>
          <label htmlFor="assignedWorker" style={{ display: "block", marginBottom: "5px" }}>
            Assigned Worker
          </label>
          <input
            type="text"
            id="assignedWorker"
            name="assignedWorker"
            value={formData.assignedWorker}
            onChange={handleChange}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
            required
          />
        </div>

        <button
          type="submit"
