                  <td style={{ border: '1px solid #ddd', padding: '12px' }}>{order.assignedWorker}</td>
                </tr>
              ))
            ) : (
              <tr>
                <td colSpan={5} style={{ border: '1px solid #ddd', padding: '12px', textAlign: 'center' }}>
                  No work orders found.
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}

