interface Customer {
  id: number;
  name: string;
  phone: string;
  email: string;
  balance: number;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS customers (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    phone TEXT NOT NULL,
    email TEXT NOT NULL,
    balance REAL NOT NULL DEFAULT 0.0
  );
`;

db.exec(createTableSql);

export function getAllCustomers(): Customer[] {
  const stmt = db.prepare("SELECT * FROM customers");
  return stmt.all() as unknown as Customer[];
}

export function getCustomerById(id: number): Customer | undefined {
  const stmt = db.prepare("SELECT * FROM customers WHERE id = ?");
  return stmt.get(id) as unknown as Customer | undefined;
}

export function insertCustomer(customer: Omit<Customer, "id">): number {
  const stmt = db.prepare(
    "INSERT INTO customers (name, phone, email, balance) VALUES (?, ?, ?, ?)"
  );
  const result = stmt.run(customer.name, customer.phone, customer.email, customer.balance);
  return Number(result.lastInsertRowid);
}

export function updateCustomer(id: number, customer: Partial<Omit<Customer, "id">>): boolean {
  const fields = [];
  const values = [];

  if (customer.name !== undefined) {
    fields.push("name = ?");
    values.push(customer.name);
  }

  if (customer.phone !== undefined) {
    fields.push("phone = ?");
    values.push(customer.phone);
  }

  if (customer.email !== undefined) {
    fields.push("email = ?");
    values.push(customer.email);
  }

  if (customer.balance !== undefined) {
    fields.push("balance = ?");
    values.push(customer.balance);
  }

  if (fields.length === 0) return false;

  values.push(id);

  const sql = `UPDATE customers SET ${fields.join(", ")} WHERE id = ?`;
  const stmt = db.prepare(sql);
  stmt.run(...values);

  return true;
}

export function deleteCustomer(id: number): boolean {
  const stmt = db.prepare("DELETE FROM customers WHERE id = ?");
  const result = stmt.run(id);
  return result.changes > 0;
}

