    const staff = getAllStaff();
    res.json(staff);
  } catch (error) {
    res.status(500).json({ error: "Internal server error" });
  }
});

// Get staff member by ID
router.get("/staff/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid staff ID" });
  }

  const staffMember = getStaffById(id);

  if (!staffMember) {
    return res.status(404).json({ error: "Staff member not found" });
  }

  res.json(staffMember);
});

// Create new staff member
router.post("/staff", (req: Request, res: Response) => {
  const { username, password_hash, role, permissions } = req.body;

  if (!username || !password_hash || !role || !permissions) {
    return res.status(400).json({ error: "All fields are required" });
  }

  try {
    const newId = insertStaff(username, password_hash, role, permissions);
    res.status(201).json({ id: newId, username, role });
  } catch (error) {
    res.status(500).json({ error: "Failed to create staff member" });
  }
});

// Update staff member
router.put("/staff/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { username, password_hash, role, permissions } = req.body;

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid staff ID" });
  }

  if (!username || !password_hash || !role || !permissions) {
    return res.status(400).json({ error: "All fields are required" });
  }

  const existingStaff = getStaffById(id);

  if (!existingStaff) {
    return res.status(404).json({ error: "Staff member not found" });
  }

  try {
    updateStaff(id, username, password_hash, role, permissions);
    res.json({ message: "Staff member updated successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to update staff member" });
  }
});

