});

import { Router, type Request, type Response } from "express";
import {
  getAllCustomers,
  getCustomerById,
  insertCustomer,
  updateCustomer,
  deleteCustomer
} from "../db/customers-table";
import {
  getAllTransactions,
  getTransactionById,
  insertTransaction,
  updateTransaction,
  deleteTransaction
} from "../db/transactions-table";
import {
  getAllMobileOperators,
  getMobileOperatorById,
  insertMobileOperator,
  updateMobileOperator,
  deleteMobileOperator
} from "../db/mobile-operators-table";
import {
  getAllBillTypes,
  getBillTypeById,
  insertBillType,
  updateBillType,
  deleteBillType
} from "../db/bill-types-table";
import {
  getAllStaff,
  getStaffById,
  insertStaff,
  updateStaff,
  deleteStaff
} from "../db/staff-table";

export const router = Router();

// Process mobile recharge transaction
router.post("/recharge", (req: Request, res: Response) => {
  const { customerId, amount, operatorId } = req.body;

  if (!customerId || !amount || !operatorId) {
    return res.status(400).json({ error: "customerId, amount, and operatorId are required" });
  }

  const customer = getCustomerById(Number(customerId));
  if (!customer) {
    return res.status(404).json({ error: "Customer not found" });
  }

  const operator = getMobileOperatorById(Number(operatorId));
  if (!operator) {
    return res.status(404).json({ error: "Mobile operator not found" });
  }

  // Validate balance
  if (customer.balance < Number(amount)) {
    return res.status(400).json({ error: "Insufficient balance" });
  }

  // Deduct amount from customer balance
  const updatedBalance = customer.balance - Number(amount);
  updateCustomer(Number(customerId), { balance: updatedBalance });

  // Create transaction record
  const transactionId = insertTransaction(
    "recharge",
    Number(amount),
    new Date().toISOString(),
    Number(customerId),
    "completed"
  );

  return res.status(201).json({
    message: "Recharge successful",
    transactionId,
    remainingBalance: updatedBalance
  });
});

// Validate operator details
router.get("/operators", (req: Request, res: Response) => {
  const operators = getAllMobileOperators();
  return res.json(operators);
});

// Update customer balance
router.put("/customers/:id/balance", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { amount } = req.body;

  if (!amount) {
    return res.status(400).json({ error: "Amount is required" });
  }

  const customer = getCustomerById(id);
  if (!customer) {
    return res.status(404).json({ error: "Customer not found" });
  }

  const updatedBalance = customer.balance + Number(amount);
  updateCustomer(id, { balance: updatedBalance });

  return res.json({
    message: "Balance updated successfully",
    newBalance: updatedBalance
  });
});

