import { Router, type Request, type Response } from "express";
import {
  getAllTransactions,
  getTransactionById,
  insertTransaction,
  updateTransaction,
  deleteTransaction
} from "../db/transactions-table";
import {
  getAllCustomers,
  getCustomerById
} from "../db/customers-table";
import {
  getAllMobileOperators,
  getMobileOperatorById
} from "../db/mobile-operators-table";
import {
  getAllBillTypes,
  getBillTypeById
} from "../db/bill-types-table";
import {
  getAllStaff,
  getStaffById
} from "../db/staff-table";

export const router = Router();

// Get all transactions
router.get("/", (req: Request, res: Response) => {
  try {
    const transactions = getAllTransactions();
    res.json(transactions);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch transactions" });
  }
});

// Get a transaction by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid transaction ID" });
    }

    const transaction = getTransactionById(id);
    if (!transaction) {
      return res.status(404).json({ error: "Transaction not found" });
    }

    res.json(transaction);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch transaction" });
  }
});

// Create a new transaction
router.post("/", (req: Request, res: Response) => {
  try {
    const { type, amount, date, customerId, status } = req.body;

    // Validate required fields
    if (!type || !amount || !date || !customerId || !status) {
      return res.status(400).json({ error: "Missing required fields" });
    }

    // Validate customer exists
    const customer = getCustomerById(Number(customerId));
    if (!customer) {
      return res.status(404).json({ error: "Customer not found" });
    }

    // Validate mobile operator exists (if applicable)
    if (type === "mobile-recharge") {
      const operator = getMobileOperatorById(1); // Assuming fixed operator for now
      if (!operator) {
        return res.status(404).json({ error: "Mobile operator not found" });
      }
    }

    // Validate bill type exists (if applicable)
    if (type === "bill-payment") {
      const billType = getBillTypeById(1); // Assuming fixed bill type for now
      if (!billType) {
        return res.status(404).json({ error: "Bill type not found" });
      }
    }

    // Validate staff exists (if applicable)
    const staff = getStaffById(1); // Assuming fixed staff for now
    if (!staff) {
      return res.status(404).json({ error: "Staff member not found" });
    }

    const newId = insertTransaction(type, amount, date, customerId, status);

    const newTransaction = getTransactionById(newId);
    if (!newTransaction) {
      return res.status(500).json({ error: "Failed to retrieve created transaction" });
    }

    res.status(201).json(newTransaction);
  } catch (error) {
    res.status(500).json({ error: "Failed to create transaction" });
  }
});

// Update a transaction
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid transaction ID" });
    }

    const { type, amount, date, customerId, status } = req.body;

    // Validate required fields
    if (!type || !amount || !date || !customerId || !status) {
      return res.status(400).json({ error: "Missing required fields" });
    }

    // Check if transaction exists
    const existingTransaction = getTransactionById(id);
    if (!existingTransaction) {
      return res.status(404).json({ error: "Transaction not found" });
    }

    // Validate customer exists
    const customer = getCustomerById(Number(customerId));
    if (!customer) {
      return res.status(404).json({ error: "Customer not found" });
    }

    // Validate mobile operator exists (if applicable)
    if (type === "mobile-recharge") {
      const operator = getMobileOperatorById(1); // Assuming fixed operator for now
      if (!operator) {
        return res.status(404).json({ error: "Mobile operator not found" });
      }
    }

    // Validate bill type exists (if applicable)
