import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";
import { router as authRouter } from "../routes/authentication-service";
import { router as rechargeRouter } from "../routes/recharge-service";
import { router as billRouter } from "../routes/bill-service";
import { router as customerRouter } from "../routes/customer-service";
import { router as transactionRouter } from "../routes/transaction-service";

const JWT_SECRET = process.env.JWT_SECRET;

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process requests to protected routes
  const protectedPaths = [
    authRouter,
    rechargeRouter,
    billRouter,
    customerRouter,
    transactionRouter
  ];

  // Skip session management for non-protected routes
  if (!req.path.startsWith('/api/')) {
    next();
    return;
  }

  // Check for authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    res.status(401).json({ error: 'Unauthorized: Missing or invalid token' });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '

  // Validate token signature
  if (!JWT_SECRET) {
    res.status(500).json({ error: 'Server configuration error: JWT_SECRET not set' });
    return;
  }

  try {
    const [payload, signature] = token.split('.');
    if (!payload || !signature) {
      res.status(401).json({ error: 'Unauthorized: Invalid token format' });
      return;
    }

    const expectedSignature = createHmac('sha256', JWT_SECRET)
      .update(payload)
      .digest('base64url');

    const expectedBuffer = Buffer.from(expectedSignature, 'base64url');
    const actualBuffer = Buffer.from(signature, 'base64url');

    if (!timingSafeEqual(expectedBuffer, actualBuffer)) {
      res.status(401).json({ error: 'Unauthorized: Invalid token signature' });
      return;
    }

    // Token is valid, proceed
    next();
  } catch (error) {
    res.status(401).json({ error: 'Unauthorized: Invalid token' });
  }
}

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";
import { router as authRouter } from "../routes/authentication-service";
import { router as rechargeRouter } from "../routes/recharge-service";
import { router as billRouter } from "../routes/bill-service";
import { router as customerRouter } from "../routes/customer-service";
import { router as transactionRouter } from "../routes/transaction-service";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Skip validation for authentication routes
  if (req.path.startsWith("/auth") || 
      req.path.startsWith("/login") ||
      req.path.startsWith("/register")) {
    return next();
  }

  // Only apply role-based access control to POST, PUT, DELETE requests
  if (req.method !== "POST" && req.method !== "PUT" && req.method !== "DELETE") {
    return next();
  }

  // Check if the request is for protected routes
  const protectedPaths = [
    "/recharge", "/bill", "/customer", "/transaction"
  ];

  const isProtectedPath = protectedPaths.some(path => 
    req.path.startsWith(path)
  );

  if (!isProtectedPath) {
    return next();
  }

  // Get token from headers
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return res.status(401).json({ message: "Unauthorized" });
  }

  const token = authHeader.substring(7);

  // Validate token format
  const parts = token.split(".");
  if (parts.length !== 3) {
    return res.status(401).json({ message: "Invalid token format" });
  }

  // Check if JWT_SECRET is set
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    return res.status(500).json({ message: "Server configuration error" });
  }

  // Verify token signature
  const [header, payload, signature] = parts;
  const expectedSignature = createHmac("sha256", secret)
    .update(`${header}.${payload}`)
    .digest("base64url");

  try {
    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      return res.status(401).json({ message: "Invalid token" });
    }
  } catch (err) {
    return res.status(401).json({ message: "Invalid token" });
  }

  // Decode payload to get user role
  try {
    const payloadStr = Buffer.from(payload, "base64url").toString();
    const payloadObj = JSON.parse(payloadStr);
    const userRole = payloadObj.role;

    if (!userRole) {
      return res.status(403).json({ message: "Insufficient permissions" });
    }

    // Define required roles for different actions
    const requiredRoles: Record<string, string[]> = {
      "/recharge": ["admin", "operator"],
      "/bill": ["admin", "operator"],
      "/customer": ["admin", "operator"],
      "/transaction": ["admin", "operator"]
    };

    let hasPermission = false;
    for (const [path, roles] of Object.entries(requiredRoles)) {
      if (req.path.startsWith(path)) {
        hasPermission = roles.includes(userRole);
        break;
      }
    }

    if (!hasPermission) {
      return res.status(403).json({ message: "Insufficient permissions" });
    }

    next();
  } catch (err) {
    return res.status(401).json({ message: "Invalid token" });
  }
}

