  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: name === "accountBalance" ? Number(value) : value,
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch("/api/customer-service/customers", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(formData),
      });

      if (!response.ok) {
        throw new Error(`Failed to add customer: ${response.status}`);
      }

      // Reset form and refresh data
      setFormData({ name: "", phoneNumber: "", accountBalance: 0 });
      fetchCustomers();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleUpdate = async (id: number) => {
    try {
      const response = await fetch(`/api/customer-service/customers/${id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(formData),
      });

      if (!response.ok) {
        throw new Error(`Failed to update customer: ${response.status}`);
      }

      // Reset form and refresh data
      setEditingId(null);
      setFormData({ name: "", phoneNumber: "", accountBalance: 0 });
      fetchCustomers();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleDelete = async (id: number) => {
    try {
      const response = await fetch(`/api/customer-service/customers/${id}`, {
        method: "DELETE",
      });

      if (!response.ok) {
        throw new Error(`Failed to delete customer: ${response.status}`);
      }

      fetchCustomers();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const startEdit = (customer: Customer) => {
    setFormData({
      name: customer.name,
      phoneNumber: customer.phoneNumber,
      accountBalance: customer.accountBalance,
    });
    setEditingId(customer.id);
  };

  const cancelEdit = () => {
    setEditingId(null);
    setFormData({ name: "", phoneNumber: "", accountBalance: 0 });
  };

  if (loading) return <div style={{ textAlign: "center" }}>Loading...</div>;

  if (error) return <div style={{ color: "red", textAlign: "center" }}>{error}</div>;

  return (
    <div style={styles.container}>
      <h1 style={styles.title}>Customer Management</h1>

      <form onSubmit={handleSubmit} style={styles.form}>
        <input
          type="text"
          name="name"
          placeholder="Name"
          value={formData.name}
          onChange={handleInputChange}
          style={styles.input}
          required
        />
        <input
          type="tel"
          name="phoneNumber"
          placeholder="Phone Number"
          value={formData.phoneNumber}
          onChange={handleInputChange}
          style={styles.input}
          required
        />
        <input
          type="number"
          name="accountBalance"
          placeholder="Account Balance"
          value={formData.accountBalance}
          onChange={handleInputChange}
          style={styles.input}
          required
        />
        <button type="submit" style={styles.button}>Add Customer</button>
      </form>

      {editingId !== null && (
        <div style={styles.editForm}>
          <h2>Edit Customer</h2>
          <form onSubmit={(e) => {
            e.preventDefault();
            handleUpdate(editingId);
          }}>
            <input
              type="text"
              name="name"
              placeholder="Name"
              value={formData.name}
              onChange={handleInputChange}
              style={styles.input}
              required
            />
            <input
              type="tel"
              name="phoneNumber"
              placeholder="Phone Number"
              value={formData.phoneNumber}
              onChange={handleInputChange}
              style={styles.input}
              required
            />
            <input
              type="number"
              name="accountBalance"
              placeholder="Account Balance"
              value={formData.accountBalance}
              onChange={handleInputChange}
              style={styles.input}
              required
            />
            <button type="submit" style={styles.button}>Update Customer</button>
            <button type="button" onClick={cancelEdit} style={styles.cancelButton}>Cancel</button>
          </form>
        </div>
      )}

      <div style={styles.customerList}>
        <h2>Customer List</h2>
        {customers.length === 0 ? (
          <p>No customers found.</p>
        ) : (
          <table style={styles.table}>
            <thead>
              <tr>
                <th>Name</th>
                <th>Phone Number</th>
                <th>Account Balance</th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {customers.map((customer) => (
                <tr key={customer.id}>
                  <td>{customer.name}</td>
                  <td>{customer.phoneNumber}</td>
                  <td>${customer.accountBalance.toFixed(2)}</td>
                  <td>
                    <button 
                      onClick={() => startEdit(customer)}
                      style={styles.actionButton}
                    >
                      Edit
                    </button>
                    <button 
                      onClick={() => handleDelete(customer.id)}
                      style={styles.actionButton}
                    >
                      Delete
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}

