import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";
import { router as authRouter } from "../routes/authentication-service";
import { router as rechargeRouter } from "../routes/recharge-service";
import { router as billRouter } from "../routes/bill-service";
import { router as customerRouter } from "../routes/customer-service";
import { router as transactionRouter } from "../routes/transaction-service";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Skip validation for authentication routes
  if (req.path.startsWith("/auth") || 
      req.path.startsWith("/login") ||
      req.path.startsWith("/register")) {
    return next();
  }

  // Only apply role-based access control to POST, PUT, DELETE requests
  if (req.method !== "POST" && req.method !== "PUT" && req.method !== "DELETE") {
    return next();
  }

  // Check if the request is for protected routes
  const protectedPaths = [
    "/recharge", "/bill", "/customer", "/transaction"
  ];

  const isProtectedPath = protectedPaths.some(path => 
    req.path.startsWith(path)
  );

  if (!isProtectedPath) {
    return next();
  }

  // Get token from headers
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return res.status(401).json({ message: "Unauthorized" });
  }

  const token = authHeader.substring(7);

  // Validate token format
  const parts = token.split(".");
  if (parts.length !== 3) {
    return res.status(401).json({ message: "Invalid token format" });
  }

  // Check if JWT_SECRET is set
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    return res.status(500).json({ message: "Server configuration error" });
  }

  // Verify token signature
  const [header, payload, signature] = parts;
  const expectedSignature = createHmac("sha256", secret)
    .update(`${header}.${payload}`)
    .digest("base64url");

  try {
    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      return res.status(401).json({ message: "Invalid token" });
    }
  } catch (err) {
    return res.status(401).json({ message: "Invalid token" });
  }

  // Decode payload to get user role
  try {
    const payloadStr = Buffer.from(payload, "base64url").toString();
    const payloadObj = JSON.parse(payloadStr);
    const userRole = payloadObj.role;

    if (!userRole) {
      return res.status(403).json({ message: "Insufficient permissions" });
    }

    // Define required roles for different actions
    const requiredRoles: Record<string, string[]> = {
      "/recharge": ["admin", "operator"],
      "/bill": ["admin", "operator"],
      "/customer": ["admin", "operator"],
      "/transaction": ["admin", "operator"]
    };

    let hasPermission = false;
    for (const [path, roles] of Object.entries(requiredRoles)) {
      if (req.path.startsWith(path)) {
        hasPermission = roles.includes(userRole);
        break;
      }
    }

    if (!hasPermission) {
      return res.status(403).json({ message: "Insufficient permissions" });
    }

    next();
  } catch (err) {
    return res.status(401).json({ message: "Invalid token" });
  }
}

import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock user database - in a real app this would be a proper database
const users = [
  { id: 1, username: "admin", password: "password123", role: "administrator" },
  { id: 2, username: "staff1", password: "staffpass", role: "staff" },
  { id: 3, username: "staff2", password: "staffpass2", role: "staff" }
];

// Mock session storage
const sessions = new Map<string, { userId: number; role: string }>();

// Login endpoint
router.post("/login", (req: Request, res: Response) => {
  const { username, password } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: "Username and password are required" });
  }

  const user = users.find(u => u.username === username && u.password === password);

  if (!user) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  // Generate a mock session ID
  const sessionId = `session_${Math.random().toString(36).substr(2, 9)}`;
  sessions.set(sessionId, { userId: user.id, role: user.role });

  res.json({
    sessionId,
    user: { id: user.id, username: user.username, role: user.role }
  });
});

// Session validation middleware
const validateSession = (req: Request, res: Response, next: () => void) => {
  const sessionId = req.headers.authorization?.replace("Bearer ", "") || req.query.sessionId as string;

  if (!sessionId) {
    return res.status(401).json({ error: "No session provided" });
  }

  const session = sessions.get(sessionId);
  if (!session) {
    return res.status(401).json({ error: "Invalid session" });
  }

  (req as any).session = session;
  next();
};

// Role-based access control middleware
const requireRole = (requiredRole: string) => {
  return (req: Request, res: Response, next: () => void) => {
    const session = (req as any).session;
    if (!session || session.role !== requiredRole) {
      return res.status(403).json({ error: "Access denied" });
    }
    next();
  };
};

// Get current user info
router.get("/me", validateSession, (req: Request, res: Response) => {
  const session = (req as any).session;
  const user = users.find(u => u.id === session.userId);

  if (!user) {
    return res.status(404).json({ error: "User not found" });
  }

  res.json({
    id: user.id,
    username: user.username,
    role: user.role
  });
});

// Logout endpoint
router.post("/logout", validateSession, (req: Request, res: Response) => {
  const sessionId = req.headers.authorization?.replace("Bearer ", "") || req.query.sessionId as string;

  if (sessions.has(sessionId)) {
    sessions.delete(sessionId);
    return res.json({ message: "Logged out successfully" });
  }

  res.status(400).json({ error: "Invalid session" });
});

// Staff-only endpoint example
router.get("/staff-dashboard", validateSession, requireRole("staff"), (req: Request, res: Response) => {
  res.json({ message: "Welcome to the staff dashboard" });
});

// Admin-only endpoint example
router.get("/admin-panel", validateSession, requireRole("administrator"), (req: Request, res: Response) => {
  res.json({ message: "Welcome to the admin panel" });
});

import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock database functions - in a real app these would connect to a database
const mockDatabase = {
  participants: [
    { id: 1, name: "Alice Smith", email: "alice@example.com", age: 12 },
    { id: 2, name: "Bob Johnson", email: "bob@example.com", age: 11 }
  ],

  getAllParticipants: (): Promise<any[]> => {
    return Promise.resolve(mockDatabase.participants);
  },

  getParticipantById: (id: number): Promise<any | null> => {
    const participant = mockDatabase.participants.find(p => p.id === id) || null;
    return Promise.resolve(participant);
  },

  createParticipant: (participantData: any): Promise<any> => {
    const newId = Math.max(0, ...mockDatabase.participants.map(p => p.id)) + 1;
    const newParticipant = { ...participantData, id: newId };
    mockDatabase.participants.push(newParticipant);
    return Promise.resolve(newParticipant);
  },

  updateParticipant: (id: number, participantData: any): Promise<any | null> => {
    const index = mockDatabase.participants.findIndex(p => p.id === id);
    if (index === -1) return Promise.resolve(null);

    mockDatabase.participants[index] = { ...mockDatabase.participants[index], ...participantData };
    return Promise.resolve(mockDatabase.participants[index]);
  },

  deleteParticipant: (id: number): Promise<boolean> => {
    const initialLength = mockDatabase.participants.length;
    mockDatabase.participants = mockDatabase.participants.filter(p => p.id !== id);
    return Promise.resolve(mockDatabase.participants.length < initialLength);
  }
};

// Validation helper
const validateParticipant = (data: any): string[] => {
  const errors: string[] = [];

  if (!data.name || typeof data.name !== 'string' || data.name.trim().length === 0) {
    errors.push('Name is required and must be a non-empty string');
  }

  if (!data.email || typeof data.email !== 'string' || !data.email.includes('@')) {
    errors.push('Email is required and must be a valid email address');
  }

  if (typeof data.age !== 'number' || data.age <= 0 || data.age > 100) {
    errors.push('Age is required and must be a positive number between 1 and 100');
  }

  return errors;
};

