export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only handle POST requests to /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  const secret = process.env.JWT_SECRET;
  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // In a real implementation, we would verify the JWT token here
  // For now, we just check that the secret exists
  // This is a placeholder for actual JWT verification logic

  // Simulate token verification (this is just a mock)
  const token = req.headers.authorization?.split(" ")[1];
  if (!token) {
    res.status(401).json({ error: "Missing token" });
    return;
  }

  // Mock verification - in reality, we'd decode and verify the JWT
  try {
    // This is a simplified example - in practice, you'd use a library like jsonwebtoken
    const expectedSignature = createHmac("sha256", secret)
      .update(token.split(".")[0] + "." + token.split(".")[1])
      .digest();

