              id: "2",
              type: "newsletter_sent",
              description: "Weekly newsletter sent",
              timestamp: "2023-05-14T09:15:00Z"
            },
            {
              id: "3",
              type: "unsubscription",
              description: "User unsubscribed",
              timestamp: "2023-05-13T16:45:00Z"
            }
          ]
        };

        setStats(mockStats);
      } catch (err) {
        setError("Failed to load dashboard data");
      } finally {
        setLoading(false);
      }
    };

    fetchStats();
  }, []);

  if (loading) {
    return (
      <div style={{
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        minHeight: "200px",
        fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif"
      }}>
        Loading...
      </div>
    );
  }

  if (error) {
    return (
      <div style={{
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        minHeight: "200px",
        fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif"
      }}>
        {error}
      </div>
    );
  }

  if (!stats) {
    return (
      <div style={{
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        minHeight: "200px",
        fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif"
      }}>
        No data available
      </div>
    );
  }

  return (
    <div style={{
      maxWidth: "800px",
      margin: "0 auto",
      padding: "20px",
      fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif"
    }}>
      <h1 style={{
        textAlign: "center",
        marginBottom: "30px",
        fontSize: "2rem",
        fontWeight: "normal"
      }}>
        Dashboard Overview
      </h1>

      <div style={{
        display: "grid",
        gridTemplateColumns: "repeat(auto-fit, minmax(250px, 1fr))",
        gap: "20px",
        marginBottom: "30px"
      }}>
        <div style={{
          border: "1px solid #ddd",
          borderRadius: "8px",
          padding: "20px",
          textAlign: "center",
          backgroundColor: "#f9f9f9"
        }}>
          <h2 style={{
            margin: "0 0 10px 0",
            fontSize: "1.2rem",
            color: "#333"
          }}>
            Total Subscribers
          </h2>
          <p style={{
            fontSize: "2rem",
            fontWeight: "bold",
            color: "#007bff",
            margin: "0"
          }}>
            {stats.totalSubscribers.toLocaleString()}
          </p>
        </div>

        <div style={{
          border: "1px solid #ddd",
          borderRadius: "8px",
          padding: "20px",
          textAlign: "center",
          backgroundColor: "#f9f9f9"
        }}>
          <h2 style={{
            margin: "0 0 10px 0",
            fontSize: "1.2rem",
            color: "#333"
          }}>
            Active Newsletters
          </h2>
          <p style={{
            fontSize: "2rem",
            fontWeight: "bold",
            color: "#28a745",
            margin: "0"
          }}>
            {stats.activeNewsletters}
          </p>
        </div>
      </div>

      <div style={{
        border: "1px solid #ddd",
        borderRadius: "8px",
        padding: "20px",
        backgroundColor: "#f9f9f9"
      }}>
        <h2 style={{
          margin: "0 0 20px 0",
          fontSize: "1.3rem",
          color: "#333"
        }}>
          Recent Activity
        </h2>

        {stats.recentActivity.length === 0 ? (
          <p style={{
            textAlign: "center",
            fontStyle: "italic",
            color: "#666"
          }}>
            No recent activity
          </p>
        ) : (
          <ul style={{
            listStyle: "none",
            padding: 0,
            margin: 0
          }}>
            {stats.recentActivity.map(activity => (
              <li
                key={activity.id}
                style={{
                  padding: "10px 0",
                  borderBottom: "1px solid #eee",
                  display: "flex",
                  justifyContent: "space-between"
                }}
              >
                <span>{activity.description}</span>
                <span style={{
                  color: "#666",
                  fontSize: "0.9rem"
                }}>
                  {new Date(activity.timestamp).toLocaleDateString()}
                </span>
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
}
